PYBOY_RAM_SIZE = 0x8000


def prune_inactive_stream_position_files(active_envs, root=PROJECT_ROOT):
    """Remove viewer snapshots for worker IDs outside the active topology."""
    active_envs = max(1, int(active_envs))
    removed = []
    for path in Path(root).glob('live_agent_positions.env*.json'):
        match = re.fullmatch(r'live_agent_positions\.env(\d+)\.json', path.name)
        if match is None or int(match.group(1)) < active_envs:
            continue
        try:
            path.unlink()
            removed.append(path.name)
        except FileNotFoundError:
            continue
    return sorted(removed)


class _PrivateRamPyBoy:
    """Transparent PyBoy proxy that never opens the ROM's shared RAM sidecar."""

    def __init__(self):
        self._battery_ram = BytesIO(bytes(PYBOY_RAM_SIZE))
        self._pyboy = PyBoy(
            str(ROM_PATH),
            window='null',
            ram_file=self._battery_ram,
        )

    def __getattr__(self, name):
        return getattr(self._pyboy, name)

    def stop(self, save=True, ram_file=None, rtc_file=None):
        # PyBoy does not retain the constructor's ram_file for stop(); without
        # this explicit stream it silently reopens ``yellow.gb.ram`` itself.
        if save and ram_file is None:
            self._battery_ram.seek(0)
            ram_file = self._battery_ram
        return self._pyboy.stop(save=save, ram_file=ram_file, rtc_file=rtc_file)


def create_pyboy():
    """Create an emulator with process-local, in-memory battery RAM.

    PyBoy otherwise derives ``yellow.gb.ram`` beside the shared ROM. With 96
    workers plus frontier probes, one process can truncate that file while
    another is reading it, which caused the live ``PyBoyAssertException: No
    data`` crash. Savestates contain the runtime machine state we actually
    resume from, so a private zeroed battery-RAM stream is the correct clean
    bootstrap and removes the cross-process filesystem race entirely.
    """
    return _PrivateRamPyBoy()


def swarm_episode_start_path(state_file, is_explorer, explorer_state_path=None):
    """Choose the durable fallback state for a swarm episode.

    This selects the fallback used only when a moving frontier cannot be
    loaded. A configured post-Brock anchor remains safer than replaying
    Pallet for older milestones/configurations.
    """
    if is_explorer and explorer_state_path:
        candidate = Path(explorer_state_path)
        if candidate.is_file():
            return candidate
    return Path(state_file)


def swarm_worker_should_load_frontier(
    swarm_enabled, is_explorer, frontier_exists
):
    """Decide whether a worker should load the shared swarm frontier state.

    By default followers load the current frontier (start at its quest phase).
    To force every worker to start from the base quest (quest phase 0) set the
    environment variable POKEMON_FORCE_START_QUEST_ZERO=1. This is useful when
    debugging or when wanting every env to begin from a clean baseline.
    """
    # Honor an explicit override to always start at quest phase 0.
    if os.environ.get("POKEMON_FORCE_START_QUEST_ZERO") == "1":
        return False
    # Explorer status controls catch-up truncation and frontier publication,
    # not the era of the game explored. Excluding explorers here stranded one
    # eighth of the full-game swarm in Mt. Moon after reaching Celadon.
    del is_explorer
    return bool(swarm_enabled and frontier_exists)


def swarm_worker_is_drill(env_id, drill_fraction):
    """Pin a stable env_id slice as drill workers (default 25% when fraction=0.25)."""
    fraction = float(drill_fraction or 0.0)
    if fraction <= 0:
        return False
    stride = max(1, int(round(1.0 / fraction)))
    return int(env_id) % stride == 0


def swarm_route_runner_skips_novelty(is_drill_worker, drill_fraction):
    """75% proven-route runners are not paid to wander already-solved tiles."""
    return float(drill_fraction or 0.0) > 0.0 and not bool(is_drill_worker)


def swarm_worker_obeys_quest_catchup(is_explorer):
    """Every non-explorer cohort follows an advanced quest frontier.

    Drill workers may explore freely while the frontier remains on their
    current quest, but once that quest is mastered they must join the next
    rotation instead of continuing indefinitely from an obsolete phase.
    """
    return not bool(is_explorer)


def fullgame_quest_completion_log_line(
    env_id, steps, phase_steps, quest_phase, quest_total, completed, next_objective,
    map_id, pos_a, pos_b, is_drill=False,
):
    """Format a split-bearing quest completion record for the viewer."""
    return (
        f"  [QUEST] env_id={int(env_id)} step={int(steps)} "
        f"phase_steps={int(phase_steps)} "
        f"phase={int(quest_phase)}/{int(quest_total)} "
        f"completed={completed} next={next_objective} "
        f"map={int(map_id)} y={int(pos_a)} x={int(pos_b)}"
        f"{' drill' if is_drill else ''}"
    )


def swarm_worker_records_mastery(is_drill_worker, mastery_enabled):
    """Only the stable drill cohort contributes optimization rotations."""
    return bool(mastery_enabled) and bool(is_drill_worker)


def swarm_worker_uses_verified_route_guidance(
    is_drill_worker, mastery_enabled, verified_route=True
):
    """Use solved routes for every worker during the mastery ladder.

    Drill workers still provide the independent timing samples that gate
    promotion. They should not discard collision-proven navigation and spend
    entire rotations rediscovering already completed maps.
    """
    return not bool(is_drill_worker) or (
        bool(mastery_enabled) and bool(verified_route)
    )


def swarm_worker_replays_proven_trace(
    is_drill_worker, is_explorer, mastery_enabled, has_trace
):
    """Apply a recorded successful route to every mastery worker.

    Drill workers own the timing votes, but making them rediscover already
    solved navigation prevents the voters from reaching the finish line. They
    still measure independent emulator episodes; the recorded trace merely
    supplies the same verified route already used by the exploit cohort.
    """
    return bool(
        not is_explorer
        and has_trace
        and swarm_worker_uses_verified_route_guidance(
            is_drill_worker,
            mastery_enabled,
            verified_route=True,
        )
    )


def swarm_mastery_blocks_frontier_publish(is_drill_worker, mastery_enabled):
    """Hold every worker's frontier publish until the current quest is mastered.

    Path-optimization mastery is a swarm-wide gate: no cohort may advance the
    shared frontier past the current quest until the plateau rule passes.
    ``is_drill_worker`` is retained for call-site compatibility only.
    """
    del is_drill_worker
    return bool(mastery_enabled)


def fullgame_frontier_is_postcredits_phase(quest_phase):
    """True only after the Hall of Fame objective has completed.

    ``FULLGAME_ENTER_HALL_OF_FAME_QUEST_PHASE`` is the still-actionable phase
    whose safe frontier belongs in Champions Room.  Treating that phase as
    post-credits pins mastery one quest early and makes every completed worker
    replay the Champion forever.
    """
    return int(quest_phase) > FULLGAME_ENTER_HALL_OF_FAME_QUEST_PHASE


