def vermilion_gym_stand_tiles(can_y, can_x, walkable):
    # Adjacent floor tiles and the facing that looks at the can.
    stands = []
    for ny, nx, face in (
        (can_y + 1, can_x, 0),
        (can_y - 1, can_x, 1),
        (can_y, can_x - 1, 3),
        (can_y, can_x + 1, 2),
    ):
        if (ny, nx) in walkable:
            stands.append((ny, nx, face))
    return tuple(stands)


def gym_bfs_first_action(walkable, start, goals):
    # First cardinal from start toward any goal tile.
    goals = frozenset(goals)
    if start in goals:
        return None
    deltas = ((0, -1, 0), (1, 1, 0), (2, 0, -1), (3, 0, 1))
    seen = {start}
    queue = [(start, None)]
    head = 0
    while head < len(queue):
        (y, x), first = queue[head]
        head += 1
        for action, dy, dx in deltas:
            nxt = (y + dy, x + dx)
            if nxt in seen or nxt not in walkable:
                continue
            seen.add(nxt)
            step = action if first is None else first
            if nxt in goals:
                return step
            queue.append((nxt, step))
    return None

