def _expand_cardinal_route_steps(
    map_id,
    start,
    segments,
    final_destination_map=None,
):
    """Expand compact static-map segments into exact action-guidance tiles."""
    deltas = {0: (-1, 0), 1: (1, 0), 2: (0, -1), 3: (0, 1)}
    total_steps = sum(count for _, count in segments)
    result = []
    y, x = start
    step_index = 0
    for action, count in segments:
        delta_y, delta_x = deltas[action]
        for _ in range(count):
            step_index += 1
            destination = (
                final_destination_map
                if step_index == total_steps
                else None
            )
            result.append((map_id, y, x, action, destination))
            y += delta_y
            x += delta_x
    return tuple(result)


def _reverse_cardinal_route_steps(route_steps, final_state):
    """Reverse a deterministic cardinal route, including map transitions."""
    states = [tuple(step[:3]) for step in route_steps] + [tuple(final_state)]
    opposite = {0: 1, 1: 0, 2: 3, 3: 2}
    result = []
    for index in range(len(route_steps) - 1, -1, -1):
        map_id, y, x = states[index + 1]
        old_map_id, _, _, action, destination = route_steps[index]
        result.append((
            map_id,
            y,
            x,
            opposite[int(action)],
            int(old_map_id) if destination is not None else None,
        ))
    return tuple(result)


