def _early_game_corridor_rules(map_id, width, height, target, blocked=(), **extra):
    """Greedy cardinal nudge toward one tile. Used only on the proven opening."""
    target_y, target_x = (int(target[0]), int(target[1]))
    blocked = frozenset((int(y), int(x)) for y, x in blocked)
    rules = []
    for y in range(int(height)):
        for x in range(int(width)):
            if (y, x) in blocked:
                continue
            dy = target_y - y
            dx = target_x - x
            if dy == 0 and dx == 0:
                continue
            if abs(dy) >= abs(dx):
                action = 0 if dy < 0 else 1
            else:
                action = 2 if dx < 0 else 3
            rules.append({
                'map': int(map_id), 'target': (y, x), 'radius': 0,
                'action': action, 'force_action': True,
                'bonus': 150.0, 'penalty': 20.0,
                # Force the 75% route cohort. Drill workers still see the
                # bonus/penalty so they can try a cheaper corridor.
                'route_workers_only': True,
                **extra,
            })
    return rules


def _forced_route_action_guidance(route_steps, wait_ticks=128, **extra):
    """Expand route steps into forced rules.

    `extra` is merged into every rule, which is how a leg gets a condition --
    `quest_phases=...` to scope it to part of the story, or
    `max_party_hp_fraction=...` so it only fires while the party is hurt.
    """
    return [
        {
            'map': map_id, 'target': (y, x), 'radius': 0,
            'action': action, 'force_action': True,
            'bonus': 150.0, 'penalty': 20.0,
            'verified_route': True,
            **extra,
            **(
                {
                    'destination_map': destination_map,
                    'transition_bonus': 300.0,
                    'wait_ticks': int(wait_ticks),
                }
                if destination_map is not None else {}
            ),
        }
        for map_id, y, x, action, destination_map in route_steps
    ]


def scope_action_guidance(rules, phases):
    """Apply an outer phase scope without widening a rule's own scope.

    A rule that already has ``quest_phases`` is active only in the
    intersection. This matters for composite guidance lists whose individual
    routes intentionally exclude later story phases.
    """
    outer_phases = frozenset(phases)
    return [
        {
            **dict(rule),
            'quest_phases': (
                outer_phases
                if rule.get('quest_phases') is None
                else outer_phases & frozenset(rule['quest_phases'])
            ),
        }
        for rule in rules
    ]



