def silph_card_key_pad_text_is_stale(map_id, quest_phase, pos_a, pos_b,
                                     battle_flag, enemy_hp, text_box=None):
    """Identify the false D730 latch left by the 5F/9F pad reversal."""
    return (
        int(map_id) == 210
        and int(quest_phase) in {
            FULLGAME_SILPH_CARD_KEY_QUEST_PHASE,
            FULLGAME_SILPH_CO_RIVAL_QUEST_PHASE,
        }
        and (int(pos_a), int(pos_b)) == (15, 9)
        and int(battle_flag) == 0
        and int(enemy_hp) == 0
        and not (
            int(quest_phase) == FULLGAME_SILPH_CARD_KEY_QUEST_PHASE
            and (int(pos_a), int(pos_b)) == (15, 9)
            and text_box is not None
            and int(text_box) == 0xFF
        )
    )
