def pokemon_tower_post_rival_forced_action(map_id, quest_phase, pos_a, pos_b):
    """Own the exact post-rival trace even if broad guidance is filtered."""
    if (
        int(map_id) != 143
        or int(quest_phase) != FULLGAME_POKEMON_TOWER_3F_QUEST_PHASE
    ):
        return None
    position = (int(pos_a), int(pos_b))
    for step_map, y, x, action, _ in POKEMON_TOWER_POST_RIVAL_TO_3F_STEPS:
        if int(step_map) == 143 and position == (int(y), int(x)):
            return int(action)
    return None


