def _part11_bike_redeem_guidance(steps):
    return [
        {
            **dict(item),
            "unless_event_bits": tuple(
                dict.fromkeys(
                    tuple(item.get("unless_event_bits") or ())
                    + (EVENT_GOT_BICYCLE,)
                )
            ),
            "require_event_bits": tuple(
                dict.fromkeys(
                    tuple(item.get("require_event_bits") or ())
                    + (EVENT_GOT_BIKE_VOUCHER,)
                )
            ),
        }
        for item in _forced_route_action_guidance(steps, wait_ticks=128)
    ]


