NUGGET_BRIDGE_TRAINER_TILES = frozenset({
    (31, 11), (28, 10), (25, 11), (22, 10), (19, 11), (15, 11),
})


def _nugget_bridge_action(y, x):
    if (y, x) in NUGGET_BRIDGE_TRAINER_TILES or (y - 1, x) in NUGGET_BRIDGE_TRAINER_TILES:
        return 2 if x == 11 else 3
    if y <= 8:
        return 2
    return 0


