def oak_parcel_dialogue_completion_bit(
    quest_phase, map_id, pos_a, pos_b, action_name
):
    """Identify the deterministic Oak dialogue boundary to fast-forward."""
    if int(map_id) != 40 or (int(pos_a), int(pos_b)) != (3, 5):
        return None
    if str(action_name) != 'a':
        return None
    return {
        FULLGAME_DELIVER_OAKS_PARCEL_QUEST_PHASE: 56,
        FULLGAME_RECEIVE_POKEDEX_QUEST_PHASE: 37,
    }.get(int(quest_phase))


def allowed_atomic_frontier_event_bits(
    quest_phase, current_named_event_bits
):
    """Allow inseparable story flags belonging to the immediately next quest.

    Yellow sets Oak's parcel and Pokédex flags on the same script tick.  A
    phase-7 frontier therefore cannot exist with only the parcel flag set.
    Keep this exception exact so unrelated out-of-order events remain blocked.
    """
    bits = {int(bit) for bit in current_named_event_bits}
    allowed = set()
    if (
        int(quest_phase) == FULLGAME_RECEIVE_POKEDEX_QUEST_PHASE
        and {56, 37} <= bits
    ):
        allowed.add(37)
    # Route 12 Snorlax sits on the only southbound coast. The soul-marsh
    # grind is on Route 15, so the fight is won during those phases -- before
    # the named `beat_route12_snorlax` waypoint. Cycling Road is optional
    # once the Bicycle is owned and is not required to make this durable.
    if (
        int(quest_phase) in (
            FULLGAME_SOUL_MARSH_GRIND_PHASES
            | {
                FULLGAME_LAVENDER_FUCHSIA_QUEST_PHASE,
                FULLGAME_ROUTE12_SNORLAX_QUEST_PHASE,
            }
        )
        and EVENT_BEAT_ROUTE12_SNORLAX in bits
    ):
        allowed.add(EVENT_BEAT_ROUTE12_SNORLAX)
    # Koga is reachable during the soul/marsh grind, and his final Pokemon can
    # be the battle that crosses the next level threshold. The XP gain and
    # EVENT_BEAT_KOGA are written by the same battle, so rejecting the flag
    # also rejects the only promotable level frontier and causes endless Koga
    # replays. Keep the exception scoped to these grind phases.
    if (
        int(quest_phase) in FULLGAME_SOUL_MARSH_GRIND_PHASES
        and EVENT_BEAT_KOGA in bits
    ):
        allowed.add(EVENT_BEAT_KOGA)
    return allowed
