def cerulean_post_heal_exit_action(map_id, pos_a, pos_b, quest_phase,
                                    step_index):
    """Break Nurse Joy's closing-text loop before resuming the route.

    Yellow's stale D056 battle byte and Nurse Joy's closing text make a single
    battle/text proxy unreliable here. Alternate B (close text without
    reopening it) and Down (leave as soon as movement is released).
    """
    exit_phases = FULLGAME_CERULEAN_GRIND_PHASES | {
        FULLGAME_CERULEAN_GYM_QUEST_PHASE,
        FULLGAME_RETURN_TO_BILLS_HOUSE_QUEST_PHASE,
    }
    if (
        int(map_id) == 64
        and (int(pos_a), int(pos_b)) == (3, 3)
        and int(quest_phase) in exit_phases
    ):
        return 'b' if int(step_index) % 2 == 0 else 'down'
    return None


def pewter_post_heal_gym_exit_action(map_id, pos_a, pos_b, quest_phase,
                                      text_box, step_index):
    """Release Joy's closing dialogue along the phase-29 Center exit.

    The completed route correctly walks south from (3,3), but D730 can stay
    at 1 after healing and swallow the forced Down.  Alternate B with Down
    only while that latch is present and only on the Center's exit column.
    """
    if (
        int(map_id) == 58
        and int(quest_phase) == FULLGAME_PEWTER_GYM_ENTRY_QUEST_PHASE
        and int(pos_b) == 3
        and 3 <= int(pos_a) <= 7
        and int(text_box) != 0
    ):
        return 'b' if int(step_index) % 2 == 0 else 'down'
    return None


def pewter_center_exit_text_is_stale(map_id, pos_a, pos_b, quest_phase,
                                      battle_flag, text_box,
                                      party_hp_fraction=0.0):
    """Identify D730 after a completed Pewter heal has left stale dialogue.

    Phase 29 enters with its heal already complete.  Phase 31 deliberately
    visits Joy after Brock, so only treat her latch as stale once the party is
    at least 90% healthy.  That preserves the heal while making its handoff to
    the recorded Route 3 exit deterministic.
    """
    phase = int(quest_phase)
    heal_is_complete = (
        phase == FULLGAME_PEWTER_GYM_ENTRY_QUEST_PHASE
        or (
            phase == FULLGAME_ROUTE3_QUEST_PHASE - 1
            and float(party_hp_fraction) >= 0.9
        )
    )
    return bool(
        int(map_id) == 58
        and heal_is_complete
        and int(pos_b) == 3
        and 3 <= int(pos_a) <= 7
        and int(battle_flag) == 0
        and int(text_box) != 0
    )


# Every ordinary Yellow Center in the completed-run map atlas uses Nurse Joy at
# (y=2,x=3), the player interaction tile at (3,3), and the southbound exit
# column x=3.  Keep this centralized: a newly reached Center should inherit the
# same reliable post-heal handoff instead of requiring another city-specific
# exception after it stalls.
POKEMON_CENTER_MAP_IDS = frozenset({
    41,   # Viridian
    58,   # Pewter
    64,   # Cerulean
    68,   # Route 4 / Mt. Moon
    81,   # Route 10 / Rock Tunnel
    89,   # Vermilion
    133,  # Celadon
    141,  # Lavender
    154,  # Fuchsia
    171,  # Cinnabar
    182,  # Saffron
})


def completed_heal_center_exit_action(map_id, pos_a, pos_b, quest_phase,
                                       font_loaded):
    """Finish any explicit heal waypoint and leave its Center safely.

    Heal objectives may advance as soon as SetLastBlackoutMap is durable,
    while Joy's closing page still owns input.  On the immediately following
    quest, press B until real text is gone, then walk the shared exit spine.
    B cannot re-open Joy, unlike A, and Down rejoins each recorded outdoor
    route.  Restricting this to a just-completed ``heal_at_*`` waypoint avoids
    hijacking unrelated Center visits or NPC objectives.
    """
    phase = int(quest_phase)
    if not (0 < phase < len(FULLGAME_QUEST_WAYPOINTS)):
        return None
    previous_name = str(
        FULLGAME_QUEST_WAYPOINTS[phase - 1].get('name', '')
    )
    if not previous_name.startswith('heal_at_'):
        return None
    if (
        int(map_id) not in POKEMON_CENTER_MAP_IDS
        or int(pos_b) != 3
        or not 3 <= int(pos_a) <= 7
    ):
        return None
    if int(font_loaded) != 0:
        return 'b'
    return 'down'


def completed_heal_center_handoff_pending(map_id, pos_a, pos_b, quest_phase):
    """True until a newly completed heal reaches a safe outdoor frontier."""
    return completed_heal_center_exit_action(
        map_id, pos_a, pos_b, quest_phase, 0
    ) is not None


def completed_rock_tunnel_exit_handoff_action(map_id, pos_a, pos_b,
                                               quest_phase):
    """Step south once after the lower Route 10 exit before ending rotation.

    The exit objective completes on Route 10 at (53, 8), directly on the cave
    doorway.  Ending the one-quest rotation from that transition frame lets the
    next policy action walk north and re-enter Rock Tunnel before the frontier
    can be serialized.  Keep the completed rotation alive for one deterministic
    step away from the doorway; (54, 8) is still a valid lower-Route-10
    Lavender frontier.
    """
    if (
        int(quest_phase) == FULLGAME_LAVENDER_QUEST_PHASE
        and int(map_id) == 21
        and (int(pos_a), int(pos_b)) == (53, 8)
    ):
        return 'down'
    return None


def completed_rock_tunnel_exit_handoff_pending(map_id, pos_a, pos_b,
                                                quest_phase):
    """True while the completed cave exit is still on its doorway tile."""
    return completed_rock_tunnel_exit_handoff_action(
        map_id, pos_a, pos_b, quest_phase
    ) is not None


