def route13_water_pocket_action(
    map_id, pos_a, pos_b, quest_phase, same_position_step_count=0,
    battle_flag=0,
):
    """Follow the coherent coast route, yielding to every battle action.

    A trainer's approach and closing text can outlive the raw battle flag.
    Alternate B with the direction only after stalled movement. The Route 15
    late override is restricted to the arrival objective so it cannot pull
    a grinding worker out of the grass or reverse the post-Koga return.
    """
    if int(battle_flag) != 0 or int(quest_phase) not in FULLGAME_PART11_PHASES:
        return None
    if int(map_id) in (26, 184) and int(quest_phase) != FULLGAME_FUCHSIA_QUEST_PHASE:
        return None
    action = COAST_TRANSIT_ACTIONS.get((int(map_id), int(pos_a), int(pos_b)))
    if action is None:
        return None
    stuck = int(same_position_step_count)
    return 'b' if stuck >= 2 and stuck % 2 == 0 else action


def route12_post_snorlax_coast_action(
    map_id, pos_a, pos_b, quest_phase, snorlax_beaten, step_index,
    same_position_step_count=0, battle_flag=0,
):
    """Keep the Route 12 coast moving after Snorlax.

    Cycling Road is optional once the Bicycle is owned. Pret `bg_event 11, 63`
    is the sport-fishing sign. Live 96/96 then sat on (65,14): Down is
    walkable, but Yellow's Pikachu follower plus Part 11 sparse A left
    repeated Downs ignored. B lets the queued step finish, same as Silph 1F.
    """
    if (
        int(battle_flag) != 0
        or int(map_id) != 23
        or not bool(snorlax_beaten)
        or int(quest_phase) not in FULLGAME_PART11_PHASES
    ):
        return None
    pos = (int(pos_a), int(pos_b))
    if pos == (63, 11):
        return 'b' if int(step_index) % 2 == 0 else 'down'
    if (
        int(pos_a) >= 61
        and int(same_position_step_count) >= 2
        and int(same_position_step_count) % 2 == 0
    ):
        return 'b'
    return None


