def callback_calls_for_env_steps(env_steps, n_envs):
    """Convert aggregate environment steps to SB3 callback invocations."""
    return max(1, math.ceil(int(env_steps) / max(1, int(n_envs))))


def quest_phase_stall_limit_for_phase(default_limit, quest_phase):
    """Give high-level Mansion checkpoints enough time to earn a full level."""
    limit = int(default_limit)
    if int(quest_phase) in FULLGAME_MANSION_GRIND_PHASES:
        return max(limit, 16384)
    return limit


def quest_waypoint_matches(waypoint, map_id, pos_a, pos_b, named_events,
                           level=0, badge_count=0, last_blackout_map=None,
                           total_party_hp=None, total_party_max_hp=None,
                           party_move_ids=None, bag_item_ids=None,
                           party_species_levels=None, memory=None,
                           battle_active=None):
    if isinstance(named_events, int):
        named_event_count = named_events
        named_event_bits = set()
    else:
        named_event_bits = set(named_events)
        named_event_count = len(named_event_bits)
    if 'map' in waypoint and int(map_id) != int(waypoint['map']):
        return False
    if 'min_y' in waypoint and int(pos_a) < int(waypoint['min_y']):
        return False
    if 'max_y' in waypoint and int(pos_a) > int(waypoint['max_y']):
        return False
    if 'min_x' in waypoint and int(pos_b) < int(waypoint['min_x']):
        return False
    if 'max_x' in waypoint and int(pos_b) > int(waypoint['max_x']):
        return False
    if (
        'min_named_events' in waypoint
        and named_event_count < int(waypoint['min_named_events'])
    ):
        return False
    if (
        'event_bit' in waypoint
        and int(waypoint['event_bit']) not in named_event_bits
    ):
        return False
    if (
        'any_event_bits' in waypoint
        and not (set(map(int, waypoint['any_event_bits'])) & named_event_bits)
    ):
        return False
    if (
        ('min_level' in waypoint or 'min_party_species_level' in waypoint)
        and memory is not None
        and not party_read_is_plausible(memory)
    ):
        # A striped party block reads level 153 and would clear every
        # remaining grind waypoint on consecutive steps. See
        # party_read_is_plausible -- the flag guards below cannot see it.
        return False
    if 'min_level' in waypoint and int(level) < int(waypoint['min_level']):
        return False
    if (
        ('min_level' in waypoint or 'min_party_species_level' in waypoint)
        and (
            bool(battle_active)
            or (
                memory is not None
                and (
                    int(memory[ADDR_BATTLE_FLAG]) in (1, 2)
                    or int(memory[ADDR_FONT_LOADED]) != 0
                    or int(memory[ADDR_TEXT_BOX]) != 0
                )
            )
        )
    ):
        # XP/levels are awarded on the faint frame, before battle teardown.
        # A battle-active savestate is not a durable grind checkpoint and the
        # one-quest rotation would otherwise terminate before it could publish.
        return False
    if (
        'party_move_id' in waypoint
        and int(waypoint['party_move_id']) not in set(party_move_ids or ())
    ):
        return False
    bag_item_ids = set(map(int, bag_item_ids or ()))
    if (
        'bag_item_id' in waypoint
        and int(waypoint['bag_item_id']) not in bag_item_ids
    ):
        return False
    if (
        'any_bag_item_ids' in waypoint
        and not (set(map(int, waypoint['any_bag_item_ids'])) & bag_item_ids)
    ):
        return False
    species_levels = {
        int(species): int(species_level)
        for species, species_level in (party_species_levels or ())
    }
    if (
        'party_species_id' in waypoint
        and int(waypoint['party_species_id']) not in species_levels
    ):
        return False
    if 'min_party_species_level' in waypoint:
        eligible_species = set(map(int, waypoint.get(
            'party_species_ids', species_levels.keys()
        )))
        if not any(
            species in eligible_species
            and species_level >= int(waypoint['min_party_species_level'])
            for species, species_level in species_levels.items()
        ):
            return False
    if 'status_flag_addr' in waypoint:
        if memory is None:
            return False
        addr = int(waypoint['status_flag_addr'])
        mask = int(waypoint.get('status_flag_mask', 0xFF))
        if int(memory[addr]) & mask != mask:
            return False
    if (
        'min_badges' in waypoint
        and int(badge_count) < int(waypoint['min_badges'])
    ):
        return False
    if (
        'blackout_map' in waypoint
        and (
            last_blackout_map is None
            or int(last_blackout_map) != int(waypoint['blackout_map'])
        )
    ):
        return False
    if waypoint.get('require_full_hp') and (
        total_party_hp is None
        or total_party_max_hp is None
        or int(total_party_max_hp) <= 0
        or int(total_party_hp) < int(total_party_max_hp)
    ):
        return False
    if waypoint.get('require_dialogue_closed') and (
        memory is None or int(memory[ADDR_FONT_LOADED]) != 0
    ):
        return False
    return True


def swarm_progress_key(rank_named_events, named_event_count, quest_phase,
                       route_phase, route_value):
    """Build a frontier key without letting unverified flags outrank quests."""
    event_rank = int(named_event_count) if rank_named_events else 0
    return (
        event_rank,
        int(quest_phase),
        int(route_phase),
        int(route_value),
    )


def fullgame_swarm_subphase_value(quest_phase, route_value, lead_xp):
    """Rank safe level-grind states by earned XP within each level.

    Whole quest phases persist completed levels, but later levels require more
    wild victories than a single episode can reliably finish. Reuse the
    route-value tiebreaker as absolute lead XP during every explicit grind so
    healthy post-battle states can be shared incrementally instead of losing
    an episode's XP on reset.
    """
    if int(quest_phase) in FULLGAME_RNG_GRIND_QUEST_PHASES:
        if int(quest_phase) in FULLGAME_CHARMANDER_GRIND_PHASES:
            # Preserve navigation as a tiebreaker while Charmander is lead.
            return int(lead_xp) * 1000 + int(route_value)
        return int(lead_xp)
    return int(route_value)


def gen1_medium_slow_experience_for_level(level):
    """Return the Generation-I Medium Slow cumulative XP threshold."""
    level = max(1, int(level))
    return max(
        0,
        (6 * level ** 3) // 5 - 15 * level ** 2 + 100 * level - 140,
    )


def repair_charmander_grind_frontier_value(
    quest_phase, stored_value, family_xp, target_level,
):
    """Discard a pre-promotion lead-XP component from Charmander frontiers.

    The phase transition can serialize before Charmander is promoted. Older
    code consequently ranked the snapshot with Pikachu's XP, then every worker
    became "behind" as soon as the next step put Charmander in front. A
    Charmander-grind snapshot cannot legitimately have enough family XP for
    the level after its current objective; use that as a narrow migration
    signature and rebuild only the corrupt XP component.
    """
    value = int(stored_value)
    if (
        int(quest_phase) not in FULLGAME_CHARMANDER_GRIND_PHASES
        or family_xp is None
        or target_level is None
    ):
        return value
    stored_xp, navigation_value = divmod(value, 1000)
    impossible_xp = gen1_medium_slow_experience_for_level(int(target_level) + 1)
    if stored_xp < impossible_xp:
        return value
    return int(family_xp) * 1000 + navigation_value


def fullgame_swarm_route_progress(quest_phase, map_id, route_phase,
                                  route_value):
    """Make an entered Silph state outrank its same-phase outdoor recovery.

    Generic post-Brock routing labels Route 8 as phase 8 and unknown indoor
    maps as phase -1.  That ordering prevented a phase-173 Silph state from
    replacing the regressed Route 8 frontier even after the forced recovery
    succeeded.  Reserve phase 9 for Silph interiors during Silph objectives;
    outdoor states retain their ordinary recovery rank.
    """
    if (
        int(quest_phase) in FULLGAME_SILPH_GRIND_PHASES
        and int(map_id) in {6, 27, 133}
    ):
        # The Silph grind deliberately walks from the Celadon Center through
        # Celadon to the proven Route 16 grass pair. Route 16 (map 27) is not
        # part of the old post-Misty route table, so its generic rank is -1.
        # That made every route worker look eight tiers behind the Center
        # frontier and `swarm_catchup` reset it at step 128, before it could
        # roll an encounter. Keep the whole phase-scoped grind corridor in
        # the already-earned post-Misty tier; the subphase rank below is XP.
        return (8, 0)
    if (
        int(quest_phase) == FULLGAME_MANSION_B1F_QUEST_PHASE
        and int(map_id) in FULLGAME_MANSION_B1F_DESCENT_MAPS
    ):
        # Tie the one-way 3F -> isolated-1F descent at the already-earned 3F
        # rank. B1F itself remains rank 32 and advances the ordered waypoint.
        return (31, 0)
    if (
        int(quest_phase) in (
            FULLGAME_CINNABAR_ROUTE_PHASES | FULLGAME_MANSION_GYM_PHASES
        )
        and int(map_id) in FULLGAME_CINNABAR_ROUTE_ORDER
    ):
        return (FULLGAME_CINNABAR_ROUTE_ORDER[int(map_id)], 0)
    if (
        FULLGAME_SILPH_CO_5F_QUEST_PHASE
        <= int(quest_phase)
        <= FULLGAME_MASTER_BALL_QUEST_PHASE
        and int(map_id) in FULLGAME_SILPH_INTERIOR_MAPS
    ):
        return (9, 0)
    if (
        int(quest_phase) == FULLGAME_HM04_STRENGTH_QUEST_PHASE
        and int(map_id) in FULLGAME_HM04_RETURN_MAPS
    ):
        # The objective begins at Safari rank 24 and walks geographically
        # backward to the Warden. Progress is the eventual HM04 quest phase,
        # not the decreasing map order along this one-way return corridor.
        return (24, 0)
    if (
        int(quest_phase) in FULLGAME_SAFARI_PHASES
        and int(map_id) in FULLGAME_SAFARI_ROUTE_ORDER
    ):
        # Must be checked before the coast branch below: the Safari phases are a
        # subset of PART11, and the coast table would otherwise rank the Gym
        # above the town the worker has to walk back through.
        return (FULLGAME_SAFARI_ROUTE_ORDER[int(map_id)], 0)
    if (
        int(quest_phase) in FULLGAME_SOUL_MARSH_GRIND_PHASES
        and int(map_id) in FULLGAME_SOUL_MARSH_RETURN_MAPS
    ):
        # Koga's Gym is a one-time XP branch off the Route 15 grind. Keep the
        # whole round trip in one route tier so catch-up does not repeatedly
        # reload the Gym frontier while a worker is walking back to grass.
        return (19, 0)
    if (
        int(quest_phase) in FULLGAME_PART11_PHASES
        and int(map_id) in FULLGAME_COAST_TO_FUCHSIA_MAPS
    ):
        # Post-Brock routing knows nothing past Route 8: it ranks Lavender at
        # phase 8 and every coast map as the unknown-map phase -1.  So a worker
        # that actually made progress -- Lavender -> Route 12 -> gate -> coast
        # -- ranked BELOW the Lavender frontier and was truncated as
        # `swarm_catchup` on the next 128-step check, forever.  Live: 1,500+
        # consecutive episodes, avg_ep_length pinned at 128 against a leg that
        # needs ~200 steps, so the swarm could never finish it even once.
        # Ordered by position along the leg rather than flat. Flat also made
        # every coast worker tie with the frontier, and since promotion needs
        # strictly `>` the frontier froze on Route 12 for 12 hours while
        # workers were reaching Fuchsia. See FULLGAME_COAST_ROUTE_ORDER.
        return (FULLGAME_COAST_ROUTE_ORDER[int(map_id)], 0)
    return (int(route_phase), int(route_value))


def should_restore_rock_tunnel_grind_frontier_resources(
    quest_phase, frontier_quest_phase, frontier_subphase_value,
):
    """Keep every serialized level-grind frontier viable.

    Multiple workers can still be finishing branches loaded before the first
    repaired save. Restoring every *saved snapshot* prevents a successful
    level-up at low HP from becoming either unpublishable or the next level's
    fragile shared start. The live worker is restored immediately after
    serialization and receives no battle heal.

    ``quest_phase`` is the candidate's phase *after* completing a waypoint.
    Restore when either the completed phase or the next phase is an explicit
    RNG grind so both the last level in a band and consecutive levels work.
    """
    del frontier_quest_phase, frontier_subphase_value
    phase = int(quest_phase)
    return (
        phase in FULLGAME_RNG_GRIND_QUEST_PHASES
        or phase - 1 in FULLGAME_RNG_GRIND_QUEST_PHASES
        or phase in {
            FULLGAME_ROUTE24_QUEST_PHASE,
            FULLGAME_ROUTE25_QUEST_PHASE,
            FULLGAME_ENTER_BILLS_HOUSE_QUEST_PHASE,
            FULLGAME_ROUTE25_HEAL_QUEST_PHASE,
            FULLGAME_RETURN_TO_BILLS_HOUSE_QUEST_PHASE,
        }
    )


def should_restore_rock_tunnel_traverse_frontier_resources(quest_phase):
    """Heal the serialized snapshot for Rock Tunnel and its combat handoff.

    Deliberately separate from the grind predicate. Resource restoration and
    movement validation are independent: only Route 15's actual two-tile
    encounter patrol accepts either direction; one-way transit routes retain
    their forced-direction proof.

    Only the saved snapshot is healed. The live worker is restored immediately
    after serialization and gets no battle heal, exactly as for the grind.
    """
    phase = int(quest_phase)
    return (
        phase in FULLGAME_ROCK_TUNNEL_INTERIOR_PHASES
        or phase == FULLGAME_LAVENDER_QUEST_PHASE
    )


def should_restore_tower_purification_frontier_resources(quest_phase):
    """Repair the 7F snapshot after the route crossed 5F's healing zone.

    Yellow's 5F script calls HealParty on its four purified-zone tiles, but
    live fast-route replays can leave the party unchanged. A phase-200
    candidate has crossed that mandatory zone and defeated Marowak, so the
    shared 7F snapshot may safely receive the heal that the map script owed.
    """
    return int(quest_phase) == FULLGAME_POKEMON_TOWER_ROCKET_QUEST_PHASE


def should_restore_tower_rival_frontier_resources(quest_phase):
    """Heal only the saved post-rival snapshot before the 3F traversal.

    The mandatory five-Pokemon Tower rival battle reproducibly leaves Pikachu
    at 9% HP. Every worker completes the battle, but the ordinary 40% lead-HP
    floor then rejects phase 195 and reloads phase 194, forcing the same battle
    forever. The next objective is a collision-proven one-way walk to 3F, so
    restore the serialized checkpoint exactly as for other unavoidable trainer
    handoffs; the live worker receives no heal.
    """
    return int(quest_phase) == FULLGAME_POKEMON_TOWER_3F_QUEST_PHASE


def should_restore_silph_giovanni_frontier_resources(quest_phase):
    """Heal the serialized snapshot after Giovanni, before the Master Ball.

    Live 11F candidates beat him at 1-18% lead HP. The next objective is the
    President's gift on the same floor, and mastery rotation ends the episode
    a few clean overworld steps later, so a low-HP win is otherwise discarded
    as `lead_hp<0.40` and Giovanni is refought forever.
    """
    return int(quest_phase) == FULLGAME_MASTER_BALL_QUEST_PHASE


def should_restore_rocket_giovanni_frontier_resources(quest_phase):
    """Heal only the serialized snapshot after Rocket Hideout Giovanni.

    The fresh full-game route reproducibly wins at about 19% lead HP. The
    victory is irreversible, the Silph Scope is collected on the same floor,
    and the next recovery objective is the scripted post-hideout Center heal.
    Preserve that real win while keeping the shared frontier healthy; the live
    worker is restored immediately after serialization and receives no heal.
    """
    return int(quest_phase) == FULLGAME_SILPH_SCOPE_QUEST_PHASE


def should_restore_mt_moon_jj_frontier_resources(quest_phase):
    """Heal the serialized snapshot after Mt Moon Jessie & James.

    Live phase-37 candidates beat them at 2% HP on B2F (map 61, y=4, x=3).
    The 40% floor discarded that win (`lead_hp=0.02<0.40`) while 356/357
    other episodes wiped, so the frontier never left the fight. The next
    objective is walking out of the cave; only the saved snapshot is healed.
    """
    return int(quest_phase) in {
        FULLGAME_JESSIE_JAMES_QUEST_PHASE,
        FULLGAME_MT_MOON_EXIT_QUEST_PHASE,
    }


def should_restore_misty_frontier_resources(quest_phase):
    """Preserve a deterministic low-HP Misty clear for the rival handoff.

    The fresh-pass route wins at 28/73 HP on every worker, just below the 40%
    publication floor. The next objective is another mandatory trainer fight,
    so serialize a healed copy instead of either replaying Misty forever or
    sharing the fragile survivor. The live winning episode remains untouched.
    """
    return int(quest_phase) == FULLGAME_CERULEAN_RIVAL_QUEST_PHASE


def swarm_frontier_required_validation_direction(
    forced_direction, restore_grind_resources, map_id=None,
):
    """Choose the movement proof appropriate for a frontier candidate.

    Story/navigation checkpoints must accept the exact forced route direction;
    that protects the swarm from stale collision views on one-way routes.
    Level-grind checkpoints are different: their forced rules are two-tile
    encounter patrols, so either direction is a valid continuation. Requiring
    the direction selected for one endpoint falsely rejected every level-15
    clear on Route 2 even though the opposite patrol direction was usable.
    """
    if restore_grind_resources and int(map_id) == 26:
        # Route 15 is the demonstrated two-tile Soul/Marsh encounter patrol.
        # Either direction is genuinely usable there. Transit checkpoints on
        # Route 14 must still prove their scripted direction: at (33, 12), Up
        # moves but the required Left is permanently blocked by the trainer,
        # so an any-direction proof shared an unusable phase-224 frontier.
        return None
    return forced_direction


def swarm_frontier_validation_pre_actions(quest_phase, map_id, event_bits):
    """Return genuine dialogue-dismissal inputs needed before movement proof."""
    if (
        int(quest_phase) == FULLGAME_RETURN_ROUTE24_CHARMANDER_QUEST_PHASE
        and int(map_id) == 66
        and EVENT_GOT_BICYCLE in set(map(int, event_bits or ()))
    ):
        # The clerk awards the Bicycle before the final text pages close.
        # Workers honestly reach phase 91 at (3,6), but a direction-only probe
        # rejects that durable state while the completion dialogue owns input.
        return ('b',) * 8
    return ()


def try_acquire_swarm_frontier_write_lock(lock_path, stale_seconds=60.0):
    """Acquire a cross-process writer lock using an atomic directory create."""
    lock_path = Path(lock_path)
    try:
        lock_path.mkdir()
        return True
    except FileExistsError:
        try:
            if time.time() - lock_path.stat().st_mtime <= float(stale_seconds):
                return False
            lock_path.rmdir()
            lock_path.mkdir()
            return True
        except (FileNotFoundError, FileExistsError, OSError):
            return False


def release_swarm_frontier_write_lock(lock_path):
    """Release a directory lock; a missing lock is already released."""
    try:
        Path(lock_path).rmdir()
    except FileNotFoundError:
        pass


SWARM_MASTERY_LOCK_ATTEMPTS = 200
SWARM_MASTERY_LOCK_RETRY_SECONDS = 0.01


def record_swarm_drill_completion(meta_path, completed_phase, steps, window_size=32):
    """Append one drill clear and preserve the phase's all-time best steps.

    The drill cohort finishes short guided objectives almost simultaneously.
    Mastery votes are durable training evidence, so give that burst enough
    time to serialize instead of silently dropping every worker that cannot
    win the directory lock inside the old 80 ms window.
    """
    meta_path = Path(meta_path)
    lock_path = meta_path.with_name(f"{meta_path.name}.write_lock")
    for _lock_try in range(SWARM_MASTERY_LOCK_ATTEMPTS):
        if try_acquire_swarm_frontier_write_lock(lock_path):
            break
        time.sleep(SWARM_MASTERY_LOCK_RETRY_SECONDS)
    else:
        return None
    try:
        payload = {'schema': 2, 'windows': {}, 'best_steps': {}}
        if meta_path.exists():
            try:
                loaded = json.loads(meta_path.read_text(encoding='utf-8'))
                if isinstance(loaded, dict):
                    payload = loaded
            except (OSError, ValueError, TypeError):
                payload = {'schema': 2, 'windows': {}, 'best_steps': {}}
        windows = dict(payload.get('windows') or {})
        best_steps = dict(payload.get('best_steps') or {})
        no_improve_counts = dict(payload.get('no_improve_counts') or {})
        key = str(int(completed_phase))
        samples = [int(value) for value in windows.get(key, [])]
        previous_samples = list(samples)
        samples.append(int(steps))
        samples = samples[-max(1, int(window_size)):]
        windows[key] = samples
        previous_best = best_steps.get(key)
        best_steps[key] = (
            int(steps)
            if previous_best is None
            else min(int(previous_best), int(steps))
        )
        # Plateau progress must survive the rolling window: the window holds
        # only `window_size` clears, which is too few to express an N-rotation
        # plateau once N approaches it. Reset only on a genuine all-time record.
        if previous_best is None:
            no_improve_counts[key] = 0
        elif int(steps) < int(previous_best):
            no_improve_counts[key] = 0
        else:
            try:
                # Seed from the window for phases last recorded before this
                # counter existed, so a live run keeps the plateau progress it
                # already earned instead of restarting from zero on deploy.
                current = int(
                    no_improve_counts[key] if key in no_improve_counts
                    else swarm_mastery_non_improving_streak(previous_samples)
                )
            except (ValueError, TypeError, KeyError):
                current = 0
            no_improve_counts[key] = max(0, current) + 1
        payload = {
            'schema': 2,
            'windows': windows,
            'best_steps': best_steps,
            'no_improve_counts': no_improve_counts,
            'ts': time.time(),
        }
        temp_meta = meta_path.with_name(
            f"{meta_path.stem}.tmp.pid{os.getpid()}.json"
        )
        temp_meta.write_text(json.dumps(payload), encoding='utf-8')
        os.replace(temp_meta, meta_path)
        return samples
    finally:
        release_swarm_frontier_write_lock(lock_path)


def _normalize_proven_navigation_trace(trace, reject_invalid=False):
    """Keep only replay-safe overworld navigation from a successful run.

    Dialogue and battle inputs depend on hidden engine state that is not part
    of the compact route key. Persisting them turned one successful Oak
    conversation into 141 replayed B presses. Interactions remain owned by
    phase-scoped guidance; proven memory is for coordinates and routes.

    Loop-erase repeated replay states as they are encountered. A successful
    trace can contain collisions or exploratory backtracking before the action
    that finally leaves a tile. Keeping every occurrence is not replay-safe:
    the cursor's recovery lookup can rejoin the earlier occurrence forever.
    The final occurrence owns the successful suffix and is therefore the one
    deterministic replay must retain.
    """
    normalized = []
    state_indexes = {}
    for entry in trace or ():
        if not isinstance(entry, (list, tuple)) or len(entry) < 6:
            if reject_invalid:
                return None
            continue
        action = str(entry[5])
        if action not in {'up', 'down', 'left', 'right'}:
            continue
        if int(entry[3]) != 0 or int(entry[4]) != 0:
            continue
        normalized_entry = [
            int(entry[0]), int(entry[1]), int(entry[2]), int(entry[3]),
            int(entry[4]), action,
        ]
        state = tuple(normalized_entry[:5])
        if state in state_indexes:
            loop_start = state_indexes[state]
            for removed in normalized[loop_start:]:
                state_indexes.pop(tuple(removed[:5]), None)
            del normalized[loop_start:]
        state_indexes[state] = len(normalized)
        normalized.append(normalized_entry)
    return normalized


def load_swarm_proven_quest_trace(meta_path, quest_phase):
    """Load replay-safe navigation from the best successful quest trace."""
    try:
        payload = json.loads(Path(meta_path).read_text(encoding='utf-8'))
        route = (payload.get('routes') or {}).get(str(int(quest_phase))) or {}
        trace = route.get('trace') or []
        if not isinstance(trace, list):
            return []
        return _normalize_proven_navigation_trace(trace)
    except (OSError, ValueError, TypeError):
        return []


def fullgame_quest_objective_name(quest_phase):
    """Stable objective identity for stores whose numeric phases can move."""
    phase = int(quest_phase)
    if 0 <= phase < len(FULLGAME_QUEST_WAYPOINTS):
        return str(FULLGAME_QUEST_WAYPOINTS[phase]['name'])
    return None


def remap_swarm_proven_routes_by_objective(meta_path):
    """Move completed routes to new phase numbers after curriculum inserts.

    Route coordinates belong to an objective, not to its incidental list
    index. Deployments annotate the legacy store before changing layouts; this
    remapper then retains every demonstrated trace while level-band objectives
    are inserted ahead of later story beats.
    """
    meta_path = Path(meta_path)
    if not meta_path.exists():
        return []
    lock_path = meta_path.with_name(f"{meta_path.name}.write_lock")
    if not try_acquire_swarm_frontier_write_lock(lock_path):
        return []
    try:
        try:
            payload = json.loads(meta_path.read_text(encoding='utf-8'))
        except (OSError, ValueError, TypeError):
            return []
        routes = dict(payload.get('routes') or {})
        phase_by_name = {
            str(waypoint['name']): index
            for index, waypoint in enumerate(FULLGAME_QUEST_WAYPOINTS)
        }
        # These objectives changed names, but not their demonstrated location
        # or interaction. Keep their atlas seeds instead of letting an old
        # numeric phase collide with an unrelated objective after insertion.
        legacy_objective_aliases = {
            'heal_after_level_25': 'heal_after_level_24',
            'train_pikachu_level_55':
                'train_pikachu_soul_marsh_level_55',
        }
        remapped = {}
        changes = []

        def route_rank(route):
            generated = str(route.get('source', '')) in {
                'completed_run_seed', 'route_atlas_seed',
            }
            return (1 if generated else 0, int(route.get('steps', 10 ** 12)))

        for old_key, raw_route in routes.items():
            route = dict(raw_route or {})
            objective = route.get('objective')
            objective = legacy_objective_aliases.get(objective, objective)
            if objective:
                route['objective'] = objective
            if objective in phase_by_name:
                new_key = str(phase_by_name[str(objective)])
            else:
                new_key = str(old_key)
                try:
                    inferred = fullgame_quest_objective_name(int(new_key))
                except (TypeError, ValueError):
                    inferred = None
                if inferred is not None:
                    route['objective'] = inferred
            prior = remapped.get(new_key)
            if prior is None or route_rank(route) < route_rank(prior):
                remapped[new_key] = route
            if str(old_key) != new_key:
                changes.append((int(old_key), int(new_key), str(objective)))
        if not changes and payload.get('quest_layout') == 'level_bands_v1':
            return []
        backup = meta_path.with_name(
            f"{meta_path.stem}.{time.strftime('%Y%m%d_%H%M%S')}."
            f"pre_level_bands{meta_path.suffix}"
        )
        shutil.copy2(meta_path, backup)
        payload.update({
            'schema': max(2, int(payload.get('schema', 1))),
            'routes': remapped,
            'quest_layout': 'level_bands_v1',
            'ts': time.time(),
        })
        atomic_write_json(meta_path, payload)
        return changes
    finally:
        release_swarm_frontier_write_lock(lock_path)


def proven_quest_trace_action(trace, cursor, state):
    """Return the next proven action when its recorded emulator state matches.

    Search forward so ordinary recovery guidance can rejoin a demonstrated
    route after a transient animation, dialogue, or collision mismatch. Never
    guess an action for a state that was absent from the successful trace.
    """
    state = tuple(int(value) for value in state)
    for index in range(max(0, int(cursor)), len(trace)):
        entry = trace[index]
        if len(entry) >= 6 and tuple(int(value) for value in entry[:5]) == state:
            return str(entry[5]), index + 1
    # A collision, trainer callout, or recovery detour can return the player
    # to a route tile that is earlier than the cursor. The old forward-only
    # lookup then forgot the demonstrated route for the rest of the episode.
    # Rejoin only on an exact recorded emulator state; never invent a greedy
    # direction merely because a waypoint is geometrically nearby.
    matches = [
        index for index, entry in enumerate(trace)
        if len(entry) >= 6
        and tuple(int(value) for value in entry[:5]) == state
    ]
    if matches:
        cursor = max(0, int(cursor))
        index = min(matches, key=lambda item: (abs(item - cursor), item))
        return str(trace[index][5]), index + 1
    return None, int(cursor)


def verified_guidance_route_atlas(
    action_guidance, action_names=FULLGAME_ACTIONS, quest_count=None
):
    """Compile exact movement guidance into per-quest replay traces.

    The completed run is represented throughout this file as emulator-verified
    coordinate rules. Historically those rules and the learned proven-route
    store were separate, so a new mastery quest appeared to have no route
    until it was solved again. Import only unconditional cardinal rules: battle,
    dialogue, HP, item, and event-dependent actions remain with their richer
    guidance handlers.
    """
    atlas = defaultdict(list)
    seen = defaultdict(set)
    conditional_keys = {
        'require_event_bits', 'unless_event_bits',
        'require_bag_item_ids', 'unless_bag_item_ids',
        'min_party_hp_fraction', 'max_party_hp_fraction',
        'min_lead_level',
    }
    for rule in action_guidance or ():
        # `verified_route` marks emulator/BFS replays. Older completed-run
        # sections predate that marker but already use exact radius-0 forced
        # cardinal rules. They are behaviorally route instructions today, so
        # import them too; broad reward-only hints remain excluded.
        if not rule.get('verified_route') and not (
            rule.get('force_action') and int(rule.get('radius', 0)) == 0
        ):
            continue
        if any(key in rule for key in conditional_keys):
            continue
        phases = rule.get('quest_phases')
        target = rule.get('target')
        action = rule.get('action')
        if phases is None or not isinstance(target, (list, tuple)) or len(target) != 2:
            continue
        if isinstance(action, bool):
            continue
        if isinstance(action, int):
            if not 0 <= action < min(4, len(action_names)):
                continue
            action_name = str(action_names[action])
        else:
            action_name = str(action)
        if action_name not in {'up', 'down', 'left', 'right'}:
            continue
        entry = [
            int(rule['map']), int(target[0]), int(target[1]),
            0, 0, action_name,
        ]
        for phase in phases:
            phase = int(phase)
            if quest_count is not None and not 0 <= phase < int(quest_count):
                continue
            key = tuple(entry)
            if key in seen[phase]:
                continue
            seen[phase].add(key)
            atlas[phase].append(list(entry))
    return dict(atlas)


def fullgame_automation_coverage_report(
    quest_waypoints, action_guidance, proven_routes_payload=None,
    active_guidance_phases=None, recovery_guidance=None,
):
    """Describe route evidence for every objective in the active layout.

    This is deliberately computed from the final runtime guidance list, after
    all phase scoping and completed-run atlas seeding. It makes curriculum
    insertions auditable and, most importantly, identifies any RNG grind that
    lacks both an exact patrol/approach and a previously completed trace.
    """
    active_guidance_phases = (
        None if active_guidance_phases is None
        else frozenset(map(int, active_guidance_phases))
    )
    guidance_counts = Counter()
    for rule in action_guidance or ():
        if not isinstance(rule, dict) or not rule.get('force_action'):
            continue
        target = rule.get('target')
        phases = rule.get('quest_phases')
        if not isinstance(target, (tuple, list)) or len(target) != 2:
            continue
        if phases is None:
            continue
        try:
            for phase in phases:
                phase = int(phase)
                if active_guidance_phases is None or phase in active_guidance_phases:
                    guidance_counts[phase] += 1
        except TypeError:
            continue
    routes = dict((proven_routes_payload or {}).get('routes') or {})
    recovery_counts = Counter()
    for rule in recovery_guidance or ():
        for phase in rule.get('quest_phases') or ():
            recovery_counts[int(phase)] += 1
    objectives = []
    missing_grinds = []
    for phase, waypoint in enumerate(quest_waypoints):
        route = routes.get(str(phase)) or {}
        row = {
            'phase': int(phase),
            'objective': str(waypoint.get('name', phase)),
            'rng_grind': phase in FULLGAME_RNG_GRIND_QUEST_PHASES,
            'guidance_rules': int(guidance_counts.get(phase, 0)),
            'recovery_guidance_rules': int(recovery_counts.get(phase, 0)),
            'proven_route': bool(route.get('trace')),
            'route_source': route.get('source'),
        }
        row['accounted'] = bool(
            row['guidance_rules']
            or row['proven_route']
            or row['recovery_guidance_rules']
        )
        if row['rng_grind'] and not row['accounted']:
            missing_grinds.append(int(phase))
        objectives.append(row)
    return {
        'schema': 1,
        'quest_count': len(objectives),
        'accounted_count': sum(bool(row['accounted']) for row in objectives),
        'rng_grind_count': sum(bool(row['rng_grind']) for row in objectives),
        'missing_rng_grind_phases': missing_grinds,
        'objectives': objectives,
        'ts': time.time(),
    }


def completed_run_recording_guidance(recording_path, quest_phases):
    """Compile unambiguous walked moves from a completed-run JSONL recording.

    Only clean overworld state changes whose held cardinal input actually
    moved one tile (or crossed a map boundary) are retained. Coordinates seen
    with conflicting directions are discarded, making this a conservative
    recovery atlas rather than a transcription of exploratory mistakes.
    """
    recording_path = Path(recording_path)
    if not recording_path.exists():
        return []
    action_index = {'up': 0, 'down': 1, 'left': 2, 'right': 3}
    observed = defaultdict(set)
    destinations = defaultdict(set)
    try:
        with recording_path.open(encoding='utf-8') as handle:
            for line in handle:
                try:
                    event = json.loads(line)
                except (ValueError, TypeError):
                    continue
                if event.get('event_type') != 'state_change':
                    continue
                held = [
                    button for button in event.get('held_buttons') or ()
                    if button in action_index
                ]
                if len(held) != 1:
                    continue
                before = event.get('previous_state') or {}
                after = event.get('state') or {}
                try:
                    before_pos = (
                        int(before['map_id']), int(before['y']), int(before['x'])
                    )
                    after_pos = (
                        int(after['map_id']), int(after['y']), int(after['x'])
                    )
                except (KeyError, TypeError, ValueError):
                    continue
                direction = held[0]
                changed_map = before_pos[0] != after_pos[0]
                dy = after_pos[1] - before_pos[1]
                dx = after_pos[2] - before_pos[2]
                # The manual recorder's battle/text fields can remain stale
                # for thousands of frames.  A matching one-tile displacement
                # is stronger proof that this was a real overworld input.
                moved_as_pressed = changed_map or {
                    'up': (dy, dx) == (-1, 0),
                    'down': (dy, dx) == (1, 0),
                    'left': (dy, dx) == (0, -1),
                    'right': (dy, dx) == (0, 1),
                }[direction]
                if not moved_as_pressed:
                    continue
                observed[before_pos].add(direction)
                if changed_map:
                    destinations[before_pos].add(after_pos[0])
    except OSError:
        return []
    phases = frozenset(map(int, quest_phases))
    rules = []
    for (map_id, y, x), directions in sorted(observed.items()):
        if len(directions) != 1:
            continue
        direction = next(iter(directions))
        rule = {
            'map': map_id, 'target': (y, x), 'radius': 0,
            'action': action_index[direction],
            'force_action': True, 'verified_route': True,
            'route_workers_only': False,
            'quest_phases': phases,
            'bonus': 0.0, 'penalty': 0.0,
            'completed_run_recovery': True,
        }
        destination_set = destinations.get((map_id, y, x), set())
        if len(destination_set) == 1:
            rule['destination_map'] = next(iter(destination_set))
            rule['wait_ticks'] = 128
        rules.append(rule)
    return rules


def seed_swarm_proven_routes_from_guidance(
    meta_path, action_guidance, quest_count=None
):
    """Seed missing quest routes without replacing real faster completions."""
    atlas = verified_guidance_route_atlas(
        action_guidance, quest_count=quest_count
    )
    if not atlas:
        return []
    meta_path = Path(meta_path)
    lock_path = meta_path.with_name(f"{meta_path.name}.write_lock")
    if not try_acquire_swarm_frontier_write_lock(lock_path):
        return []
    try:
        payload = {'schema': 1, 'routes': {}}
        if meta_path.exists():
            try:
                loaded = json.loads(meta_path.read_text(encoding='utf-8'))
                if isinstance(loaded, dict):
                    payload = loaded
            except (OSError, ValueError, TypeError):
                pass
        routes = dict(payload.get('routes') or {})
        seeded = []
        pruned = False
        if quest_count is not None:
            for key, route in list(routes.items()):
                try:
                    phase = int(key)
                except (TypeError, ValueError):
                    continue
                if (
                    phase >= int(quest_count)
                    and route.get('source') in {
                        'completed_run_seed', 'route_atlas_seed',
                    }
                ):
                    del routes[key]
                    pruned = True
        for phase, trace in sorted(atlas.items()):
            key = str(int(phase))
            prior = routes.get(key) or {}
            # Refresh generated seeds as verified code routes evolve, but a
            # successful worker/drill trace is always more authoritative.
            if prior and prior.get('source') not in {
                'completed_run_seed', 'route_atlas_seed',
            }:
                continue
            normalized = _normalize_proven_navigation_trace(trace)
            if not normalized:
                continue
            if prior.get('trace') == normalized:
                continue
            routes[key] = {
                # Any genuine completion replaces this baseline immediately.
                'steps': 10 ** 12,
                'navigation_steps': len(normalized),
                'source': 'route_atlas_seed',
                'objective': fullgame_quest_objective_name(phase),
                'trace': normalized,
                'ts': time.time(),
            }
            seeded.append(int(phase))
        if not seeded and not pruned:
            return []
        # Preserve migration/layout metadata; this store is shared by route
        # seeding, measured completions, and objective-based phase remapping.
        payload = dict(payload)
        payload.update({
            'schema': max(2, int(payload.get('schema', 1))),
            'routes': routes,
            'ts': time.time(),
        })
        temp_meta = meta_path.with_name(
            f"{meta_path.stem}.tmp.pid{os.getpid()}.json"
        )
        temp_meta.write_text(json.dumps(payload), encoding='utf-8')
        os.replace(temp_meta, meta_path)
        return seeded
    finally:
        release_swarm_frontier_write_lock(lock_path)


def record_swarm_proven_quest_trace(
    meta_path, completed_phase, trace, source='route', completion_steps=None
):
    """Persist replay-safe navigation when total completion time improves."""
    normalized = _normalize_proven_navigation_trace(
        trace, reject_invalid=True
    )
    if not normalized:
        return False
    completed_in = (
        len(trace) if completion_steps is None else int(completion_steps)
    )
    if completed_in < 0:
        return False
    meta_path = Path(meta_path)
    lock_path = meta_path.with_name(f"{meta_path.name}.write_lock")
    if not try_acquire_swarm_frontier_write_lock(lock_path):
        return False
    try:
        payload = {'schema': 1, 'routes': {}}
        if meta_path.exists():
            try:
                loaded = json.loads(meta_path.read_text(encoding='utf-8'))
                if isinstance(loaded, dict):
                    payload = loaded
            except (OSError, ValueError, TypeError):
                pass
        routes = dict(payload.get('routes') or {})
        key = str(int(completed_phase))
        prior = routes.get(key) or {}
        prior_steps = int(prior.get('steps', 10 ** 12))
        if prior_steps <= completed_in:
            return False
        routes[key] = {
            'steps': completed_in,
            'navigation_steps': len(normalized),
            'source': str(source),
            'objective': fullgame_quest_objective_name(completed_phase),
            'trace': normalized,
            'ts': time.time(),
        }
        payload = dict(payload)
        payload.update({
            'schema': max(2, int(payload.get('schema', 1))),
            'routes': routes,
            'ts': time.time(),
        })
        temp_meta = meta_path.with_name(
            f"{meta_path.stem}.tmp.pid{os.getpid()}.json"
        )
        temp_meta.write_text(json.dumps(payload), encoding='utf-8')
        os.replace(temp_meta, meta_path)
        return True
    finally:
        release_swarm_frontier_write_lock(lock_path)


def swarm_required_lead_hp_fraction(configured_fraction, quest_phase):
    """Keep the combat frontier floor except on the post-Surge heal leg.

    Lt. Surge repeatedly leaves Pikachu just below the configured 40% lead
    threshold while the two reserves keep total-party HP safely above its
    independent 40% floor.  The next objective is an immediate Pokémon Center
    visit, so the total-party guard is sufficient for this one travel phase;
    the ordinary lead floor resumes as soon as Nurse Joy heals the party.

    2026-08-08: the Fuchsia arrival phase is the same shape, and the lead floor
    was silently costing the swarm every crossing of the Route 15 gate. Workers
    that get through arrive at step 3,704-4,091 of a 4,096-step episode, almost
    always with a fainted lead after the route's nine trainer fights -- 188
    [FRONTIER_BLOCKED] lines reading `lead_hp=0.00<0.40`. So ~21 successful
    crossings over 26h were all discarded and all 96 workers kept resetting
    behind the gate to re-run it. Being past the gate dominates lead HP here:
    the very next scripted action is the HP-gated Fuchsia Center heal
    (FUCHSIA_HEAL_ACTION_GUIDANCE, active below 0.9), and the independent 40%
    total-party floor still applies, which is what actually guards against
    promoting a fragile frontier.
    """
    phase = int(quest_phase)
    if (
        phase in FULLGAME_RNG_GRIND_QUEST_PHASES
        or phase - 1 in FULLGAME_RNG_GRIND_QUEST_PHASES
    ):
        # Both an incremental-XP candidate within a grind phase and the
        # post-level-up candidate are healed before serialization by
        # should_restore_rock_tunnel_grind_frontier_resources(). Applying the
        # ordinary 40% floor before that repair discarded low-level wins and
        # made workers re-earn the same XP until one happened to finish healthy.
        # The independent party_fainted blocker still rejects an actual wipe.
        return 0.0
    if phase in FULLGAME_ROCK_TUNNEL_INTERIOR_PHASES:
        # Same bargain inside Rock Tunnel: the snapshot is healed by
        # should_restore_rock_tunnel_traverse_frontier_resources(), and there is
        # no Center in the cave to arrive at healthy from. Without this the
        # floor refused every ladder crossing -- 2,016 wipes and two publishes.
        return 0.0
    if phase == FULLGAME_LAVENDER_QUEST_PHASE:
        # The final Rock Tunnel trainer can leave the lead below 40%, while the
        # party as a whole remains healthy.  Lower Route 10 is protected from
        # wild encounters and the next durable recovery is Lavender's Center,
        # so retain the independent whole-party floor but do not throw away the
        # already-proven cave clear solely because the lead is at 26%.
        return 0.0
    if phase == FULLGAME_CERULEAN_RIVAL_QUEST_PHASE:
        # The verified Misty winner is healed only in the serialized frontier;
        # see should_restore_misty_frontier_resources().
        return 0.0
    if phase in {
        FULLGAME_POKEMON_TOWER_6F_QUEST_PHASE,
        FULLGAME_POKEMON_TOWER_7F_QUEST_PHASE,
    }:
        # This candidate has just entered Tower 5F at (9,3). The phase-scoped
        # forced route reaches the real purification pad before the 6F stairs,
        # where _restore_tower_purification_heal() enforces Yellow's HealParty
        # contract. The 6F->7F route deliberately returns through that same pad
        # before Marowak. Live fresh-pass candidates consistently arrive at the
        # two boundaries with 27% and 38% lead HP respectively and were
        # discarded before taking those safe routes. Preserve the completed
        # floor transitions; earlier Tower floors retain the configured lead
        # floor and party_fainted still rejects a total wipe.
        return 0.0
    if phase == FULLGAME_POKEMON_TOWER_3F_QUEST_PHASE:
        # The Tower rival survivor is repaired only in the serialized snapshot
        # by should_restore_tower_rival_frontier_resources(). Live fresh-pass
        # evidence: 48/48 candidates finished at 9% lead HP and were rejected,
        # replaying the five-Pokemon battle 4,785 times without reaching 3F.
        return 0.0
    if phase == FULLGAME_POKEMON_TOWER_ROCKET_QUEST_PHASE:
        # Reaching Tower 7F completes the Marowak leg, but live candidates
        # arrive with as little as 5% lead HP. The serialized snapshot is
        # intentionally healed by
        # should_restore_tower_purification_frontier_resources(), restoring
        # the mandatory 5F purification-zone effect without healing the live
        # worker. Do not reject the candidate before that bounded repair runs;
        # the separate party_fainted blocker still rejects a total wipe.
        return 0.0
    if phase == FULLGAME_SILPH_SCOPE_QUEST_PHASE:
        # Rocket Hideout Giovanni is an irreversible win and the serialized
        # candidate is healed by should_restore_rocket_giovanni_frontier_resources().
        # Live fresh-pass winners arrive at 19% lead HP, so applying the 40%
        # floor before that bounded snapshot repair refights Giovanni forever.
        return 0.0
    if phase in (
        FULLGAME_PEWTER_HEAL_QUEST_PHASE,
        FULLGAME_ROUTE3_QUEST_PHASE - 1,
        FULLGAME_POST_SURGE_HEAL_QUEST_PHASE,
        FULLGAME_POST_ERIKA_HEAL_QUEST_PHASE,
        FULLGAME_FUCHSIA_PRE_GRIND_HEAL_QUEST_PHASE,
        FULLGAME_FUCHSIA_GYM_QUEST_PHASE,
        # 2026-09-05: the beat_koga candidate is published from a healthy
        # phase-231 gym-entry state, but the enter_safari_zone candidate that
        # follows is written the instant Koga falls. Live fresh-pass workers
        # (envs 19/45/18/22/34/7/24/38...) clear Koga in ~700 steps and reach
        # map 157 (11,4) with the lead at 0-8% while reserves hold whole-party
        # HP well above its floor -- every publish was rejected `lead_hp<0.40`
        # and the durable frontier sat at phase 232 for 12+ min while all 48
        # workers were already at 233. Same shape as the Fuchsia pre-grind
        # heal: the next scripted action is the HP-gated Fuchsia Center heal
        # (FUCHSIA_HEAL_ACTION_GUIDANCE, active below 0.9), the Safari Zone
        # itself has no damaging encounters, and the independent whole-party
        # floor plus party_fainted still reject a genuinely dead party.
        FULLGAME_SAFARI_QUEST_PHASE,
        FULLGAME_ROUTE24_QUEST_PHASE,
        FULLGAME_ROUTE25_QUEST_PHASE,
        FULLGAME_ENTER_BILLS_HOUSE_QUEST_PHASE,
        FULLGAME_ROUTE25_HEAL_QUEST_PHASE,
        FULLGAME_REACH_VERMILION_QUEST_PHASE,
        FULLGAME_HEAL_AT_VERMILION_QUEST_PHASE,
        FULLGAME_MASTER_BALL_QUEST_PHASE,
        FULLGAME_INDIGO_PLATEAU_QUEST_PHASE,
        FULLGAME_INDIGO_LOBBY_QUEST_PHASE,
        FULLGAME_HEAL_BEFORE_ELITE_FOUR_QUEST_PHASE,
        FULLGAME_JESSIE_JAMES_QUEST_PHASE,
        FULLGAME_MT_MOON_EXIT_QUEST_PHASE,
        # NOT the Cerulean arrival. Exempting it (tried 2026-08-15) does
        # promote the frontier, but it promotes a state that cannot finish:
        # the crossing arrives POISONED at 6/56, and Gen 1 poison costs 1 HP
        # per 4 overworld steps, so 24 steps of budget does not cover the ~25
        # tiles to Nurse Joy. Workers reached the Cerulean Center and died
        # inside it, 1,529 wipes and zero heals per 100s. The 40% floor is
        # very nearly right here and rejecting 11% is the correct call; the
        # real defect is upstream, where a 41% poisoned Mt Moon exit was
        # published as the crossing's start. That leg needs 24 HP (42.9%):
        # 70 forced steps across Route 4 plus ~25 in Cerulean is 95 steps,
        # and 23 HP only buys 92. It is short by one HP.
        # Indigo is the Fuchsia shape: the next scripted action is Nurse Joy
        # in the lobby (map 174). Live 292 workers reach map 9 (17,9) with
        # lead_hp=0.27 after Route 23 grass and every publish is discarded.
    ):
        return 0.0
    if phase in {
        FULLGAME_BEAT_CHAMPION_QUEST_PHASE,
        FULLGAME_ENTER_HALL_OF_FAME_QUEST_PHASE,
    }:
        # The League's last two durable handoffs are safe with a low lead as
        # long as the party-wide floor still passes.  After Lance, the forced
        # room exit reaches Champions Room without encounters and
        # _prepare_champion_battle_resources() restores full HP/PP before the
        # Rival fight.  After Champion, the Hall-of-Fame publisher already
        # requires EVENT_BEAT_CHAMPION_RIVAL and proves the mandatory map-118
        # transition end to end before sharing the state.  Live phase-301
        # candidates consistently leave Lance at 39% lead HP and were being
        # discarded by the generic 40% lead floor despite subsequently
        # completing Champion.  Keep party_fainted and the independent 40%
        # whole-party floor as the hard safety gates.
        return 0.0
    return float(configured_fraction)


def swarm_required_party_hp_fraction(configured_fraction, quest_phase):
    """Allow safe, alive frontiers to proceed directly to scripted healing.

    The level-10 forest clear can legitimately leave the single-mon party
    below the ordinary 40% safety floor.  Rejecting that alive state traps the
    mastery ladder on the already-cleared forest even though the next route is
    collision-proven and ends at Nurse Joy.  Other phases retain the configured
    whole-party floor.  The same exemption is required immediately after Lt.
    Surge: a verified win can reproducibly leave the party at 44/111 HP
    (39.64%), just below the configured 40% floor, and the next objective is
    the forced Vermilion Center heal.  The separate ``party_fainted`` blocker
    continues to reject an actual wipe.
    """
    phase = int(quest_phase)
    if (
        phase in FULLGAME_RNG_GRIND_QUEST_PHASES
        or phase - 1 in FULLGAME_RNG_GRIND_QUEST_PHASES
    ):
        return 0.0
    if phase in FULLGAME_ROCK_TUNNEL_INTERIOR_PHASES:
        # The snapshot is healed on the way out; see the lead-HP twin. The
        # `party_fainted` blocker still stands, so a worker mid-blackout is
        # never promoted.
        return 0.0
    if phase == FULLGAME_CERULEAN_RIVAL_QUEST_PHASE:
        # All live winners finish at 28/73 HP. Accept the alive candidate so
        # the writer can publish a healed snapshot for the next rival battle.
        return 0.0
    if (
        FULLGAME_POKEMON_TOWER_3F_QUEST_PHASE
        <= phase
        <= FULLGAME_POKEMON_TOWER_ROCKET_QUEST_PHASE
    ):
        # Preserve the rival survivor through the irreversible floor changes
        # and the 6F Marowak leg. Live phase-199 candidates arrive on 6F with
        # 121/305 HP (39.67%, logged as 0.40<0.40), so the historical claim
        # that 5F's purification pad always healed the party is not reliable.
        # The lead remains healthy and the next leg is deterministic; retain
        # the party-wide exemption through the 7F arrival, whose serialized
        # snapshot receives the purification heal below.
        return 0.0
    if phase == FULLGAME_SILPH_SCOPE_QUEST_PHASE:
        # The same serialized-snapshot repair as the lead-HP exemption above.
        # Keep party_fainted as the hard stop, but do not reject an alive
        # Giovanni winner before the shared checkpoint can be healed.
        return 0.0
    if phase in (
        FULLGAME_PEWTER_HEAL_QUEST_PHASE,
        FULLGAME_ROUTE3_QUEST_PHASE - 1,
        FULLGAME_POST_SURGE_HEAL_QUEST_PHASE,
        FULLGAME_ROUTE24_QUEST_PHASE,
        FULLGAME_ROUTE25_QUEST_PHASE,
        FULLGAME_ENTER_BILLS_HOUSE_QUEST_PHASE,
        FULLGAME_ROUTE25_HEAL_QUEST_PHASE,
        FULLGAME_REACH_VERMILION_QUEST_PHASE,
        FULLGAME_HEAL_AT_VERMILION_QUEST_PHASE,
        FULLGAME_MASTER_BALL_QUEST_PHASE,
        FULLGAME_JESSIE_JAMES_QUEST_PHASE,
        FULLGAME_MT_MOON_EXIT_QUEST_PHASE,
    ):
        # The post-Brock survivor is still inside Pewter Gym with a
        # collision-proven, encounter-free route to the Pewter Center. Its
        # phase-scoped guidance visits Joy whenever HP is below 90%, so low HP
        # is safe progress and must not force Brock to be refought forever.
        # Deliberately not the Cerulean arrival -- see
        # swarm_required_lead_hp_fraction: a poisoned 6/56 arrival cannot reach
        # Nurse Joy, so accepting it only moves the stall one quest later.
        return 0.0
    return float(configured_fraction)


def swarm_frontier_meta_is_compatible(meta, required_schema):
    """Reject legacy frontier state when its progress semantics changed."""
    if not isinstance(meta, dict):
        return False
    required_schema = int(required_schema or 0)
    if required_schema <= 0:
        return True
    try:
        return int(meta.get('schema', 0)) == required_schema
    except (TypeError, ValueError):
        return False


def file_sha256(path):
    digest = hashlib.sha256()
    with open(path, 'rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def swarm_frontier_state_matches_meta(state_path, meta):
    """Ensure concurrent workers did not interleave state/meta replacements."""
    expected = meta.get('state_sha256') if isinstance(meta, dict) else None
    if not isinstance(expected, str) or len(expected) != 64:
        return False
    try:
        return file_sha256(state_path) == expected.lower()
    except OSError:
        return False


# wBattleMon (pret/pokeyellow's battle_struct, 29 bytes) is the in-battle
# working copy of the active Pokemon -- separate from the party struct below
# and only re-synced from it at battle start or on a mid-battle move-learn.
# ADDR_ACTIVE_MON_CUR_HP_HI/ADDR_ACTIVE_MON_MAX_HP_HI above already anchor
# this struct (offsets 1 and 15 from its base), which puts the base at
# 0xD013 and its 4-byte Moves/PP fields at 0xD01B and 0xD02C respectively --
# confirmed against a real screenshot of the FIGHT menu showing a move stuck
# at 0/10 PP mid-battle while this project's PP refill was only ever applied
# to the party struct copy (FIRST_PARTY_MOVE_PP_ADDR below), never this one.
