# These pairs were verified against the project's actual save states.
PARTY_CUR_HP_ADDRS = [
    (0xD16B, 0xD16C),
    (0xD197, 0xD198),
    (0xD1C3, 0xD1C4),
    (0xD1EF, 0xD1F0),
    (0xD21B, 0xD21C),
    (0xD247, 0xD248),
]
