# --- Per-episode gates -------------------------------------------------
#
# Every name below latches (set True / counted up) to make something happen
# "once", and is read back through a defaulted getattr. None of them were ever
# cleared, and reset() does not touch them -- so "once per fight" and "once per
# run" were really *once per process*. The first episode an env plays consumes
# the gate; every episode after it silently skips the behaviour.
#
# With 96 envs replaying full runs, that means effectively every run after the
# first was missing these. Measured on the Champion fight: adding pre-fight
# heals + 80 mid-fight heals moved the wipe rate only 83% -> 76%, because ~96%
# of attempts never received them.
#
# Keep these exhaustive: test_per_episode_gates.py re-derives the sticky-gate
# set from the source and fails if a new one is added without being listed
# here (or explicitly allow-listed as a once-per-process log throttle).
BATTLE_ASSIST_ONE_SHOT_FLAGS = (
    '_misty_battle_resources_prepared',
    '_route9_trainer0_handoff_prepared',
    '_mt_moon_jessie_james_resources_prepared',
    '_indigo_plateau_resources_prepared',
    '_surge_battle_resources_prepared',
    '_erika_battle_resources_prepared',
    '_silph_rival_resources_prepared',
    '_silph_giovanni_resources_prepared',
    '_sabrina_resources_prepared',
    '_route22_rival_resources_prepared',
    '_lorelei_agatha_resources_prepared_phase',
    '_bruno_battle_resources_prepared',
    '_lance_battle_resources_prepared',
    '_champion_battle_resources_prepared',
)
BATTLE_ASSIST_HEAL_BUDGETS = (
    '_surge_emergency_heals_used',
    '_brock_emergency_heals_used',
    '_route3_trainer_emergency_heals_used',
    '_route9_trainer0_emergency_heals_used',
    '_route6_trainer_emergency_heals_used',
    '_route10_lower_trainer_emergency_heals_used',
    '_rock_tunnel_first_1f_emergency_heals_used',
    '_rock_tunnel_middle_hiker_emergency_heals_used',
    '_rock_tunnel_final_jrf_emergency_heals_used',
    '_rock_tunnel_hiker_emergency_heals_used',
    '_erika_gym_trainer_emergency_heals_used',
    '_erika_emergency_heals_used',
    '_silph_rival_emergency_heals_used',
    '_silph_giovanni_emergency_heals_used',
    '_sabrina_emergency_heals_used',
    '_route22_rival_emergency_heals_used',
    '_blaine_emergency_heals_used',
    '_earth_emergency_heals_used',
    '_lorelei_agatha_emergency_heals_used',
    '_bruno_emergency_heals_used',
    '_lance_emergency_heals_used',
    '_champion_emergency_heals_used',
)
# Route/progression gates. These are not heals -- they gate a physical action
# the run needs *every* time:
#   _bicycle_selected_for_part11  mounts the bike for Routes 16/17/18. Sticky,
#       only the first run of a process ever rides; the rest walk.
#   _rocket_scope_faced           first visit faces the Rocket, later steps
#       press A. Sticky, a fresh episode skips straight to A without facing.
#   _silph_5f_pad_warp_seen       records that 9F was reached *this run*, and
#       picks Down vs Up on the 5F pad. Sticky, a fresh episode takes Down on
#       a pad it has not actually returned through yet.
PER_EPISODE_PROGRESSION_GATES = (
    '_bicycle_selected_for_part11',
    '_bike_shop_walkout_disabled',
    '_bike_shop_walkout_misses',
    '_rocket_scope_faced',
    '_route22_post_rival_runtime_recovered',
    '_silph_5f_pad_warp_seen',
    '_viridian_gym_exit_recovered',
    '_victory_road_1f_floor_reloaded',
)
# Deliberately NOT reset: one-shot log throttles. Clearing these would
# re-emit the same probe line every episode across 96 envs.
ONCE_PER_PROCESS_LOG_GATES = (
    '_reported_silph_corridor_probe',
    '_reported_silph_pad_probe',
)


class PokemonYellowEnv(gym.Env):
    """Pokemon Yellow training env with per-instance stage config."""
    state_file = START_STATE_PATH
    max_steps = 4096
    milestone_name = "bootstrap"
    milestone_check = None  # lambda mem, mid: bool
    step_penalty = 0.0  # starts at 0 during curriculum, increases in full-game phase
    # Per-milestone shaping: dict of {map_id: (target_y, target_x)} or None
    shaping_targets = None
    post_hit_shaping_targets = None
    reward_cap = None  # max location_reward from MAP_REWARDS (prevents off-path maps rewarding)
    tile_exploration_bonus = 5.0
    map_discovery_bonus = 100.0
    map_step_penalties = None
    full_hp_map_step_penalties = None
    frontier_path = None
    frontier_reward_scale = 0.0
    frontier_segment_span = 1000.0
    frontier_waypoint_span = 100.0
    frontier_action_guidance_bonus = 0.0
    frontier_action_guidance_penalty = 0.0
    zone_bonuses = None
    milestone_hit_bonus = 0.0
    frontier_soft_stall_score = None
    frontier_soft_stall_steps = 0
    frontier_soft_stall_penalty = 0.0
    frontier_stall_steps = 0
    frontier_stall_penalty = 0.0
    frontier_hit_score = None
    action_guidance = None
    action_guidance_requires_overworld = True
    completed_run_recovery_guidance = None
    completed_run_recovery_after_steps = 0
    penalty_exempt_zones = None
    auto_wait_zones = None
    force_a_in_wild_battles = False
    force_a_in_trainer_battles = False
    # Decoupled from force-A: keeps slot-0 loaded with a damaging move + PP
    # whenever in battle, without overriding *when*/*whether* A gets pressed.
    # Addresses a failure mode specific to fine-tuning an already-shaped
    # checkpoint rather than training from scratch (which is what PWhiddy/
    # pokemonred_puffer actually do, and why neither of them needs this): a
    # policy that always had force-A guaranteeing a good move suddenly losing
    # that guarantee can have a run of genuinely unwinnable battles right as
    # it's relearning menu navigation from raw input, which is enough to
    # teach battle-avoidance instead of battle-competence. This does not
    # choose actions for the policy -- it only prevents "the move you'd want
    # to use doesn't work" from being the reason a battle goes badly.
    ensure_battle_move_ready = False
    trainer_battle_action_script = None
    trainer_battle_maps = None
    enemy_hp_battle_proxy_maps = None
    force_a_on_zero_enemy_hp_text = False
    low_hp_retreat_threshold = 0
    low_hp_retreat_shaping_targets = None
    allowed_maps = None
    disallowed_map_penalty = 0.0
    terminate_on_milestone_hit = False
    terminate_after_hit_state_saved = False
    safe_hit_save_maps = None
    safe_hit_min_total_hp = 0
    safe_hit_save_bonus = 0.0
    progress_checkpoint_maps = None
    progress_checkpoint_bonus = 0.0
    restore_party_resources_on_progress_checkpoint = False
    direction_press_ticks = 8
    direction_release_ticks = 16
    button_press_ticks = 8
    button_release_ticks = 16
    battle_direction_press_ticks = None
    battle_direction_release_ticks = None
    battle_button_press_ticks = None
    battle_button_release_ticks = None
    battle_noop_ticks = None
    post_transition_settle_ticks = 0
    load_settle_ticks = 0
    coord_stuck_threshold = 8
    coord_stuck_penalty = 1.0
    same_position_step_limit = 0
    same_position_step_penalty = 0.0
    action_oscillation_penalty = 1.0
    overworld_non_movement_penalty = 0.0
    force_repel = False
    wild_battle_step_penalty = 0.0
    wild_battle_entry_penalty = 0.0
    hp_loss_penalty_scale = 0.0
    wipe_penalty = 0.0
    wipe_progress_max_y_scale = 0.0
    wipe_progress_tiles_scale = 0.0
    wipe_progress_frontier_scale = 0.0
    invalid_party_state_penalty = 0.0
    terminate_on_invalid_party_state = False
    terminate_on_party_wipe = False
    party_size_bonus_scale = 2000.0
    wild_faint_bonus = 0.0
    trainer_battle_entry_bonus = 0.0
    trainer_faint_bonus = 0.0
    trainer_faint_hit_count = 0
    level_up_bonus = 0.0
    battle_a_bonus = 0.0
    battle_direction_penalty = 0.0
