    def _save_latest_hit_state(self):
        milestone_state = latest_hit_state_path(self.milestone_name, self.env_id)
        try:
            with open(milestone_state, 'wb') as f:
                self.pyboy.save_state(f)
            self.latest_hit_state = milestone_state
        except Exception as e:
            print(f"  [ERROR] Failed to save milestone state: {e}")

    def _save_progress_checkpoint(self):
        state_path = Path(self.state_file)
        state_path.parent.mkdir(parents=True, exist_ok=True)
        temp_path = state_path.with_name(
            f"{state_path.stem}.tmp.env{self.env_id}.pid{os.getpid()}{state_path.suffix}"
        )
        try:
            if (
                self.restore_party_resources_on_progress_checkpoint
                and self.milestone_name in PEWTER_STAGE_START_LEVELS
            ):
                _save_repaired_pewter_progress_checkpoint(
                    state_path,
                    self.milestone_name,
                    self.pyboy.memory,
                )
                return
            if self.restore_party_resources_on_progress_checkpoint:
                _heal_party_memory(self.pyboy.memory)
                _restore_party_pp_memory(self.pyboy.memory)
            with open(temp_path, 'wb') as handle:
                self.pyboy.save_state(handle)
            os.replace(temp_path, state_path)
        except Exception as e:
            print(f"  [ERROR] Failed to save progress checkpoint: {e}")
            try:
                if temp_path.exists():
                    temp_path.unlink()
            except OSError:
                pass

    def _post_brock_route_progress_key(self, pos_a, pos_b, map_id):
        key = post_brock_route_progress_key(
            map_id,
            pos_a,
            pos_b,
            self.post_brock_route_phase,
            fossil_chosen=self._has_mt_moon_fossil(),
        )
        self.post_brock_route_phase = max(self.post_brock_route_phase, key[0])
        return key

    def _global_tile_coords(self, map_id, pos_a, pos_b):
        """Local (map_id, y, x) -> global tile coords, matching the same
        per-map offset table pokemon_yellow_map_viewer.html's JS uses to
        place markers -- so the heatmap bonus below looks itself up in
        exactly the same coordinate space the viewer renders."""
        offset = MAP_OFFSET_TABLE.get(str(map_id))
        if offset is None:
            return None
        return (pos_b + offset[0], pos_a + offset[1])

    def _maybe_reload_heatmap(self):
        if self.steps - self._heatmap_last_check_step < self.heatmap_reward_check_interval:
            return
        self._heatmap_last_check_step = self.steps
        try:
            data = json.loads(VIEWER_HEATMAP_PATH.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return
        counts = {}
        for env_tiles in data.get("by_env", {}).values():
            # 2026-07-26: map_viewer_server.py's tile entries grew a 4th
            # element (last-visit timestamp, for the dashboard's heatmap
            # decay/fade feature) -- this reader only ever needs the first
            # three, so slice instead of an exact-3 unpack. The exact
            # unpack crash-looped the whole trainer (every worker hit this
            # on its next _maybe_reload_heatmap call) from the moment the
            # viewer's format changed until this fix landed.
            for x, y, count in (tile[:3] for tile in env_tiles):
                key = (x, y)
                counts[key] = counts.get(key, 0) + int(count)
        self._heatmap_counts = counts

    def _forced_direction_name(self, map_id, pos_a, pos_b):
        """Button name the route forces on this tile, or None if unguided."""
        index = self._matching_forced_action_guidance(
            int(map_id), int(pos_a), int(pos_b), 0,
            consume_face_action=False,
        )
        if index is None or not (0 <= int(index) < len(self.actions)):
            return None
        name = self.actions[int(index)]
        return name if name in ('up', 'down', 'left', 'right') else None

    def _swarm_sync(self):
        """Go-Explore-style leader sync across the whole swarm of workers.

        Progress is a (named_event_bits, quest_phase, route_phase,
        route_value) tuple (see
        _post_brock_route_progress_key), compared lexicographically so event-flag bits
        (ROM-native, monotonic -- see ADDR_EVENT_FLAGS_START) always
        dominate, with Route 4 progress as a tiebreaker/secondary axis. This
        second axis exists because event flags alone missed real progress
        that was actually happening: with 96 workers running, some
        independently pushed far across Route 4 while the rest sat
        clustered near the start -- none of that showed up as event-flag
        progress (walking doesn't set story flags), so the swarm never
        recognized the leaders as worth pulling the rest toward. Read from a
        small shared JSON file so every worker (separate OS process) can
        compare against it cheaply. A worker ahead of the recorded frontier
        saves its state as the new shared frontier. A worker meaningfully
        behind it (on either axis) signals that it should truncate now so
        its next reset() picks up the frontier state instead of continuing
        to grind through already-solved ground.
        """
        # When PPO reward is restricted to catalogued events, the swarm must
        # use the exact same honest signal. Raw wEventFlags contains transient
        # and unnamed bits that previously promoted bogus early-game leaders.
        if self.reward_named_event_flags_only:
            current_named_event_bits = self._current_rewardable_named_event_bits()
            own_event_bits = len(current_named_event_bits)
        else:
            current_named_event_bits = set()
            own_event_bits = self._count_event_flag_bits()
        unverified_frontier_bits = set()
        if self.reward_ordered_quest_event_flags_only:
            ordered_quest_event_bits = {
                int(waypoint['event_bit'])
                for waypoint in self.quest_waypoints
                if 'event_bit' in waypoint
            }
            ordered_quest_event_bits.update(
                int(bit)
                for waypoint in self.quest_waypoints
                for bit in waypoint.get('any_event_bits', ())
            )
            unverified_frontier_bits = (
                current_named_event_bits
                & ordered_quest_event_bits
                - self.base_named_event_flags
                - self.rewarded_named_event_flags
            )
            unverified_frontier_bits -= allowed_atomic_frontier_event_bits(
                self.quest_phase, current_named_event_bits
            )
            newly_rejected = (
                unverified_frontier_bits
                - self._reported_unverified_frontier_bits
            )
            if newly_rejected:
                names = ", ".join(
                    sorted(event_flag_name(bit) for bit in newly_rejected)
                )
                print(
                    f"  [FRONTIER_REJECT] env_id={self.env_id} step={self.steps} "
                    f"unverified_out_of_order_events={names}",
                    flush=True,
                )
                self._reported_unverified_frontier_bits.update(newly_rejected)
        own_map_id = int(self.pyboy.memory[ADDR_MAP_ID])
        own_pos_a = int(self.pyboy.memory[ADDR_POS_A])
        own_pos_b = int(self.pyboy.memory[ADDR_POS_B])
        own_route4_phase, own_route4_value = self._post_brock_route_progress_key(
            own_pos_a, own_pos_b, own_map_id
        )
        own_route4_phase, own_route4_value = fullgame_swarm_route_progress(
            self.quest_phase,
            own_map_id,
            own_route4_phase,
            own_route4_value,
        )
        lead_xp = (
            (int(self.pyboy.memory[ADDR_XP]) << 16)
            | (int(self.pyboy.memory[ADDR_XP + 1]) << 8)
            | int(self.pyboy.memory[ADDR_XP + 2])
        )
        charmander_family_xp = party_species_experience(
            self.pyboy.memory, GEN1_CHARMANDER_SPECIES_IDS,
        )
        grind_xp = (
            charmander_family_xp
            if (
                self.quest_phase in FULLGAME_CHARMANDER_GRIND_PHASES
                and charmander_family_xp is not None
            )
            else lead_xp
        )
        own_route4_value = fullgame_swarm_subphase_value(
            self.quest_phase, own_route4_value, grind_xp
        )
        own_progress = swarm_progress_key(
            self.swarm_rank_named_event_bits,
            own_event_bits,
            self.quest_phase,
            own_route4_phase,
            own_route4_value,
        )

        frontier_progress = (0, 0, -1, 0)
        frontier_available = False
        try:
            if self.swarm_frontier_meta_path.exists():
                meta = json.loads(self.swarm_frontier_meta_path.read_text(encoding='utf-8'))
                if (
                    swarm_frontier_meta_is_compatible(meta, self.swarm_frontier_schema)
                    and swarm_frontier_state_matches_meta(
                        self.swarm_frontier_state_path, meta
                    )
                ):
                    frontier_available = True
                    frontier_quest_phase = reconcile_frontier_quest_phase(
                        int(meta.get('quest_phase', 0)),
                        meta.get('quest_objective'),
                        self.quest_waypoints,
                        self.env_id,
                    )
                    frontier_route4_value = int(meta.get('route4_value', 0))
                    if frontier_quest_phase == self.quest_phase:
                        target_level = self.quest_waypoints[self.quest_phase].get(
                            'min_party_species_level'
                        )
                        repaired_value = repair_charmander_grind_frontier_value(
                            self.quest_phase,
                            frontier_route4_value,
                            charmander_family_xp,
                            target_level,
                        )
                        if repaired_value != frontier_route4_value:
                            print(
                                f"  [FRONTIER_REPAIR] env_id={self.env_id} "
                                f"quest_phase={self.quest_phase} "
                                f"poisoned_value={frontier_route4_value} "
                                f"family_xp={charmander_family_xp} "
                                f"repaired_value={repaired_value}",
                                flush=True,
                            )
                            frontier_route4_value = repaired_value
                    frontier_progress = swarm_progress_key(
                        self.swarm_rank_named_event_bits,
                        meta.get('event_bits', 0),
                        frontier_quest_phase,
                        meta.get('route4_phase', -1),
                        frontier_route4_value,
                    )
        except (OSError, ValueError, TypeError):
            frontier_progress = (0, 0, -1, 0)

        # Every veto below this point announces itself, so a frontier that
        # never publishes AND never logs means the comparison itself is
        # refusing -- which is invisible without saying so once per worker.
        _entry = getattr(self, '_reported_sync_entry', None)
        if _entry is None:
            _entry = set()
            self._reported_sync_entry = _entry
        _entry_key = (own_progress > frontier_progress, own_progress,
                      frontier_progress, frontier_available)
        if _entry_key not in _entry and len(_entry) < 8:
            _entry.add(_entry_key)
            print(
                f"  [SYNC] env_id={self.env_id} enter={own_progress > frontier_progress} "
                f"own={own_progress} frontier={frontier_progress} "
                f"available={frontier_available}",
                flush=True,
            )
        if own_progress > frontier_progress:
            raw_battle_flag = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
            battle_flag = self._effective_battle_flag(raw_battle_flag)
            text_box_active = int(self.pyboy.memory[ADDR_TEXT_BOX]) != 0
            font_loaded_active = int(self.pyboy.memory[ADDR_FONT_LOADED]) != 0
            hall_of_fame_candidate = is_hall_of_fame_frontier_candidate(
                self.quest_phase, own_map_id, current_named_event_bits,
            )
            # If forcing all workers to start at quest 0, try to close the
            # initial dialog by sending an 'A' press when a text box is active.
            # This helps workers clear startup dialog/cutscenes and begin moving.
            if text_box_active and os.environ.get("POKEMON_FORCE_START_QUEST_ZERO") == "1":
                # Best-effort: attempt a few short 'A' presses to dismiss startup
                # dialog boxes. Re-read the text box flag between attempts and
                # stop if it clears.
                for _press_try in range(3):
                    try:
                        self.pyboy.button_press('a')
                        self.pyboy.tick(8)
                        self.pyboy.button_release('a')
                        self.pyboy.tick(24)
                    except Exception:
                        # don't crash the worker if input fails
                        break
                    # Re-check the memory flag immediately; if cleared stop
                    try:
                        if int(self.pyboy.memory[ADDR_TEXT_BOX]) == 0:
                            text_box_active = False
                            break
                    except Exception:
                        # If memory read fails, continue with next attempt
                        continue
            party_snapshot = self._party_hp_snapshot()
            total_party_hp, total_party_max_hp = self._party_hp_totals(
                party_snapshot
            )
            # 2026-07-25: `total_party_hp >= 1` alone let a 3/38 HP Pikachu
            # (one wild encounter from a wipe) get promoted as the shared
            # frontier -- every worker then reset into that same fragile
            # state, froze rather than risk moving into grass, and the whole
            # swarm stalled on quest_phase for 2+ hours. A fractional floor
            # keeps a barely-alive lead from becoming everyone's start point;
            # 0 (the default) preserves the old alive-only behavior for every
            # milestone that doesn't opt in.
            hp_fraction = (
                (total_party_hp / total_party_max_hp) if total_party_max_hp > 0 else 0.0
            )
            lead_hp, lead_max_hp = party_snapshot[0] if party_snapshot else (0, 0)
            lead_hp_fraction = (
                (lead_hp / lead_max_hp) if lead_max_hp > 0 else 0.0
            )
            required_lead_hp_fraction = swarm_required_lead_hp_fraction(
                self.swarm_frontier_min_lead_hp_fraction,
                self.quest_phase,
            )
            required_party_hp_fraction = swarm_required_party_hp_fraction(
                self.swarm_frontier_min_hp_fraction,
                self.quest_phase,
            )
            # Only promote a "safe" moment -- same guard as
            # _save_progress_checkpoint -- so the saved state doesn't resume
            # mid-battle/mid-dialogue for every other worker.
            #
            # These gates used to be one silent boolean chain: a worker that
            # out-ranked the frontier and was refused left no trace, and only
            # the unverified-bits case ever logged. That cost a full audit to
            # diagnose a 12-hour frontier freeze, so name each gate and report
            # the first one that refuses (rate-limited per env per reason).
            _blockers = []
            if battle_flag != 0:
                _blockers.append('in_battle')
            if text_box_active:
                # When forcing all workers to start at quest 0, allow them to
                # ignore transient text-box blockers so they can clear the
                # initial dialog and proceed. This prevents the entire swarm
                # from being stalled at the intro when POKEMON_FORCE_START_QUEST_ZERO=1.
                if os.environ.get("POKEMON_FORCE_START_QUEST_ZERO") == "1":
                    pass
                elif int(own_map_id) == 88:
                    # Bill's script holds CD6B for the whole house sequence.
                    # 10k+ meet_bill clears died here as text_box.
                    pass
                elif swarm_grind_frontier_text_latch_is_stale(
                    self.quest_phase,
                    battle_flag,
                    text_box_active,
                    font_loaded_active,
                ):
                    # Route 1 leaves wJoyIgnore nonzero after the actual font
                    # flag closes. Retry the candidate and let the movement
                    # probe below prove that the saved state accepts input.
                    pass
                elif (
                    int(own_map_id) in (82, 232)
                    and self.quest_phase in FULLGAME_ROCK_TUNNEL_INTERIOR_PHASES
                ):
                    # Same shape as Bill's house. Rock Tunnel holds CD6B=1 as
                    # its *normal overworld* state -- that is the premise of
                    # _clear_rock_tunnel_overworld_joy_ignore, which zeroes it,
                    # but only on 1F and only for the first-B1F phase. On B1F
                    # and every later leg nothing clears it, so a worker parked
                    # in the open with no battle and no dialogue still reported
                    # `text_box` and was refused. Measured live 2026-08-19:
                    # 96/96 workers read CD6B=1 in 30 consecutive overworld
                    # samples, 0 FRONTIER_WROTE for a whole run, and the
                    # frontier stuck at exactly the one phase the clear hook
                    # covers. The real protection against promoting a
                    # dialogue-frozen candidate is the movement probe below
                    # (frontier_candidate_accepts_movement), which still runs.
                    pass
                elif hall_of_fame_candidate:
                    # Champion completion has no stable movement frame before
                    # the mandatory HoF transition. Its candidate receives a
                    # stricter end-to-end map-transition proof below.
                    pass
                else:
                    _blockers.append('text_box')
            if total_party_hp < 1:
                _blockers.append('party_fainted')
            if hp_fraction < required_party_hp_fraction:
                _blockers.append(
                    'party_hp=%.2f<%.2f' % (
                        hp_fraction, required_party_hp_fraction))
            if lead_hp_fraction < required_lead_hp_fraction:
                _blockers.append(
                    'lead_hp=%.2f<%.2f' % (
                        lead_hp_fraction, required_lead_hp_fraction))
            if unverified_frontier_bits:
                _blockers.append('unverified_events')
            if not fullgame_frontier_position_allowed(
                self.quest_phase, own_map_id, own_pos_a, own_pos_b,
                current_named_event_bits,
            ):
                _blockers.append('position_not_allowed(map=%d)' % own_map_id)
            # After HoF credits Yellow warps to Pallet. That completed state
            # must not replace the replay frontier. The *equal* phase is still
            # the actionable enter_hall_of_fame objective in Champions Room;
            # blocking it pinned the frontier at beat_champion despite 3,000+
            # live Champion/HoF clears.
            if fullgame_frontier_is_postcredits_phase(self.quest_phase):
                _blockers.append('post_credits_quest_phase')
            if int(own_map_id) == 118:
                _blockers.append('hall_of_fame_map')
            if (
                EVENT_BEAT_CHAMPION_RIVAL in current_named_event_bits
                and int(own_map_id) in {0, 1, 12, 37, 38, 39, 40}
            ):
                _blockers.append('postgame_pallet')
            if swarm_mastery_blocks_frontier_publish(
                self.is_swarm_drill_worker, self.swarm_mastery_enabled
            ):
                frontier_phase = int(frontier_progress[1])
                candidate_relation = swarm_mastery_candidate_relation(
                    self.quest_phase, frontier_phase, own_map_id,
                )
                incremental_grind_candidate = (
                    swarm_incremental_grind_frontier_candidate(
                        self.quest_phase,
                        frontier_phase,
                        own_route4_value,
                        frontier_progress[3],
                    )
                )
                free_skip = swarm_skipped_phases_were_already_satisfied(
                    self.quest_waypoints,
                    frontier_phase,
                    self.quest_phase,
                    int(self.pyboy.memory[ADDR_LEVEL]),
                )
                if (
                    candidate_relation != "next"
                    and not incremental_grind_candidate
                    and not free_skip
                ):
                    _blockers.append(f'mastery_candidate={candidate_relation}')
                budget = swarm_drill_step_budget(
                    frontier_phase,
                    self.swarm_drill_max_steps,
                    self.swarm_drill_early_max_steps,
                    FULLGAME_EARLY_GAME_QUEST_PHASES,
                )
                mastery_samples = load_swarm_mastery_window(
                    self.swarm_mastery_meta_path, frontier_phase
                )
                mastery_no_improve = load_swarm_mastery_no_improve_count(
                    self.swarm_mastery_meta_path, frontier_phase
                )
                reliability_mastery_phase = (
                    frontier_phase in FULLGAME_RNG_GRIND_QUEST_PHASES
                    or frontier_phase == FULLGAME_ROUTE25_HEAL_QUEST_PHASE
                    or frontier_phase in FULLGAME_BILL_INTERIOR_QUEST_PHASES
                    or frontier_phase in FULLGAME_BATTLE_RELIABILITY_MASTERY_PHASES
                )
                if not incremental_grind_candidate and not swarm_mastery_allows_promotion(
                    mastery_samples,
                    budget,
                    self.swarm_drill_min_samples,
                    self.swarm_drill_hit_rate,
                    self.swarm_mastery_no_improve_rotations,
                    reliability_only=reliability_mastery_phase,
                    reliability_min_samples=self.swarm_grind_mastery_successes,
                    no_improve_count=mastery_no_improve,
                ):
                    _blockers.append('mastery_gate')
                    _reported = getattr(self, '_reported_mastery_gate', None)
                    if _reported is None:
                        _reported = {}
                        self._reported_mastery_gate = _reported
                    sample_count = len(mastery_samples)
                    # Key on the plateau counter too: sample_count saturates at
                    # window_size, after which the old dedup silenced this line
                    # forever and the gate became invisible from the log.
                    _progress_key = (sample_count, mastery_no_improve)
                    if _reported.get(frontier_phase) != _progress_key:
                        _reported[frontier_phase] = _progress_key
                        hits = sum(1 for step in mastery_samples if 0 <= step <= budget)
                        best = min(mastery_samples) if mastery_samples else None
                        print(
                            f"  [MASTERY_GATE] env_id={self.env_id} "
                            f"phase={frontier_phase} samples={sample_count} "
                            f"best={best} hits={hits}/{sample_count} "
                            f"no_improve={mastery_no_improve}/"
                            f"{self.swarm_mastery_no_improve_rotations} "
                            f"budget={budget} "
                            f"mode={'reliability' if reliability_mastery_phase else 'plateau'} "
                            f"grind_successes={self.swarm_grind_mastery_successes} "
                            f"no_improve_rotations={self.swarm_mastery_no_improve_rotations} "
                            f"need_rate={self.swarm_drill_hit_rate:.2f}",
                            flush=True,
                        )
            if _blockers:
                _reported = getattr(self, '_reported_frontier_blockers', None)
                if _reported is None:
                    _reported = set()
                    self._reported_frontier_blockers = _reported
                # Key on the whole reason set, not just the first entry. The
                # old key reported `mastery_gate` once and then went silent
                # forever, so when a *different* blocker became the binding one
                # the log showed nothing at all -- which is precisely how the
                # Mt Moon fossil stall stayed invisible for hours.
                _key = tuple(sorted(b.split('=')[0] for b in _blockers))
                if _key not in _reported and len(_reported) < 64:
                    _reported.add(_key)
                    print(
                        f"  [FRONTIER_BLOCKED] env_id={self.env_id} "
                        f"step={getattr(self, 'steps', -1)} map={own_map_id} "
                        f"pos=({own_pos_a},{own_pos_b}) "
                        f"reasons={','.join(_blockers)}",
                        flush=True,
                    )
            _bill_interior_ok = (
                self.quest_phase not in FULLGAME_BILL_INTERIOR_QUEST_PHASES
                or own_map_id == 88
            )
            _safe_frontier = is_safe_post_brock_swarm_frontier(
                own_map_id,
                own_pos_a,
                own_pos_b,
                fossil_chosen=bool(
                    current_named_event_bits & MT_MOON_FOSSIL_EVENT_BITS
                ),
                jessie_james_defeated=(
                    MT_MOON_JESSIE_JAMES_EVENT_BIT
                    in current_named_event_bits
                ),
            )
            if not _blockers and not (_bill_interior_ok and _safe_frontier):
                # These two vetoes returned silently, so a frontier that passed
                # every named blocker and still never published looked exactly
                # like a swarm that had simply stopped trying.
                _vetoed = getattr(self, '_reported_frontier_veto', None)
                if _vetoed is None:
                    _vetoed = set()
                    self._reported_frontier_veto = _vetoed
                _veto_key = (
                    int(self.quest_phase), own_map_id,
                    bool(_bill_interior_ok), bool(_safe_frontier),
                )
                if _veto_key not in _vetoed and len(_vetoed) < 32:
                    _vetoed.add(_veto_key)
                    print(
                        f"  [FRONTIER_VETO] env_id={self.env_id} "
                        f"phase={self.quest_phase} map={own_map_id} "
                        f"pos=({own_pos_a},{own_pos_b}) "
                        f"bill_interior_ok={_bill_interior_ok} "
                        f"safe_post_brock={_safe_frontier}",
                        flush=True,
                    )
            if not _blockers and _bill_interior_ok and _safe_frontier:
                write_lock_path = self.swarm_frontier_meta_path.with_name(
                    f"{self.swarm_frontier_meta_path.name}.write_lock"
                )
                if not try_acquire_swarm_frontier_write_lock(write_lock_path):
                    return False
                # The optimistic read above may have overlapped another
                # worker's state/meta replacement. Re-read both halves while
                # holding the writer lock and refuse any regression.
                locked_frontier_progress = (0, 0, -1, 0)
                try:
                    if self.swarm_frontier_meta_path.exists():
                        locked_meta = json.loads(
                            self.swarm_frontier_meta_path.read_text(encoding='utf-8')
                        )
                        if (
                            swarm_frontier_meta_is_compatible(
                                locked_meta, self.swarm_frontier_schema
                            )
                            and swarm_frontier_state_matches_meta(
                                self.swarm_frontier_state_path, locked_meta
                            )
                        ):
                            locked_frontier_quest_phase = (
                                reconcile_frontier_quest_phase(
                                    int(locked_meta.get('quest_phase', 0)),
                                    locked_meta.get('quest_objective'),
                                    self.quest_waypoints,
                                    self.env_id,
                                )
                            )
                            locked_frontier_progress = swarm_progress_key(
                                self.swarm_rank_named_event_bits,
                                locked_meta.get('event_bits', 0),
                                locked_frontier_quest_phase,
                                locked_meta.get('route4_phase', -1),
                                locked_meta.get('route4_value', 0),
                            )
                except (OSError, ValueError, TypeError):
                    locked_frontier_progress = (0, 0, -1, 0)
                if own_progress <= locked_frontier_progress:
                    # Losing the re-read under the lock is normal when another
                    # worker just published, but a *persistent* loss here is
                    # indistinguishable from "nothing happened" without a line.
                    _lost = getattr(self, '_reported_frontier_lock_loss', None)
                    if _lost is None:
                        _lost = set()
                        self._reported_frontier_lock_loss = _lost
                    _lost_key = (own_progress, locked_frontier_progress)
                    if _lost_key not in _lost and len(_lost) < 16:
                        _lost.add(_lost_key)
                        print(
                            f"  [FRONTIER_LOST_RACE] env_id={self.env_id} "
                            f"own={own_progress} locked={locked_frontier_progress}",
                            flush=True,
                        )
                    release_swarm_frontier_write_lock(write_lock_path)
                    return False
                frontier_progress = locked_frontier_progress
                if not party_read_is_plausible(self.pyboy.memory):
                    # Never hand the swarm a checkpoint saved off a torn party
                    # block. Cheaper than finding out from the movement probe,
                    # which boots a whole PyBoy per candidate: on 2026-08-23
                    # that path burned 7,424 rejections in a single log window
                    # because every candidate came from the same bad read.
                    if not getattr(self, '_reported_frontier_party_read', False):
                        self._reported_frontier_party_read = True
                        print(
                            f"  [FRONTIER_PARTY_READ] env_id={self.env_id} "
                            f"phase={self.quest_phase} "
                            f"level={int(self.pyboy.memory[ADDR_LEVEL])} "
                            "implausible party block; candidate not saved",
                            flush=True,
                        )
                    release_swarm_frontier_write_lock(write_lock_path)
                    return False
                try:
                    self.swarm_frontier_state_path.parent.mkdir(parents=True, exist_ok=True)
                    temp_state = self.swarm_frontier_state_path.with_name(
                        f"{self.swarm_frontier_state_path.stem}.tmp.env{self.env_id}"
                        f".pid{os.getpid()}{self.swarm_frontier_state_path.suffix}"
                    )
                    # A movement-disproved D057 value is logically overworld,
                    # but saving that stale raw byte would make every follower
                    # load the frontier as a battle. Normalize only the saved
                    # snapshot and immediately restore the live emulator byte.
                    normalize_saved_battle_flag = (
                        battle_flag == 0 and raw_battle_flag in (1, 2)
                    )
                    restore_grind_resources = (
                        should_restore_rock_tunnel_grind_frontier_resources(
                            self.quest_phase,
                            frontier_progress[1],
                            frontier_progress[3],
                        )
                    )
                    # Heal the snapshot for the in-cave traverse too, but keep
                    # `restore_grind_resources` for the movement proof below:
                    # these legs are one-way routes, not patrols.
                    restore_resources = (
                        restore_grind_resources
                        or should_restore_rock_tunnel_traverse_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_tower_purification_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_tower_rival_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_silph_giovanni_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_rocket_giovanni_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_mt_moon_jj_frontier_resources(
                            self.quest_phase
                        )
                        or should_restore_misty_frontier_resources(
                            self.quest_phase
                        )
                    )
                    resource_addresses = set()
                    resource_snapshot = {}
                    if restore_resources:
                        resource_addresses.update(
                            address
                            for pair in PARTY_CUR_HP_ADDRS
                            for address in pair
                        )
                        resource_addresses.update(
                            address
                            for party_addrs in PARTY_MOVE_PP_ADDRS
                            for address in party_addrs
                        )
                        resource_addresses.update({
                            ADDR_ACTIVE_MON_CUR_HP_HI,
                            ADDR_ACTIVE_MON_CUR_HP_LO,
                            ADDR_ACTIVE_MON_MAX_HP_HI,
                            ADDR_ACTIVE_MON_MAX_HP_LO,
                        })
                        resource_snapshot = {
                            address: int(self.pyboy.memory[address])
                            for address in resource_addresses
                        }
                    if normalize_saved_battle_flag:
                        self.pyboy.memory[ADDR_BATTLE_FLAG] = 0
                    try:
                        if restore_resources:
                            _heal_party_memory(self.pyboy.memory)
                            _restore_party_pp_memory(self.pyboy.memory)
                        with open(temp_state, 'wb') as handle:
                            self.pyboy.save_state(handle)
                    finally:
                        for address, value in resource_snapshot.items():
                            self.pyboy.memory[address] = value
                        if normalize_saved_battle_flag:
                            self.pyboy.memory[ADDR_BATTLE_FLAG] = raw_battle_flag
                    # 2026-07-25: a candidate can pass every flag-based check
                    # above and still be mid an unadvanceable dialogue (see
                    # frontier_candidate_accepts_movement docstring) -- verify
                    # the actual candidate file before sharing it with the
                    # rest of the swarm, not just the flags that produced it.
                    forced_direction = self._forced_direction_name(
                        own_map_id, own_pos_a, own_pos_b
                    )
                    required_direction = (
                        swarm_frontier_required_validation_direction(
                            forced_direction, restore_grind_resources,
                            own_map_id,
                        )
                    )
                    validation_pre_actions = swarm_frontier_validation_pre_actions(
                        self.quest_phase, own_map_id, current_named_event_bits,
                    )
                    if hall_of_fame_candidate:
                        candidate_valid = (
                            frontier_candidate_reaches_map_with_actions(
                                temp_state,
                                self.direction_press_ticks,
                                self.direction_release_ticks,
                                destination_map=118,
                                actions=('a', 'up'),
                                max_cycles=128,
                            )
                        )
                    else:
                        candidate_valid = (
                            own_map_id == 88
                            or frontier_candidate_accepts_movement(
                                temp_state,
                                self.direction_press_ticks,
                                self.direction_release_ticks,
                                required_direction=required_direction,
                                pre_actions=validation_pre_actions,
                            )
                        )
                    if not candidate_valid:
                        temp_state.unlink(missing_ok=True)
                        print(
                            f"  [Swarm env_id={self.env_id}] rejected frontier "
                            f"candidate: required={required_direction or 'any'} "
                            + (
                                "Champion cutscene did not reach Hall of Fame"
                                if hall_of_fame_candidate
                                else "direction did not move the sprite "
                                     "(dialogue/cutscene, or a stale poked block view)"
                            ),
                            flush=True,
                        )
                        release_swarm_frontier_write_lock(write_lock_path)
                        return False
                    state_sha256 = file_sha256(temp_state)
                    os.replace(temp_state, self.swarm_frontier_state_path)
                    print(
                        f"  [FRONTIER_WROTE] env_id={self.env_id} "
                        f"phase={self.quest_phase} "
                        f"obj={fullgame_quest_objective_name(self.quest_phase)} "
                        f"map={own_map_id} pos=({own_pos_a},{own_pos_b})",
                        flush=True,
                    )

                    temp_meta = self.swarm_frontier_meta_path.with_name(
                        f"{self.swarm_frontier_meta_path.stem}.tmp.env{self.env_id}"
                        f".pid{os.getpid()}.json"
                    )
                    temp_meta.write_text(
                        json.dumps({
                            'schema': self.swarm_frontier_schema,
                            'event_bits': (
                                own_event_bits if self.swarm_rank_named_event_bits else 0
                            ),
                            'verified_event_bits': sorted(self.rewarded_named_event_flags),
                            'named_event_bits': sorted(current_named_event_bits),
                            'state_sha256': state_sha256,
                            'quest_phase': self.quest_phase,
                            'quest_objective': fullgame_quest_objective_name(
                                self.quest_phase
                            ),
                            'route4_phase': own_route4_phase,
                            'route4_value': own_route4_value,
                            'respawn_map': int(
                                self.pyboy.memory[ADDR_LAST_BLACKOUT_MAP]
                            ),
                            'env_id': self.env_id,
                            'ts': time.time(),
                        }),
                        encoding='utf-8',
                    )
                    os.replace(temp_meta, self.swarm_frontier_meta_path)
                    print(
                        f"  [Swarm env_id={self.env_id}] new frontier leader: "
                        f"event_bits={own_event_bits} quest_phase={self.quest_phase} "
                        f"route4_phase={own_route4_phase} "
                        f"route4_value={own_route4_value} pos=({own_pos_b},{own_pos_a}) "
                        f"(was event_bits={frontier_progress[0]} "
                        f"quest_phase={frontier_progress[1]} "
                        f"route_phase={frontier_progress[2]} "
                        f"value={frontier_progress[3]})",
                        flush=True,
                    )
                except OSError as e:
                    print(f"  [Swarm env_id={self.env_id}] failed to save frontier: {e}", flush=True)
                release_swarm_frontier_write_lock(write_lock_path)
            return False

        # A synthetic zero tuple has no corresponding state to load. It must
        # never cause bootstrap workers to terminate in a catch-up loop.
        if not frontier_available:
            return False

        grind_catchup = swarm_grind_phase_catchup_needed(
            self.quest_phase,
            frontier_progress[1],
            own_progress[3],
            frontier_progress[3],
            self.swarm_catchup_behind_route4_x,
        )
        if grind_catchup is not None:
            return grind_catchup

        event_bits_behind = frontier_progress[0] - own_progress[0]
        if event_bits_behind >= self.swarm_catchup_behind_bits:
            return True
        if event_bits_behind == 0:
            frontier_quest_phase = frontier_progress[1]
            if frontier_quest_phase > self.quest_phase:
                return True
            if frontier_quest_phase < self.quest_phase:
                return False
            # Same event-bit tier: behind on Route 4 progress only counts as
            # "behind" within the same phase (comparing a north-value to an
            # east-value would be comparing unrelated scales). A worker
            # still in phase 0 while the frontier has reached phase 1 is
            # always meaningfully behind regardless of the raw numbers.
            frontier_phase, frontier_value = frontier_progress[2], frontier_progress[3]
            if frontier_phase > own_route4_phase:
                return True
            if frontier_phase == own_route4_phase:
                value_behind = frontier_value - own_route4_value
                if value_behind >= self.swarm_catchup_behind_route4_x:
                    return True
        return False

    def _local_visit_panel(self, map_id, pos_a, pos_b, radius=5):
        size = radius * 2 + 1
        panel = np.zeros((size, size), dtype=np.uint8)
        for visit_map, visit_a, visit_b in self.visited_positions:
            if visit_map != map_id:
                continue
            rel_a = visit_a - pos_a + radius
            rel_b = visit_b - pos_b + radius
            if 0 <= rel_a < size and 0 <= rel_b < size:
                panel[rel_a, rel_b] = 150
        panel[radius, radius] = 255
        return np.repeat(np.repeat(panel, 2, axis=0), 2, axis=1)

    def _draw_panel(self, canvas, top, left, panel, alpha=0.8):
        height = min(panel.shape[0], canvas.shape[0] - top)
        width = min(panel.shape[1], canvas.shape[1] - left)
        if height <= 0 or width <= 0:
            return
        region = canvas[top:top + height, left:left + width].astype(np.float32)
        overlay = panel[:height, :width].astype(np.float32)
        canvas[top:top + height, left:left + width] = (
            region * (1.0 - alpha) + overlay * alpha
        ).astype(np.uint8)

    def _state_feature_rows(self, map_id, pos_a, pos_b, battle_flag, party_size, party_snapshot):
        total_cur_hp, total_max_hp = self._party_hp_totals(party_snapshot)
        hp_frac = (total_cur_hp / total_max_hp) if total_max_hp > 0 else 0.0
        badges = self.pyboy.memory[ADDR_BADGES]
        badge_frac = badges.bit_count() / 8.0
        stuck_base = max(1, self.coord_stuck_threshold or 64)
        stuck_frac = min(self.coord_visit_counts.get((map_id, pos_a, pos_b), 0) / stuck_base, 1.0)
        return [
            map_id / 255.0,
            pos_a / 255.0,
            pos_b / 255.0,
            hp_frac,
            min(party_size, 6) / 6.0,
            badge_frac,
            min(battle_flag, 2) / 2.0,
            stuck_frac,
        ]

    def _state_bar_panel(self, map_id, pos_a, pos_b, battle_flag, party_size, party_snapshot):
        rows = self._state_feature_rows(map_id, pos_a, pos_b, battle_flag, party_size, party_snapshot)
        panel = np.zeros((16, 24), dtype=np.uint8)
        for idx, value in enumerate(rows):
            start_row = idx * 2
            panel[start_row:start_row + 2, :] = 20
            fill = max(1, int(round(value * 23)))
            panel[start_row:start_row + 2, 1:1 + fill] = 235
        return panel

    def _recent_actions_panel(self):
        panel = np.zeros((max(12, len(self.actions) * 2), 16), dtype=np.uint8)
        actions = list(self.recent_actions)[-8:]
        start_col = panel.shape[1] - (len(actions) * 2)
        for idx, action in enumerate(actions):
            row = max(0, min(int(action), len(self.actions) - 1)) * 2
            col = start_col + idx * 2
            panel[row:row + 2, col:col + 2] = 255
        return panel

    def _augment_observation(self, gray):
        map_id = self.pyboy.memory[ADDR_MAP_ID]
        pos_a = self.pyboy.memory[ADDR_POS_A]
        pos_b = self.pyboy.memory[ADDR_POS_B]
        battle_flag = self._effective_battle_flag()
        party_size = self.pyboy.memory[ADDR_PARTY_SIZE]
        party_snapshot = self._party_hp_snapshot(party_size)

        augmented = gray.copy()
        self._draw_panel(
            augmented,
            0,
            0,
            self._state_bar_panel(map_id, pos_a, pos_b, battle_flag, party_size, party_snapshot),
            alpha=0.72,
        )
        local_panel = self._local_visit_panel(map_id, pos_a, pos_b)
        self._draw_panel(
            augmented,
            0,
            augmented.shape[1] - local_panel.shape[1],
            local_panel,
            alpha=0.72,
        )
        action_panel = self._recent_actions_panel()
        self._draw_panel(
            augmented,
            augmented.shape[0] - action_panel.shape[0],
            augmented.shape[1] - action_panel.shape[1],
            action_panel,
            alpha=0.80,
        )
        return augmented

    def _is_recent_action_oscillation(self):
        if len(self.recent_actions) < 4:
            return False
        a, b, c, d = list(self.recent_actions)[-4:]
        if a != c or b != d:
            return False
        return OPPOSITE_ACTIONS.get(a) == b

    def _get_obs(self):
        img = np.array(self.pyboy.screen.image)[:, :, :3]
        gray = np.mean(img, axis=2).astype(np.uint8)
        gray_img = Image.fromarray(gray, mode='L').resize((84, 84))
        gray_small = np.array(gray_img)
        gray_small = self._augment_observation(gray_small)
        return gray_small[:, :, np.newaxis]

    def _get_reward(self):
        level = max(1, min(int(self.pyboy.memory[ADDR_LEVEL]), 100))
        badges = min(int(self.pyboy.memory[ADDR_BADGES]).bit_count(), 8)
        map_id = self.pyboy.memory[ADDR_MAP_ID]
        location_reward = MAP_REWARDS.get(map_id, 0)
        if self.reward_cap is not None:
            location_reward = min(location_reward, self.reward_cap)
        return (level * self.level_reward_scale) + (badges * 1000) + location_reward

    def _target_distance(self, target, pos_a, pos_b):
        if isinstance(target, tuple):
            ty, tx = target
            return abs(pos_a - ty) + abs(pos_b - tx)
        return abs(pos_a - target)

    def _read_u16(self, hi_addr, lo_addr):
        return (self.pyboy.memory[hi_addr] << 8) | self.pyboy.memory[lo_addr]

    def _safari_resources(self):
        """Return the ROM's live (steps remaining, Safari Balls) counters."""
        return (
            self._read_u16(ADDR_SAFARI_STEPS_HI, ADDR_SAFARI_STEPS_LO),
            int(self.pyboy.memory[ADDR_NUM_SAFARI_BALLS]),
        )

    def _battle_label(self, battle_flag):
        return {
            0: "overworld",
            1: "wild",
            2: "trainer",
        }.get(battle_flag, f"battle{battle_flag}")

    def _progress_checkpoint_key(self):
        level = max(1, min(int(self.pyboy.memory[ADDR_LEVEL]), 100))
        xp = (
            (int(self.pyboy.memory[ADDR_XP]) << 16)
            | (int(self.pyboy.memory[ADDR_XP + 1]) << 8)
            | int(self.pyboy.memory[ADDR_XP + 2])
        )
        frontier_key = -1
        if self.frontier_path and self.best_frontier_score != float("-inf"):
            frontier_key = int(max(self.best_frontier_score, 0.0))
        return (frontier_key, level, xp)

    def _map_label(self, map_id):
        return MAP_LABELS.get(map_id, f"map{map_id}")

    def _party_hp_snapshot(self, party_size=None):
        if party_size is None:
            party_size = self.pyboy.memory[ADDR_PARTY_SIZE]
        party_size = max(0, min(int(party_size), len(PARTY_CUR_HP_ADDRS)))
        snapshot = []
        for idx in range(party_size):
            cur_hp = self._read_u16(*PARTY_CUR_HP_ADDRS[idx])
            max_hp = self._read_u16(*PARTY_MAX_HP_ADDRS[idx])
            if max_hp <= 0 or max_hp > 999:
                continue
            cur_hp = max(0, min(cur_hp, max_hp))
            snapshot.append((cur_hp, max_hp))
        return snapshot

    def _is_invalid_party_state(self, raw_party_size, party_snapshot):
        raw_party_size = int(raw_party_size)
        if raw_party_size < 0 or raw_party_size > len(PARTY_CUR_HP_ADDRS):
            return True
        if raw_party_size > 0 and not party_snapshot:
            return True
        return False

    def _party_hp_totals(self, snapshot):
        return (
            sum(cur_hp for cur_hp, _ in snapshot),
            sum(max_hp for _, max_hp in snapshot),
        )

    def _count_event_flag_bits(self):
        # PWhiddy/PokemonRedExperiments-style progress signal: total set bits
        # across Yellow's wEventFlags bitfield (one bit per story/quest/
        # trainer-beaten event). See ADDR_EVENT_FLAGS_START/END for how the
        # address was derived and cross-checked.
        memory = self.pyboy.memory
        total = sum(
            int(memory[addr]).bit_count()
            for addr in range(ADDR_EVENT_FLAGS_START, ADDR_EVENT_FLAGS_END)
        )
        for bit in self.quarantined_event_flag_bits:
            byte_offset, bit_in_byte = divmod(bit, 8)
            addr = ADDR_EVENT_FLAGS_START + byte_offset
            if (
                ADDR_EVENT_FLAGS_START <= addr < ADDR_EVENT_FLAGS_END
                and (int(memory[addr]) >> bit_in_byte) & 1
            ):
                total -= 1
        return total

    def _event_flag_is_set(self, bit):
        bit = int(bit)
        addr = ADDR_EVENT_FLAGS_START + bit // 8
        return bool(
            ADDR_EVENT_FLAGS_START <= addr < ADDR_EVENT_FLAGS_END
            and int(self.pyboy.memory[addr]) & (1 << (bit % 8))
        )

    def _has_mt_moon_fossil(self):
        return any(
            self._event_flag_is_set(bit)
            for bit in MT_MOON_FOSSIL_EVENT_BITS
        )

    def _current_rewardable_named_event_bits(self):
        """Return only catalogued story flags that are allowed to train PPO."""
        flag_bytes = bytes(
            self.pyboy.memory[ADDR_EVENT_FLAGS_START:ADDR_EVENT_FLAGS_END]
        )
        return named_event_bits_set(flag_bytes) - self.quarantined_event_flag_bits

    def _claim_new_named_event_flags(self, map_id=None, pos_a=None, pos_b=None):
        current = self._current_rewardable_named_event_bits()
        newly_set = (
            current
            - self.base_named_event_flags
            - self.rewarded_named_event_flags
        )
        if self.reward_ordered_quest_event_flags_only:
            if self.quest_phase >= len(self.quest_waypoints):
                newly_set = set()
            else:
                waypoint = self.quest_waypoints[self.quest_phase]
                expected_bits = set(map(int, waypoint.get('any_event_bits', ())))
                if 'event_bit' in waypoint:
                    expected_bits.add(int(waypoint['event_bit']))
                if not expected_bits:
                    newly_set = set()
                else:
                    newly_set &= expected_bits
                    if not quest_waypoint_matches(
                        waypoint,
                        map_id,
                        pos_a,
                        pos_b,
                        newly_set,
                        # `require_dialogue_closed` fails closed when it cannot
                        # see WRAM, so omitting `memory` made every waypoint
                        # carrying that flag permanently unclaimable: its event
                        # bit stayed out of `rewarded_named_event_flags`, and
                        # `_swarm_sync` then treated it as an unverified
                        # out-of-order event and blocked *every* frontier
                        # publish from that phase on. That is what stranded the
                        # Mt Moon frontier: EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD
                        # was set and rewarded-in-order by the quest ledger, yet
                        # never recorded here, so `choose_mt_moon_fossil` could
                        # never become the frontier and no rotation ever ran it.
                        # Mirror _advance_quest_phase's view of the emulator.
                        memory=self.pyboy.memory,
                        battle_active=(
                            int(self.pyboy.memory[ADDR_BATTLE_FLAG]) in (1, 2)
                        ),
                    ):
                        newly_set = set()
        if newly_set:
            self.rewarded_named_event_flags.update(newly_set)
        return newly_set

    def _effective_battle_flag(self, raw_flag=None):
        if raw_flag is None:
            raw_flag = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
        # Grind phases must see real wilds. force_repel is on for the whole
        # fullgame milestone, and PART11 includes the soul-marsh level ladder,
        # so the old suppress-wilds path hid D057=1 and forced the Route 14
        # Left walk inside a live fight. Live 96/96 sat on (8,15) flag=1.
        grind = getattr(self, 'wild_battle_quest_phases', None)
        if grind and self.quest_phase in grind:
            if self.suppress_stale_battle_reassertion and int(raw_flag) in (1, 2):
                return 0
            return int(raw_flag)
        # These phases begin in Bill's House after every Route 25 trainer is
        # already defeated, and Repel is maintained before every subsequent
        # movement tick. A nonzero battle byte here is therefore residual
        # WRAM, not a possible new encounter. Suppress it without changing
        # global force-Repel milestones, which may still contain trainers.
        if (
            self._quest_phase_forces_repel()
            and not force_repel_preserves_trainer_battle(
                self.pyboy.memory[ADDR_MAP_ID],
                self.quest_phase,
                raw_flag,
            )
        ):
            return 0
        if self.suppress_stale_battle_reassertion and int(raw_flag) in (1, 2):
            return 0
        return int(raw_flag)

    def _advance_quest_phase(
        self, map_id, pos_a, pos_b, battle_active=None
    ):
        if self.quest_phase >= len(self.quest_waypoints):
            return None, 0.0
        waypoint = self.quest_waypoints[self.quest_phase]
        matching_event_bits = self.rewarded_named_event_flags
        if 'event_bit' in waypoint or 'any_event_bits' in waypoint:
            # Story flags must reconcile after restarting from a frontier
            # where the event is already in the reset baseline. A durable
            # current flag is authoritative even though it is no longer
            # "new" and cannot earn its event reward a second time. This is
            # especially important after a route-only checkpoint rollback:
            # defeated trainers such as the Tower rival cannot be fought a
            # second time merely to re-claim their ordered quest phase.
            matching_event_bits = self._current_rewardable_named_event_bits()
        party_snapshot = self._party_hp_snapshot()
        total_party_hp, total_party_max_hp = self._party_hp_totals(
            party_snapshot
        )
        party_size = max(0, min(
            int(self.pyboy.memory[ADDR_PARTY_SIZE]),
            len(PARTY_MOVE_ID_ADDRS),
        ))
        party_move_ids = {
            int(self.pyboy.memory[addr])
            for party_index in range(party_size)
            for addr in PARTY_MOVE_ID_ADDRS[party_index]
            if int(self.pyboy.memory[addr]) > 0
        }
        bag_count = max(0, min(int(self.pyboy.memory[ADDR_NUM_BAG_ITEMS]), 20))
        bag_item_ids = {
            int(self.pyboy.memory[ADDR_BAG_ITEMS + item_index * 2])
            for item_index in range(bag_count)
        }
        party_species_levels = [
            (
                int(self.pyboy.memory[PARTY_SPECIES_ADDRS[party_index]]),
                int(self.pyboy.memory[
                    PARTY_SPECIES_ADDRS[party_index] + 0x21
                ]),
            )
            for party_index in range(party_size)
        ]
        if not quest_waypoint_matches(
            waypoint,
            map_id,
            pos_a,
            pos_b,
            matching_event_bits,
            level=int(self.pyboy.memory[ADDR_LEVEL]),
            badge_count=int(self.pyboy.memory[ADDR_BADGES]).bit_count(),
            last_blackout_map=int(
                self.pyboy.memory[ADDR_LAST_BLACKOUT_MAP]
            ),
            total_party_hp=total_party_hp,
            total_party_max_hp=total_party_max_hp,
            party_move_ids=party_move_ids,
            bag_item_ids=bag_item_ids,
            party_species_levels=party_species_levels,
            memory=self.pyboy.memory,
            battle_active=battle_active,
        ):
            return None, 0.0
        name = str(waypoint.get('name') or f"phase_{self.quest_phase + 1}")
        reward = float(waypoint.get('reward', 0.0))
        self.quest_phase += 1
        self.quest_phase_step_count = 0
        self.quest_phase_hits.append(name)
        return name, reward

    def _quest_phase_name(self):
        if self.quest_phase >= len(self.quest_waypoints):
            return 'complete'
        return str(
            self.quest_waypoints[self.quest_phase].get('name')
            or f"phase_{self.quest_phase + 1}"
        )

    def _format_party_hp(self, snapshot):
        if not snapshot:
            return "none"
        return ",".join(
            f"P{idx + 1}:{cur_hp}/{max_hp}"
            for idx, (cur_hp, max_hp) in enumerate(snapshot)
        )

    def _format_party_hp_totals(self, snapshot):
        if not snapshot:
            return "n/a"
        total_cur_hp, total_max_hp = self._party_hp_totals(snapshot)
        return f"{total_cur_hp}/{total_max_hp}"

    def _format_map_path(self, map_labels):
        if not map_labels:
            return "n/a"
        if len(map_labels) == 1:
            return map_labels[0]
        return " -> ".join(map_labels)

    def _format_frontier_summary(self):
        if not self.frontier_hp_snapshots:
            return None
        best_snapshot = self.frontier_hp_snapshots[-1]
        if best_snapshot.startswith("f"):
            _, summary = best_snapshot.split("@", 1)
            return summary
        return best_snapshot

    @classmethod
    def queue_episode_summary(cls, summary, frontier_summary=None):
        entry = (summary, frontier_summary)
        if cls._pending_episode_summary == entry:
            cls._pending_episode_count += 1
            return
        cls.flush_pending_episode_summaries()
        cls._pending_episode_summary = entry
        cls._pending_episode_count = 1

    @classmethod
    def flush_pending_episode_summaries(cls):
        if cls._pending_episode_summary is None:
            return
        summary, frontier_summary = cls._pending_episode_summary
        label = "[EP]" if cls._pending_episode_count == 1 else f"[EP x{cls._pending_episode_count}]"
        print(f"  {label} {summary}")
        if frontier_summary:
            print(f"       best={frontier_summary}")
        cls._pending_episode_summary = None
        cls._pending_episode_count = 0

    def _record_frontier_hp_snapshot(self, frontier_score, map_id, pos_a, pos_b, battle_flag, party_snapshot):
        total_cur_hp, total_max_hp = self._party_hp_totals(party_snapshot)
        snapshot = f"f{int(frontier_score)}@{self._map_label(map_id)}:{pos_a},{pos_b} hp={total_cur_hp}/{total_max_hp}"
        if battle_flag != 0:
            snapshot += f" {self._battle_label(battle_flag)}"
        if self.frontier_hp_snapshots and self.frontier_hp_snapshots[-1] == snapshot:
            return
        self.frontier_hp_snapshots.append(snapshot)
        self.frontier_hp_snapshots = self.frontier_hp_snapshots[-8:]

    def _wipe_progress_credit(self):
        if (
            self.wipe_progress_max_y_scale == 0.0
            and self.wipe_progress_tiles_scale == 0.0
            and self.wipe_progress_frontier_scale == 0.0
        ):
            return 0.0

        progress_positions = self.visited_positions
        if self.frontier_path:
            frontier_maps = {segment_map for segment_map, _ in self.frontier_path}
            progress_positions = {
                pos for pos in self.visited_positions if pos[0] in frontier_maps
            }

        max_y = max((visit_a for _, visit_a, _ in progress_positions), default=0)
        tiles_explored = len(progress_positions)
        frontier_credit = 0.0
        if self.best_frontier_score != float("-inf"):
            frontier_credit = max(self.best_frontier_score, 0.0)

        return (
            max_y * self.wipe_progress_max_y_scale
            + tiles_explored * self.wipe_progress_tiles_scale
            + frontier_credit * self.wipe_progress_frontier_scale
        )

    def _frontier_score(self, map_id, pos_a, pos_b):
        frontier_path = self.frontier_path
        if not frontier_path:
            return None

        best_score = None
        if self.best_frontier_score == float("-inf"):
            matching_segments = [idx for idx, (segment_map, _) in enumerate(frontier_path) if map_id == segment_map]
            max_segment_index = matching_segments[0] if matching_segments else 0
        else:
            max_segment_index = int(max(self.best_frontier_score, 0.0) // self.frontier_segment_span) + 1
        for segment_index, (segment_map, target) in enumerate(frontier_path):
            if map_id != segment_map:
                continue
            if segment_index > max_segment_index:
                continue

            base_score = segment_index * self.frontier_segment_span
            if isinstance(target, list):
                reached = 0
                for waypoint_index, waypoint in enumerate(target):
                    if self._target_distance(waypoint, pos_a, pos_b) <= 1:
                        reached = max(reached, waypoint_index + 1)
                next_index = min(reached, len(target) - 1)
                next_target = target[next_index]
                distance = self._target_distance(next_target, pos_a, pos_b)
                score = (
                    base_score
                    + reached * self.frontier_waypoint_span
                    - distance
                )
                best_score = score if best_score is None else max(best_score, score)
                continue

            distance = self._target_distance(target, pos_a, pos_b)
            score = base_score + self.frontier_waypoint_span - distance
            best_score = score if best_score is None else max(best_score, score)

        return best_score

    def _frontier_next_target(self, map_id, pos_a, pos_b):
        frontier_path = self.frontier_path
        if not frontier_path:
            return None

        if self.best_frontier_score == float("-inf"):
            matching_segments = [idx for idx, (segment_map, _) in enumerate(frontier_path) if map_id == segment_map]
            max_segment_index = matching_segments[0] if matching_segments else 0
        else:
            max_segment_index = int(max(self.best_frontier_score, 0.0) // self.frontier_segment_span) + 1

        best_candidate = None
        for segment_index, (segment_map, target) in enumerate(frontier_path):
            if map_id != segment_map or segment_index > max_segment_index:
                continue

            if isinstance(target, list):
                reached = 0
                for waypoint_index, waypoint in enumerate(target):
                    if self._target_distance(waypoint, pos_a, pos_b) <= 1:
                        reached = max(reached, waypoint_index + 1)
                next_index = min(reached, len(target) - 1)
                next_target = target[next_index]
                base_score = segment_index * self.frontier_segment_span
                candidate_score = base_score + reached * self.frontier_waypoint_span
            else:
                next_target = target
                candidate_score = segment_index * self.frontier_segment_span

            if best_candidate is None or candidate_score > best_candidate[0]:
                best_candidate = (candidate_score, next_target)

        if best_candidate is None:
            return None
        return best_candidate[1]

    def _quest_phase_enabled(self, phases):
        return phases is None or self.quest_phase in phases

    def _claim_zone_bonuses(self, map_id, pos_a, pos_b):
        zone_bonuses = self.zone_bonuses
        if (
            not zone_bonuses
            or not self._quest_phase_enabled(
                getattr(self, 'zone_bonus_quest_phases', None)
            )
        ):
            return 0.0

        reward = 0.0
        for zone_index, zone in enumerate(zone_bonuses.get(map_id, [])):
            if self._target_distance(zone['target'], pos_a, pos_b) > zone.get('radius', 0):
                continue
            claim_key = (map_id, zone_index)
            if claim_key in self.claimed_zone_bonuses:
                continue
            self.claimed_zone_bonuses.add(claim_key)
            reward += zone['bonus']
        return reward

    def _is_in_named_zone(self, zones, map_id, pos_a, pos_b):
        if not zones:
            return False

        for zone in zones:
            if map_id != zone.get('map'):
                continue
            if self._target_distance(zone['target'], pos_a, pos_b) <= zone.get('radius', 0):
                return True
        return False

    def _action_guidance_reward(self, map_id, pos_a, pos_b, battle_flag, action):
        guidance = self.action_guidance
        if not self._quest_phase_enabled(
            getattr(self, 'action_guidance_quest_phases', None)
        ):
            return 0.0
        if not guidance and self.frontier_action_guidance_bonus <= 0.0:
            return 0.0
        if self.action_guidance_requires_overworld and battle_flag != 0:
            return 0.0

        reward = 0.0
        for rule in guidance or []:
            if not self._action_guidance_event_allowed(rule):
                continue
            rule_phases = rule.get('quest_phases')
            if (
                rule_phases is not None
                and self.quest_phase not in rule_phases
            ):
                continue
            # Transition rules are paid only after the destination map is
            # observed. Paying for the attempted button press created an
            # unlimited reward source on blocked/pending warp frames.
            if 'destination_map' in rule:
                continue
            if map_id != rule['map']:
                continue
            if self._target_distance(rule['target'], pos_a, pos_b) > rule.get('radius', 0):
                continue
            preferred = rule['action']
            if not isinstance(preferred, (list, tuple, set)):
                preferred = [preferred]
            if int(action) in preferred:
                # Same unlimited-reward class as the transition rule above: a
                # route bonus is for *making* the guided move, not for holding
                # the tile.  A blocked forced tile otherwise farms it every
                # step -- the Route 12 wall paid 150 x 4096 = 614k/episode
                # while the worker never moved.  Legitimate multi-step waits
                # (facing latches, dialogue taps, warp settles) finish well
                # inside the grace window, so they are unaffected.
                if (
                    int(getattr(self, 'same_position_step_count', 0))
                    <= ACTION_GUIDANCE_STATIONARY_BONUS_STEPS
                ):
                    reward += rule.get('bonus', 0.0)
            else:
                reward -= rule.get('penalty', 0.0)

        if self.frontier_action_guidance_bonus > 0.0:
            next_target = self._frontier_next_target(map_id, pos_a, pos_b)
            preferred = []
            if isinstance(next_target, tuple):
                target_y, target_x = next_target
                if pos_a > target_y:
                    preferred.append(0)
                elif pos_a < target_y:
                    preferred.append(1)
                if pos_b > target_x:
                    preferred.append(2)
                elif pos_b < target_x:
                    preferred.append(3)
            elif next_target is not None:
                if pos_a > next_target:
                    preferred.append(0)
                elif pos_a < next_target:
                    preferred.append(1)

            if preferred:
                if int(action) in preferred:
                    reward += self.frontier_action_guidance_bonus
                else:
                    reward -= self.frontier_action_guidance_penalty
        return reward

    def _matching_transition_guidance(self, map_id, pos_a, pos_b, battle_flag, action):
        if self.action_guidance_requires_overworld and battle_flag != 0:
            return None
        for rule_index, rule in enumerate(self.action_guidance or []):
            if not self._action_guidance_event_allowed(rule):
                continue
            rule_phases = rule.get('quest_phases')
            if (
                rule_phases is not None
                and self.quest_phase not in rule_phases
            ):
                continue
            if 'destination_map' not in rule or map_id != rule['map']:
                continue
            if self._target_distance(rule['target'], pos_a, pos_b) > rule.get('radius', 0):
                continue
            preferred = rule['action']
            if not isinstance(preferred, (list, tuple, set)):
                preferred = [preferred]
            if rule.get('force_action') or int(action) in preferred:
                return rule_index, rule
        return None

    def _action_guidance_event_allowed(self, rule):
        is_explorer = bool(getattr(self, 'is_swarm_explorer', False))
        if rule.get('explorer_workers_only') and not is_explorer:
            return False
        if rule.get('training_workers_only') and is_explorer:
            return False
        if int(self.pyboy.memory[ADDR_LEVEL]) < int(
            rule.get('min_lead_level', 1)
        ):
            return False
        if (
            'min_party_hp_fraction' in rule
            or 'max_party_hp_fraction' in rule
        ):
            snapshot = self._party_hp_snapshot()
            current_hp, maximum_hp = self._party_hp_totals(snapshot)
            hp_fraction = (
                current_hp / maximum_hp if maximum_hp > 0 else 0.0
            )
            if hp_fraction < float(rule.get('min_party_hp_fraction', 0.0)):
                return False
            if hp_fraction > float(rule.get('max_party_hp_fraction', 1.0)):
                return False
        required_bits = rule.get('require_event_bits', ())
        if not all(self._event_flag_is_set(bit) for bit in required_bits):
            return False
        unless_bits = rule.get('unless_event_bits', ())
        if any(self._event_flag_is_set(bit) for bit in unless_bits):
            return False
        required_items = rule.get('require_bag_item_ids', ())
        if not all(self._bag_contains_item(item_id) for item_id in required_items):
            return False
        unless_items = rule.get('unless_bag_item_ids', ())
        if any(self._bag_contains_item(item_id) for item_id in unless_items):
            return False
        last_blackout_map = int(self.pyboy.memory[ADDR_LAST_BLACKOUT_MAP])
        if (
            'require_blackout_map' in rule
            and last_blackout_map != int(rule['require_blackout_map'])
        ):
            return False
        if (
            'unless_blackout_map' in rule
            and last_blackout_map == int(rule['unless_blackout_map'])
        ):
            return False
        start_phases = rule.get('episode_start_phases')
        if (
            start_phases is not None
            and int(getattr(self, '_episode_start_quest_phase', -1))
            not in frozenset(start_phases)
        ):
            return False
        return True

    def _matching_forced_action_guidance(
        self, map_id, pos_a, pos_b, battle_flag, consume_face_action=True
    ):
        """Return a phase-scoped forced interaction or warp instruction."""
        raw_battle = 0
        memory = getattr(getattr(self, 'pyboy', None), 'memory', None)
        if memory is not None:
            try:
                raw_battle = int(memory[ADDR_BATTLE_FLAG])
            except (KeyError, TypeError, ValueError):
                raw_battle = 0
        if self.action_guidance_requires_overworld and (
            battle_flag != 0 or raw_battle != 0
        ):
            return None
        self._clear_stale_overworld_joy_ignore()
        self._settle_bills_house_pending_warp()
        self._settle_cerulean_trash_house_pending_warp()
        self._settle_cerulean_bike_ledge_pocket()
        self._restore_glitched_map57_identity()
        self._settle_bike_shop_pending_warp()
        self._settle_vermilion_center_pending_warp()
        self._settle_vermilion_gym_pending_warp()
        self._settle_vermilion_side_house_pending_warp()
        self._settle_rock_tunnel_center_pending_warp()
        if self._settle_victory_road_1f_pending_warp():
            map_id = int(self.pyboy.memory[ADDR_MAP_ID])
            pos_a = int(self.pyboy.memory[ADDR_POS_A])
            pos_b = int(self.pyboy.memory[ADDR_POS_B])
        if self._settle_indigo_lobby_pending_warp():
            map_id = int(self.pyboy.memory[ADDR_MAP_ID])
            pos_a = int(self.pyboy.memory[ADDR_POS_A])
            pos_b = int(self.pyboy.memory[ADDR_POS_B])
        self._clear_rock_tunnel_overworld_joy_ignore()
        self._settle_saffron_gym_exit_door()
        self._heal_if_exiting_rock_tunnel()
        tower_post_rival_action = pokemon_tower_post_rival_forced_action(
            map_id, self.quest_phase, pos_a, pos_b,
        )
        if tower_post_rival_action is not None:
            return tower_post_rival_action
        text_box_active = int(self.pyboy.memory[ADDR_TEXT_BOX]) != 0
        if (
            text_box_active
            and int(map_id) == 92
            and self.quest_phase == FULLGAME_LT_SURGE_QUEST_PHASE
            and int(self.pyboy.memory[ADDR_BATTLE_FLAG]) == 0
        ):
            return 4
        # Route 5 (map 16): leaving the underground latches wJoyIgnore=0xFF
        # (ADDR_TEXT_BOX) and the hole is pret (17, 27). Live pile (28, 18)
        # force-UP walks onto the hole or sits ignored. Clear the latch and
        # step east of x=18 before climbing.
        if (
            int(map_id) == 16
            and self.quest_phase == FULLGAME_BICYCLE_QUEST_PHASE
        ):
            if int(self.pyboy.memory[ADDR_TEXT_BOX]) != 0:
                self.pyboy.memory[ADDR_TEXT_BOX] = 0
            if int(pos_b) >= 16 and int(pos_a) >= 26:
                return 2
        # Bike shop door mats. Entry text + Pikachu on (6,2) freeze UP
        # from (7,2). After the voucher is redeemed, do NOT return None
        # here -- that skipped POST_SURGE_BIKE_SHOP_LEAVE and the policy
        # walked north through the counter onto unused map 57.
        if (
            int(map_id) == 66
            and self.quest_phase in {
                FULLGAME_BICYCLE_QUEST_PHASE,
                FULLGAME_RETURN_ROUTE24_CHARMANDER_QUEST_PHASE,
            }
        ):
            shop_pos = (int(pos_a), int(pos_b))
            bicycle_owned = self._event_flag_is_set(EVENT_GOT_BICYCLE)
            if bicycle_owned:
                if int(self.pyboy.memory[ADDR_TEXT_BOX]) != 0:
                    self.pyboy.memory[ADDR_TEXT_BOX] = 0
                self.pyboy.memory[ADDR_LAST_MAP] = 3
                if shop_pos in {(7, 2), (7, 3)}:
                    return 1
            elif shop_pos != (3, 6):
                # Yellow can reassert the Pikachu-entry font latch after the
                # door mat, most often at (3,3). Clear both proxies while
                # walking; the clerk tile is excluded because its real
                # voucher dialogue is owned by the redemption helper.
                self.pyboy.memory[ADDR_TEXT_BOX] = 0
                self.pyboy.memory[ADDR_FONT_LOADED] = 0
            if not bicycle_owned and shop_pos == (7, 2):
                return 3
            elif not bicycle_owned and shop_pos == (7, 3):
                return 0
        # Fan Club door mat (7, 2)/(7, 3). Yellow's Pikachu/Seel script
        # opens text on entry; converting force-UP to A leaves the whole
        # swarm on the warp tile. A a few times, then walk north.
        if (
            int(map_id) == 90
            and (int(pos_a), int(pos_b)) in ((7, 2), (7, 3), (13, 9))
            and self.quest_phase == FULLGAME_BIKE_VOUCHER_QUEST_PHASE
            and not self._event_flag_is_set(EVENT_GOT_BIKE_VOUCHER)
        ):
            stuck = int(getattr(self, 'same_position_step_count', 0))
            if text_box_active and stuck < 4:
                return 4
            # Pikachu often blocks x=2; step to x=3 then climb.
            if (int(pos_a), int(pos_b)) == (7, 2) and stuck >= 8:
                return 3
            return 0
        if not text_box_active:
            gym_action = self._vermilion_gym_forced_action(consume_face_action)
            if gym_action is not None:
                return gym_action
        guidance_sets = [self.action_guidance or ()]
        if (
            self.completed_run_recovery_after_steps > 0
            and int(getattr(self, 'quest_phase_step_count', 0))
            >= self.completed_run_recovery_after_steps
        ):
            guidance_sets.append(self.completed_run_recovery_guidance)
        for guidance in guidance_sets:
            for rule in guidance:
                if not self._action_guidance_event_allowed(rule):
                    continue
                if not rule.get('force_action'):
                    continue
                if (
                    rule.get('route_workers_only')
                    and not swarm_worker_uses_verified_route_guidance(
                        getattr(self, 'is_swarm_drill_worker', False),
                        getattr(self, 'swarm_mastery_enabled', False),
                        rule.get('verified_route', False),
                    )
                ):
                    continue
                rule_phases = rule.get('quest_phases')
                if rule_phases is not None and self.quest_phase not in rule_phases:
                    continue
                if map_id != rule['map']:
                    continue
                if self._target_distance(rule['target'], pos_a, pos_b) > rule.get('radius', 0):
                    continue
                preferred = rule['action']
                if isinstance(preferred, (list, tuple, set)):
                    preferred = next(iter(preferred))
                # Trainer callouts set wJoyIgnore. Holding a cardinal there
                # cancels the script. A leftover connection-tile joyignore
                # (Route 25 west landing) is NOT a callout -- skip only when
                # a real trainer battle byte is still set.
                # Overworld dialog (battle 0) is the other trap: force-DOWN
                # on Melanie's talk tile after event 168 never reached the
                # 8-step A fallback, so 96/96 froze in the gift text.
                # CD6B=1 is Rock Tunnel's *normal* overworld (A ignored).
                # Treating it as dialog mashed A on JrF's B1F sight tile
                # (14,11) and cancelled the approach; 96/96 sat there.
                if (
                    text_box_active
                    and rule.get('face_action') is None
                    and int(preferred) != 4
                ):
                    battle_now = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
                    joy = int(self.pyboy.memory[ADDR_TEXT_BOX])
                    if battle_now == 2:
                        continue
                    if battle_now == 0 and joy != 1:
                        return 4
                # Unbeaten Rock Tunnel trainers: a corridor cardinal on
                # their vision tile cancels EngageMapTrainer. Noop also
                # stalls -- gen 1 only checks sight when the player steps.
                # Walk toward the sprite; bumping it starts the fight.
                if (
                    int(preferred) in (0, 1, 2, 3)
                    and int(self.pyboy.memory[ADDR_BATTLE_FLAG]) == 0
                ):
                    sight = ROCK_TUNNEL_TRAINER_SIGHT_TILES.get(
                        (int(map_id), int(pos_a), int(pos_b))
                    )
                    if sight is not None:
                        sight_bit, toward = sight
                        if not self._event_flag_is_set(sight_bit):
                            return int(toward)
                face_action = rule.get('face_action')
                if face_action is not None:
                    interaction_key = (map_id, tuple(rule['target']))
                    if getattr(self, '_forced_interaction_face_key', None) != interaction_key:
                        # Swarm sync asks which direction is forced so it can avoid
                        # replacing a worker mid-route.  That read-only query must
                        # not consume the one step which actually turns the player
                        # toward an adjacent NPC.
                        # A nonzero wJoyIgnore can also absorb that turn.  Do not
                        # consume it until Yellow will accept player input: the
                        # live Celadon route arrived beside Erika with D730=1
                        # after the preceding trainer outro, consumed UP while it
                        # was ignored, then pressed A sideways for the rest of
                        # every episode.  Repeating the face action lets the
                        # ordinary bounded stale-latch clear run first.
                        if consume_face_action and int(
                            self.pyboy.memory[ADDR_TEXT_BOX]
                        ) == 0:
                            self._forced_interaction_face_key = interaction_key
                        return int(face_action)
                return int(preferred)
        if text_box_active and int(self.pyboy.memory[ADDR_BATTLE_FLAG]) in (1, 2):
            # Stale D057 plus post-battle text: directional force is skipped
            # above, so mash A through the trainer outro.
            return 4
        if (
            text_box_active
            and int(self.pyboy.memory[ADDR_BATTLE_FLAG]) == 0
            and int(getattr(self, 'same_position_step_count', 0)) >= 8
            and int(self.pyboy.memory[ADDR_TEXT_BOX]) != 1
        ):
            if victory_road_1f_pending_warp(map_id, pos_a, pos_b):
                return None
            if int(map_id) == 174 and (int(pos_a), int(pos_b)) in {(11, 7), (11, 8)}:
                return None
            return 4
        self._forced_interaction_face_key = None
        return None

    def _finish_guided_transition(self, match):
        """Give a correctly launched warp time to complete, without forcing it."""
        if match is None:
            return 0
        _, rule = match
        destination_map = int(rule['destination_map'])
        remaining = max(0, int(rule.get('wait_ticks', 0)))
        ticks_used = 0
        while remaining > 0 and int(self.pyboy.memory[ADDR_MAP_ID]) != destination_map:
            chunk = min(remaining, 4)
            self.pyboy.tick(chunk)
            ticks_used += chunk
            remaining -= chunk
            if self._force_repel_is_active():
                self.pyboy.memory[ADDR_REPEL] = 255
        return ticks_used

    def _claim_transition_guidance_reward(self, match, map_id):
        if match is None:
            return 0.0
        rule_index, rule = match
        if int(map_id) != int(rule['destination_map']):
            return 0.0
        if rule_index in self.claimed_transition_guidance:
            return 0.0
        self.claimed_transition_guidance.add(rule_index)
        return float(rule.get('transition_bonus', 0.0))

    def _apply_auto_wait(self):
        zones = self.auto_wait_zones
        if not zones:
            return 0

        map_id = self.pyboy.memory[ADDR_MAP_ID]
        pos_a = self.pyboy.memory[ADDR_POS_A]
        pos_b = self.pyboy.memory[ADDR_POS_B]

        for zone in zones:
            if map_id != zone.get('map'):
                continue
            if self._target_distance(zone['target'], pos_a, pos_b) > zone.get('radius', 0):
                continue

            ticks = int(zone.get('ticks', 0))
            if ticks <= 0:
                return 0

            remaining = ticks
            while remaining > 0:
                chunk = min(remaining, 32)
                self.pyboy.tick(chunk)
                remaining -= chunk
                if self._force_repel_is_active():
                    self.pyboy.memory[ADDR_REPEL] = 255
            return ticks

        return 0

    def _settle_after_possible_transition(self, prev_map_id):
        ticks = self.post_transition_settle_ticks
        if ticks <= 0:
            return 0

        map_id = int(self.pyboy.memory[ADDR_MAP_ID])
        should_settle = map_id != int(prev_map_id) or map_id == 255
        if (
            not should_settle
            and self.allowed_maps is not None
            and map_id not in self.allowed_maps
        ):
            should_settle = True
        if not should_settle:
            return 0

        remaining = ticks
        while remaining > 0:
            chunk = min(remaining, 32)
            self.pyboy.tick(chunk)
            remaining -= chunk
            if self._force_repel_is_active():
                self.pyboy.memory[ADDR_REPEL] = 255
        return ticks

    def _force_repel_is_active(self):
        """Keep mandatory traversal deterministic without disabling grind encounters."""
        grind = getattr(self, 'wild_battle_quest_phases', None)
        if grind and self.quest_phase in grind:
            # The Soul/Marsh ladder's demonstrated grind patch is Route 15.
            # Route 12 -> 14 is mandatory transit to that patch, not part of
            # the grind. Letting wilds fire throughout the coast made a Route
            # 14 wild plus one mandatory trainer consume the full party before
            # workers could reach Route 15 or Fuchsia. Keep Repel active until
            # map 26, then stop refreshing it so the intended grass patrol can
            # produce encounters and XP normally.
            if self.quest_phase in FULLGAME_SOUL_MARSH_GRIND_PHASES:
                try:
                    map_id = int(self.pyboy.memory[ADDR_MAP_ID])
                except (AttributeError, KeyError, TypeError, ValueError):
                    map_id = 26
                if map_id != 26:
                    return bool(
                        self.force_repel
                        or self._quest_phase_forces_repel()
                    )
            return False
        return bool(
            self.force_repel
            or self._quest_phase_forces_repel()
        )

    def _maintain_force_repel_memory(self):
        """Make force-repel absolute even when the lead is under-leveled.

        Gen I Repel permits encounters at or above the lead Pokemon's level.
        Keeping only wRepelRemainingSteps at 255 therefore did not protect the
        level-5 Viridian Forest frontier. Zeroing the currently loaded grass
        and water encounter rates prevents wild encounter generation while
        leaving trainer sight-line scripts and battle flags untouched.
        """
        if not self._force_repel_is_active():
            return False
        memory = self.pyboy.memory
        memory[ADDR_REPEL] = 255
        memory[ADDR_GRASS_RATE] = 0
        memory[ADDR_WATER_RATE] = 0
        return True

    def _quest_phase_forces_repel(self):
        if self.quest_phase not in self.force_repel_quest_phases:
            return False
        minimum_level = int(
            self.force_repel_min_lead_levels.get(self.quest_phase, 1)
        )
        return int(self.pyboy.memory[ADDR_LEVEL]) >= minimum_level

    def _clear_stale_battle_flag_if_ready(self):
        if self.stale_battle_flag_clear_steps <= 0:
            return False

        battle_flag = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
        enemy_hp = int(self.pyboy.memory[ADDR_ENEMY_HP])
        text_box = int(self.pyboy.memory[ADDR_TEXT_BOX])
        if battle_flag not in (1, 2) or enemy_hp > 0 or text_box != 0:
            if battle_flag == 0 or enemy_hp > 0:
                self.zero_hp_battle_step_count = 0
            return False

        if self.zero_hp_battle_step_count < self.stale_battle_flag_clear_steps:
            return False

        self.pyboy.memory[ADDR_BATTLE_FLAG] = 0
        self.suppress_stale_battle_reassertion = False
        self.stale_battle_stationary_evidence_steps = 0
        self.last_battle_flag = 0
        self.current_battle_step_count = 0
        self.zero_hp_battle_step_count = 0
        self.stale_battle_flag_clears += 1
        return True

    def _clear_stale_overworld_joy_ignore(self):
        if int(self.pyboy.memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        joy = int(self.pyboy.memory[ADDR_TEXT_BOX])
        if joy in (0, 0xFF):
            return False
        map_id = int(self.pyboy.memory[ADDR_MAP_ID])
        if map_id == 88:
            return False
        # CD6B=1 is normal overworld in Rock Tunnel. Zeroing it mid-approach
        # aborts EngageMapTrainer the same way zeroing $FF does.
        if map_id in (82, 232):
            return False
        # Route 25 west landing (x<=1) latches a stale ignore. Everywhere
        # else on this map a 2-step clear aborts trainer callouts (Lass 2
        # at (37,5) never started because we zeroed CD6B mid-script).
        pos_b = int(self.pyboy.memory[ADDR_POS_B])
        wait = 2 if (map_id == 36 and pos_b <= 1) else 8
        if int(getattr(self, 'same_position_step_count', 0)) < wait:
            return False
        self.pyboy.memory[ADDR_TEXT_BOX] = 0
        return True

    def _settle_bills_house_pending_warp(self):
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 88:
            return False
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        if pos_a <= 8 and pos_b <= 8:
            return False
        # Outdoor coords on map 88 are a warp in flight. Entering wants the
        # indoor door; leaving must not be poked -- writing (7,2) mid-exit
        # corrupts Yellow into map 57 (Pewter Speech House) with garbage RAM.
        leaving = (
            self._event_flag_is_set(1372)
            or self._event_flag_is_set(1375)
            or self.quest_phase == FULLGAME_ROUTE25_HEAL_QUEST_PHASE
        )
        if leaving:
            return False
        if self.quest_phase not in {
            FULLGAME_ENTER_BILLS_HOUSE_QUEST_PHASE,
            FULLGAME_RETURN_TO_BILLS_HOUSE_QUEST_PHASE,
            FULLGAME_MEET_BILL_QUEST_PHASE,
        }:
            return False
        memory[ADDR_POS_A] = 7
        memory[ADDR_POS_B] = 2
        return True


    def _settle_vermilion_side_house_pending_warp(self):
        """Snap city-door coords on Vermilion indoor maps to the mat."""
        memory = self.pyboy.memory
        map_id = int(memory[ADDR_MAP_ID])
        # 90 fan club, 91 mart, 93 pidgey house, 163 old rod, 196 trade.
        if map_id not in {90, 91, 93, 163, 196}:
            return False
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        if pos_a <= 7 and pos_b <= 7:
            return False
        memory[ADDR_POS_A] = 7
        memory[ADDR_POS_B] = 2
        return True

    def _settle_vermilion_gym_pending_warp(self):
        """Snap outdoor gym-door coords on map 92 to the indoor mat."""
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 92:
            return False
        if int(memory[ADDR_POS_A]) <= 17:
            return False
        if self.quest_phase not in {
            FULLGAME_VERMILION_GYM_QUEST_PHASE,
            FULLGAME_LT_SURGE_QUEST_PHASE,
        }:
            return False
        if self._event_flag_is_set(359):
            return False
        memory[ADDR_POS_A] = 17
        memory[ADDR_POS_B] = 4
        return True

    def _vermilion_gym_target_can(self):
        """Return (y, x) of the next trash can, or None if locks are done."""
        if self._event_flag_is_set(EVENT_2ND_LOCK_OPENED):
            return None
        memory = self.pyboy.memory
        if not self._event_flag_is_set(EVENT_1ST_LOCK_OPENED):
            index = int(memory[ADDR_FIRST_LOCK_TRASH_CAN]) & 0x0F
        else:
            index = int(memory[ADDR_SECOND_LOCK_TRASH_CAN])
            if index > 14:
                index = int(memory[ADDR_SECOND_LOCK_TRASH_CAN + 1])
        if index > 14:
            return None
        return VERMILION_GYM_TRASH_CANS[index]

    def _vermilion_gym_forced_action(self, consume_face_action=True):
        """Walk the trash-can puzzle, then Lt. Surge, from RAM lock indices."""
        if self.quest_phase != FULLGAME_LT_SURGE_QUEST_PHASE:
            return None
        if self._event_flag_is_set(359):
            return None
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 92:
            return None
        y = int(memory[ADDR_POS_A])
        x = int(memory[ADDR_POS_B])
        walkable = set(VERMILION_GYM_WALKABLE)
        if self._event_flag_is_set(EVENT_2ND_LOCK_OPENED):
            walkable.update(VERMILION_GYM_NORTH_WALKABLE)
        for event_bit, sightline in VERMILION_GYM_TRAINER_SIGHTLINES.items():
            if not self._event_flag_is_set(event_bit):
                walkable.difference_update(sightline)
        can = self._vermilion_gym_target_can()
        if can is None:
            goals = {(2, 5)}
            if (y, x) == (2, 5):
                key = (92, (2, 5), 'surge')
                if getattr(self, '_forced_interaction_face_key', None) != key:
                    if consume_face_action:
                        self._forced_interaction_face_key = key
                    return 0
                return 4
            return gym_bfs_first_action(walkable, (y, x), goals)
        stands = vermilion_gym_stand_tiles(can[0], can[1], walkable)
        if not stands:
            return None
        here = next((face for sy, sx, face in stands if (sy, sx) == (y, x)), None)
        if here is not None:
            key = (92, can)
            if getattr(self, '_forced_interaction_face_key', None) != key:
                if consume_face_action:
                    self._forced_interaction_face_key = key
                return int(here)
            return 4
        return gym_bfs_first_action(
            walkable, (y, x), {(sy, sx) for sy, sx, _ in stands},
        )

    def _settle_vermilion_center_pending_warp(self):
        """Snap city door coords on map 89 to the indoor mat."""
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 89:
            return False
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        if pos_b <= 8 and pos_a <= 8:
            return False
        memory[ADDR_POS_A] = 7
        memory[ADDR_POS_B] = 3
        return True

    def _settle_saffron_gym_exit_door(self):
        """Point the gym mats at Saffron and allow Down through wJoyIgnore.

        CD6B=1 is ordinary overworld and bit 0 ignores Down. The exit mats
        are LAST_MAP warps at (17,8)/(17,9); without Down they never fire,
        which is the live phase-217 pile. LAST_MAP must be Saffron (10),
        not the Celadon blackout map left in wLastMap from the last heal.
        """
        memory = self.pyboy.memory
        if not self._event_flag_is_set(EVENT_BEAT_SABRINA):
            return False
        if int(memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        map_id = int(memory[ADDR_MAP_ID])
        pos = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if map_id == 178 and pos in {(17, 8), (17, 9)}:
            memory[ADDR_LAST_MAP] = 10
            if int(memory[ADDR_TEXT_BOX]) not in (0, 0xFF):
                memory[ADDR_TEXT_BOX] = 0
            return True
        if map_id == 10 and pos in {(3, 34), (3, 35)}:
            if int(memory[ADDR_TEXT_BOX]) not in (0, 0xFF):
                memory[ADDR_TEXT_BOX] = 0
            return True
        return False

    def _settle_rock_tunnel_center_pending_warp(self):
        """Snap outdoor door coords on map 81 to the indoor south mat."""
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 81:
            return False
        if self.quest_phase != FULLGAME_ROCK_TUNNEL_ENTRY_QUEST_PHASE:
            return False
        memory[ADDR_LAST_MAP] = 21
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        if pos_a <= 7 and pos_b <= 13:
            return False
        # pret Center door is (3,7)/(4,7). Live workers kept Route 10
        # (19,11) after the map id flipped to 81.
        memory[ADDR_POS_A] = 7
        memory[ADDR_POS_B] = 3
        return True

    def _settle_victory_road_1f_pending_warp(self):
        """Finish the Route 23 -> 1F warp instead of acting on (31, 4).

        Do not poke (17, 8): that skips object load and leaves the boulder at
        garbage coordinates so the 1F Strength solver never matches.
        """
        memory = self.pyboy.memory
        if not victory_road_1f_pending_warp(
            int(memory[ADDR_MAP_ID]),
            int(memory[ADDR_POS_A]),
            int(memory[ADDR_POS_B]),
        ):
            return False
        if int(memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        for _ in range(180):
            self.pyboy.tick()
            if self._force_repel_is_active():
                memory[ADDR_REPEL] = 255
            if (
                int(memory[ADDR_MAP_ID]) == 108
                and not victory_road_1f_pending_warp(
                    108,
                    int(memory[ADDR_POS_A]),
                    int(memory[ADDR_POS_B]),
                )
                and int(memory[ADDR_TEXT_BOX]) == 0
                and int(memory[ADDR_FONT_LOADED]) == 0
            ):
                memory[ADDR_LAST_MAP] = 34
                return True
        return (
            int(memory[ADDR_MAP_ID]) == 108
            and not victory_road_1f_pending_warp(
                108,
                int(memory[ADDR_POS_A]),
                int(memory[ADDR_POS_B]),
            )
        )

    def _settle_indigo_lobby_pending_warp(self):
        """Finish the map 9 -> lobby door warp before acting on the mat.

        Live walk-on lands at (11, 7) with wJoyIgnore=0xFF for ~40 ticks.
        Mashing A there opens the menu; LAST_MAP must stay Indigo outdoor (9)
        so Down on the mat does not Fly-leak to Cinnabar.
        """
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 174:
            return False
        if int(memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        pos = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if pos not in {(11, 7), (11, 8)}:
            return False
        memory[ADDR_LAST_MAP] = 9
        if int(memory[ADDR_TEXT_BOX]) != 0xFF:
            return False
        for _ in range(90):
            self.pyboy.tick()
            if int(memory[ADDR_TEXT_BOX]) == 0:
                memory[ADDR_LAST_MAP] = 9
                return True
        return int(memory[ADDR_TEXT_BOX]) == 0

    def _clear_rock_tunnel_overworld_joy_ignore(self):
        """CD6B=1 is normal overworld and bit 0 ignores DOWN."""
        if self.quest_phase not in FULLGAME_ROCK_TUNNEL_INTERIOR_PHASES:
            return False
        if int(self.pyboy.memory[ADDR_MAP_ID]) not in (82, 232):
            return False
        if int(self.pyboy.memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        if int(self.pyboy.memory[ADDR_TEXT_BOX]) in (0, 0xFF):
            return False
        self.pyboy.memory[ADDR_TEXT_BOX] = 0
        return True

    def _heal_if_exiting_rock_tunnel(self):
        """Full restore on the 1F exit so JrF2 is not a guaranteed wipe.

        The south warp is behind JrF2's cone; there is no Center in the cave.
        One heal per episode, only on the exit phase, after Hiker1.
        """
        if self.quest_phase != FULLGAME_ROCK_TUNNEL_EXIT_QUEST_PHASE:
            return False
        if int(self.pyboy.memory[ADDR_MAP_ID]) != 82:
            return False
        if getattr(self, "_rock_tunnel_exit_healed", False):
            return False
        if int(self.pyboy.memory[ADDR_BATTLE_FLAG]) in (1, 2):
            return False
        _heal_party_memory(self.pyboy.memory)
        self._rock_tunnel_exit_healed = True
        return True

    def _settle_cerulean_trash_house_pending_warp(self):
        """Snap illegal outdoor coords on map 62 to the indoor door.

        Map 62 is 4x4 (tiles 0-7). City door (27,11) left as-is freezes
        the warp the same way Bill's house did. Exiting the house changes
        map_id to 3, so the backyard tile (27,9) is never poked.
        """
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 62:
            return False
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        if pos_a <= 8 and pos_b <= 8:
            return False
        memory[ADDR_POS_A] = 7
        memory[ADDR_POS_B] = 3
        return True

    def _restore_glitched_map57_identity(self):
        """Undo the shop-leave warp that wrote map/x/badges = 57."""
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 57:
            return False
        if int(memory[ADDR_BADGES]) == 57:
            memory[ADDR_BADGES] = 7
        memory[ADDR_LAST_MAP] = 3
        # Do not poke Cerulean coords onto the unloaded map-57 header;
        # that is itself OOB. Leave guidance will walk a fresh episode
        # out the real shop door once force-action is no longer skipped.
        return False

    def _settle_bike_shop_pending_warp(self):
        """Let the Bike Shop map load fully and preserve its exit warps.

        Writing clerk-side coordinates while the city-to-shop warp was still
        in flight skipped object/warp initialization. It also placed workers
        north of the one-way counter, where no legal route reaches the door.
        """
        memory = self.pyboy.memory
        if int(memory[ADDR_MAP_ID]) != 66:
            return False
        if self.quest_phase not in {
            FULLGAME_BICYCLE_QUEST_PHASE,
            FULLGAME_RETURN_ROUTE24_CHARMANDER_QUEST_PHASE,
        }:
            return False
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        outdoor = pos_a > 8 or pos_b > 8
        if outdoor:
            # Map id flips before Yellow finishes loading the indoor header.
            # Advancing the pending transition keeps wWarpEntries and objects
            # intact; coordinate pokes here create a permanently broken map.
            for _ in range(180):
                self.pyboy.tick()
                if int(memory[ADDR_MAP_ID]) != 66:
                    return True
                if (
                    int(memory[ADDR_POS_A]) <= 8
                    and int(memory[ADDR_POS_B]) <= 8
                ):
                    return True
            return False
        if self._event_flag_is_set(EVENT_GOT_BICYCLE):
            # Keep the real LAST_MAP destination while the customer-side
            # leave route walks onto the intact door warp.
            memory[ADDR_LAST_MAP] = 3
            return False
        return False

    def _settle_cerulean_bike_ledge_pocket(self):
        """Snap the one-way Route 5 ledge ditch onto the bike-shop stand.

        y=33 x=16-23 is overworld ledge $37 (PAD_DOWN only). Live swarm
        jumped it from the north and froze at (34, 16): UP is the ledge,
        LEFT is the x=15 tree. Same pocket exists on Route 5 y=0-2 x=6-13.
        Shop stand is pret south of warp (13, 25).
        """
        if self.quest_phase != FULLGAME_BICYCLE_QUEST_PHASE:
            return False
        if self._event_flag_is_set(EVENT_GOT_BICYCLE):
            return False
        if not self._event_flag_is_set(EVENT_GOT_BIKE_VOUCHER):
            return False
        memory = self.pyboy.memory
        map_id = int(memory[ADDR_MAP_ID])
        pos_a = int(memory[ADDR_POS_A])
        pos_b = int(memory[ADDR_POS_B])
        cerulean_pocket = (
            map_id == 3
            and pos_a >= 33
            and 16 <= pos_b <= 23
        )
        route5_pocket = (
            map_id == 16
            and pos_a <= 2
            and 6 <= pos_b <= 13
        )
        if not (cerulean_pocket or route5_pocket):
            return False
        memory[ADDR_MAP_ID] = 3
        memory[ADDR_POS_A] = 26
        memory[ADDR_POS_B] = 13
        return True

    def _clear_impossible_celadon_center_battle_flag(self):
        """Normalize a stale battle flag along the post-Rocket mart route.

        The bad flag can be reasserted by the emulated battle state after the
        player leaves the Center. Phase 124 is force-repel traversal through
        Celadon and Department Store maps, where no battle is possible, so
        clear it on every map in that guided route.
        """
        memory = self.pyboy.memory
        safe_route_maps = {6, 122, 123, 124, 125, 126, 133, 136}
        if not (
            self.quest_phase == FULLGAME_MART_ROOF_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) in safe_route_maps
            and int(memory[ADDR_BATTLE_FLAG]) in (1, 2)
        ):
            return False
        # The live post-Rocket heal left D056=1 with stale positive enemy HP.
        # Zero-HP recovery cannot catch that. Clear only the impossible raw
        # flag; leave all other battle RAM untouched so later encounters work.
        memory[ADDR_BATTLE_FLAG] = 0
        self.last_battle_flag = 0
        self.current_battle_step_count = 0
        self.zero_hp_battle_step_count = 0
        self.battle_flag_movement_steps = 0
        self.suppress_stale_battle_reassertion = False
        self.stale_battle_stationary_evidence_steps = 0
        self.stale_battle_flag_clears += 1
        return True

    def _clear_stale_battle_flag_on_overworld_movement(self, map_id, pos_a, pos_b):
        """Latch a logical overworld state when D057 contradicts movement.

        A real battle cannot move the player's map coordinates. The 14-hour
        full-game audit found D057 stuck at 1 while agents traversed multiple
        maps, with a stale positive enemy-HP byte preventing the older
        zero-HP-only recovery from ever firing.
        """
        threshold = self.stale_battle_movement_clear_steps
        battle_flag = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
        if threshold <= 0:
            return False
        if battle_flag not in (1, 2):
            self.battle_flag_movement_steps = 0
            self.last_battle_flag_position = None
            self.suppress_stale_battle_reassertion = False
            self.stale_battle_stationary_evidence_steps = 0
            return False

        position = (int(map_id), int(pos_a), int(pos_b))
        enemy_hp = int(self.pyboy.memory[ADDR_ENEMY_HP])
        previous = self.last_battle_flag_position
        self.last_battle_flag_position = position

        if self.suppress_stale_battle_reassertion:
            if previous is not None and position != previous:
                self.stale_battle_stationary_evidence_steps = 0
                return True
            # Do not release the latch for ordinary walls, menus, or dialogue.
            # A new encounter must remain stationary while loading a different
            # enemy HP value for two complete actions. This keeps raw D057
            # untouched so the emulated battle engine can continue normally.
            # A normal overworld dialogue also sets the text-box byte. The
            # old `or text_box != 0` condition therefore released suppression
            # while talking to Bill after Route 25, resurrected the stale
            # trainer flag, and forced A until battle_stall. A different
            # positive enemy HP value is actual battle evidence; dialogue is
            # not.
            if enemy_hp > 0 and enemy_hp != self.stale_battle_enemy_hp:
                self.stale_battle_stationary_evidence_steps += 1
            else:
                self.stale_battle_stationary_evidence_steps = 0
            if self.stale_battle_stationary_evidence_steps >= 2:
                self.suppress_stale_battle_reassertion = False
                self.stale_battle_stationary_evidence_steps = 0
                self.stale_battle_enemy_hp = enemy_hp
                self.battle_flag_movement_steps = 0
                return False
            return True

        if previous is None or position == previous:
            return False

        self.battle_flag_movement_steps += 1
        if self.battle_flag_movement_steps < threshold:
            return False

        # Movement is conclusive: a real battle cannot change map
        # coordinates. Normalize the stale raw flag itself instead of only
        # hiding it behind a latch. The logical-only approach could later
        # release while stale battle RAM changed, resurrecting force-A in
        # Bill's House and consuming the 2,048-step battle budget again.
        self.pyboy.memory[ADDR_BATTLE_FLAG] = 0
        self.last_battle_flag = 0
        self.current_battle_step_count = 0
        self.zero_hp_battle_step_count = 0
        self.battle_flag_movement_steps = 0
        self.suppress_stale_battle_reassertion = False
        self.stale_battle_enemy_hp = enemy_hp
        self.stale_battle_stationary_evidence_steps = 0
        self.stale_battle_flag_clears += 1
        self.stale_battle_movement_clears += 1
        return True

    def _suppress_stale_battle_before_action(self):
        """Hide a battle flag that was already disproved by movement.

        D057 can remain asserted after the battle has ended. Keep the byte
        untouched for the emulated game, but classify it as overworld before
        action selection so battle helpers do not modify battle RAM in town.
        """
        if not self.suppress_stale_battle_reassertion:
            return False
        battle_flag = int(self.pyboy.memory[ADDR_BATTLE_FLAG])
        if battle_flag not in (1, 2):
            return False
        self.last_battle_flag = 0
        self.current_battle_step_count = 0
        self.zero_hp_battle_step_count = 0
        self.stale_battle_reassertion_suppressions += 1
        return True

    def _enemy_hp_can_indicate_battle(self, map_id):
        if self._quest_phase_forces_repel():
            return False
        return self.enemy_hp_battle_proxy_maps is None or int(map_id) in self.enemy_hp_battle_proxy_maps

    def _trainer_battle_is_active(
        self, raw_battle_flag, effective_battle_flag, map_id, enemy_hp
    ):
        """Distinguish real trainer fights from wild fights on trainer maps.

        D057 is authoritative whenever it is 1 (wild) or 2 (trainer).  Map
        membership is only a fallback for the brief enemy-HP proxy window
        before D057 becomes active.  Treating every battle on a map that has
        trainers as a trainer battle made every Mt. Moon wild encounter use
        force-A and mislabeled it in rewards/metrics.
        """
        raw_battle_flag = int(raw_battle_flag)
        effective_battle_flag = int(effective_battle_flag)
        map_id = int(map_id)
        enemy_hp = int(enemy_hp)
        if effective_battle_flag == 2:
            return True
        if raw_battle_flag in (1, 2):
            return False
        return (
            enemy_hp > 0
            and map_id in self.trainer_battle_maps
            and self._enemy_hp_can_indicate_battle(map_id)
        )

    def _record_reward_component(self, name, amount):
        amount = float(amount)
        self.episode_reward_components[name] += amount
        return amount

    def _ensure_forced_attack_ready(self):
        # force_a_in_wild_battles/force_a_in_trainer_battles blindly mash A and
        # rely on move slot 0 being a damaging move with PP left (same assumption
        # ensure_post_brock_route_state's _ensure_lead_attack_memory makes at
        # stage load). That assumption silently breaks mid-episode once slot 0's
        # PP runs dry or a level-up/heal shuffles a status move into slot 0 --
        # the result is exactly the "trainer=1/N battle_stall" loops documented
        # around battle_step_limit: A gets pressed forever with nothing to
        # actually resolve the fight. Re-assert the same guarantee every step
        # instead of only once per stage load.
        memory = self.pyboy.memory
        # Forced-A deliberately owns move selection, so it cannot choose a
        # different slot when Disable targets slot 0. Yellow also does not
        # decrement Disable after a rejected move, producing a permanent
        # "The move is disabled!" loop (live phase 65: D06C=0x16, enemy HP=6,
        # both HP values unchanged for 1,882 steps). Clear only the player's
        # in-battle Disable latch; all damage, PP use, and opponent turns stay
        # inside the genuine battle engine.
        if int(memory[ADDR_PLAYER_DISABLED_MOVE]) != 0:
            memory[ADDR_PLAYER_DISABLED_MOVE] = 0
        if int(memory[ADDR_PARTY_SIZE]) <= 0:
            return
        move_addrs = PARTY_MOVE_ID_ADDRS[0]
        pp_addrs = PARTY_MOVE_PP_ADDRS[0]
        map_id = int(memory[ADDR_MAP_ID])
        brock_ground = (
            map_id == 54
            or int(self.quest_phase) in (
                FULLGAME_BROCK_QUEST_PHASE,
                FULLGAME_PEWTER_GYM_ENTRY_QUEST_PHASE,
            )
        )
        if brock_ground:
            # Grind ThunderShock in slot 0 is 0 damage vs Geodude/Onix.
            # Live beat_brock: 620/620 party_wipe, a:235, HP 0/50.
            self._ensure_brock_attack_ready(allow_electric=False)
        elif (
            int(self.quest_phase) in FULLGAME_PRE_FOREST_GRIND_PHASES
            or int(self.quest_phase) in FULLGAME_PEWTER_GRIND_PHASES
        ):
            ensure_lead_grind_electric_attack(memory)
        move_id = int(memory[move_addrs[0]])
        move_info = GEN1_MOVE_TABLE.get(move_id)
        if move_info is None or move_info['power'] <= 0:
            _ensure_lead_attack_memory(memory)
            move_id = int(memory[move_addrs[0]])
            move_info = GEN1_MOVE_TABLE.get(move_id, GEN1_MOVE_TABLE[PEWTER_FALLBACK_ATTACK_MOVE_ID])
        pp = int(memory[pp_addrs[0]]) & 0x3F
        if pp <= 0:
            pp_ups = int(memory[pp_addrs[0]]) & 0xC0
            memory[pp_addrs[0]] = pp_ups | min(move_info['max_pp'], 0x3F)

        # The FIGHT menu's PP display and "No PP left for this move!" check
        # read wBattleMon's own copy (ADDR_BATTLE_MON_PP), not the party
        # struct refilled above -- it's only copied in from the party struct
        # at battle start or on a mid-battle move-learn, so topping up the
        # party copy alone doesn't stop the in-battle copy from running dry
        # and getting the fight stuck. Keep both in sync the same way.
        battle_pp_addr = ADDR_BATTLE_MON_PP[0]
        battle_move_id = int(memory[ADDR_BATTLE_MON_MOVE_IDS[0]])
        battle_move_info = GEN1_MOVE_TABLE.get(battle_move_id, move_info)
        battle_pp = int(memory[battle_pp_addr]) & 0x3F
        if battle_pp <= 0:
            battle_pp_ups = int(memory[battle_pp_addr]) & 0xC0
            memory[battle_pp_addr] = battle_pp_ups | min(battle_move_info['max_pp'], 0x3F)

    def _ensure_brock_attack_ready(self, allow_electric=False):
        """Put a usable damaging move in slot 0.

        Ground/Rock fights (`allow_electric=False`) cannot use Electric STAB.
        Live beat_brock had ThunderShock in slot 0 and Slam (75% acc) as the
        strongest remaining party attack; force-A then wiped 400/400 Pewter
        Gym episodes after one faint. Prefer a non-Electric move with
        accuracy >= 250 and power >= 60 (Swift, Ice Beam, …). If none exists,
        install Swift into a status/empty slot and promote it so ThunderShock
        is not deleted. Electric-allowed fights still promote the strongest
        damaging move, including Thunderbolt.
        """
        memory = self.pyboy.memory
        swift_id = PEWTER_FALLBACK_ATTACK_MOVE_ID
        swift_info = GEN1_MOVE_TABLE[swift_id]

        def swap(move_addrs, pp_addrs, src):
            if src == 0:
                return
            first_move = int(memory[move_addrs[0]])
            first_pp = int(memory[pp_addrs[0]])
            memory[move_addrs[0]] = int(memory[move_addrs[src]])
            memory[pp_addrs[0]] = int(memory[pp_addrs[src]])
            memory[move_addrs[src]] = first_move
            memory[pp_addrs[src]] = first_pp

        def promote(move_addrs, pp_addrs):
            candidates = []
            for index, (move_addr, pp_addr) in enumerate(zip(move_addrs, pp_addrs)):
                move_id = int(memory[move_addr])
                move_info = GEN1_MOVE_TABLE.get(move_id)
                if (
                    move_info is None
                    or move_info['power'] <= 0
                    or (
                        not allow_electric
                        and move_info['type'] == GEN1_ELECTRIC_TYPE
                    )
                ):
                    continue
                pp = int(memory[pp_addr]) & 0x3F
                if allow_electric:
                    candidates.append(((pp > 0, int(move_info['power'])), index))
                    continue
                accuracy = int(move_info.get('accuracy') or 0)
                power = int(move_info['power'])
                reliable = accuracy >= 250 and power >= 60
                candidates.append(((pp > 0, reliable, accuracy, power), index))

            if allow_electric:
                if candidates:
                    swap(move_addrs, pp_addrs, max(candidates)[1])
                    return
            else:
                reliable = [item for item in candidates if item[0][1]]
                if reliable:
                    swap(move_addrs, pp_addrs, max(reliable)[1])
                    return
                moves = [int(memory[addr]) for addr in move_addrs]
                if swift_id in moves:
                    swap(move_addrs, pp_addrs, moves.index(swift_id))
                    return
                found = next(
                    (
                        idx for idx, move_id in enumerate(moves)
                        if (GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0) <= 0
                    ),
                    0,
                )
                memory[move_addrs[found]] = swift_id
                memory[pp_addrs[found]] = swift_info['max_pp']
                swap(move_addrs, pp_addrs, found)
                return

            memory[move_addrs[0]] = swift_id
            memory[pp_addrs[0]] = swift_info['max_pp']

        if int(memory[ADDR_PARTY_SIZE]) > 0:
            promote(PARTY_MOVE_ID_ADDRS[0], PARTY_MOVE_PP_ADDRS[0])
        promote(ADDR_BATTLE_MON_MOVE_IDS, ADDR_BATTLE_MON_PP)

    def _ensure_bulbasaur_knows_cut(self):
        """Teach the required HM to the gifted Bulbasaur exactly once.

        The live party that received HM01 contains only Pikachu and Caterpie,
        so the old quest order made Vermilion Gym mechanically unreachable.
        Once Melanie's real gift event is durable, install Cut in Bulbasaur's
        ordinary party moveset. Prefer an empty slot, then a status move, so
        this assistance does not discard a useful attack.
        """
        if self.quest_phase != FULLGAME_TEACH_CUT_QUEST_PHASE:
            return False
        if not (
            self._event_flag_is_set(1504)
            and self._event_flag_is_set(168)
        ):
            return False
        memory = self.pyboy.memory
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        for party_index in range(party_size):
            if int(memory[PARTY_SPECIES_ADDRS[party_index]]) != GEN1_BULBASAUR_SPECIES_ID:
                continue
            move_addrs = PARTY_MOVE_ID_ADDRS[party_index]
            pp_addrs = PARTY_MOVE_PP_ADDRS[party_index]
            moves = [int(memory[addr]) for addr in move_addrs]
            if GEN1_CUT_MOVE_ID in moves:
                return True
            replacement = next(
                (idx for idx, move_id in enumerate(moves) if move_id == 0),
                None,
            )
            if replacement is None:
                replacement = next(
                    (
                        idx for idx, move_id in enumerate(moves)
                        if (GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0) <= 0
                    ),
                    3,
                )
            memory[move_addrs[replacement]] = GEN1_CUT_MOVE_ID
            memory[pp_addrs[replacement]] = GEN1_CUT_MAX_PP
            return True
        return False

    def _promote_charmander_family_for_training(self):
        """Move the gifted Charmander family to the lead slot safely.

        A party reorder touches four parallel Gen-1 records: the compact
        species list, the six 44-byte battle structs, OT names, and
        nicknames.  Swapping only the battle struct looks correct in combat
        but corrupts later menus and trades, so keep all four arrays aligned.
        This is scoped to the explicit post-Saffron training curriculum and
        only runs in a quiet overworld frame.
        """
        if self.quest_phase not in (
            FULLGAME_CHARMANDER_GRIND_PHASES
            | {FULLGAME_CHARIZARD_QUEST_PHASE, FULLGAME_TEACH_FLY_QUEST_PHASE}
        ):
            return False
        memory = self.pyboy.memory
        if (
            self._effective_battle_flag() != 0
            or int(memory[ADDR_TEXT_BOX]) != 0
        ):
            return False
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        source_index = next((
            index for index in range(party_size)
            if int(memory[PARTY_SPECIES_ADDRS[index]])
            in GEN1_CHARMANDER_SPECIES_IDS
        ), None)
        if source_index is None:
            return False

        def promote_ember_to_first_move():
            move_addrs = PARTY_MOVE_ID_ADDRS[0]
            pp_addrs = PARTY_MOVE_PP_ADDRS[0]
            moves = [int(memory[addr]) for addr in move_addrs]
            if GEN1_EMBER_MOVE_ID not in moves:
                return
            ember_index = moves.index(GEN1_EMBER_MOVE_ID)
            if ember_index == 0:
                return
            first_move = int(memory[move_addrs[0]])
            first_pp = int(memory[pp_addrs[0]])
            memory[move_addrs[0]] = GEN1_EMBER_MOVE_ID
            memory[pp_addrs[0]] = int(memory[pp_addrs[ember_index]])
            memory[move_addrs[ember_index]] = first_move
            memory[pp_addrs[ember_index]] = first_pp

        if source_index == 0:
            promote_ember_to_first_move()
            self._lead_moveset_snapshot = None
            return True

        def swap_ranges(first, second, length):
            left = bytes(int(memory[first + offset]) for offset in range(length))
            right = bytes(int(memory[second + offset]) for offset in range(length))
            for offset, value in enumerate(right):
                memory[first + offset] = value
            for offset, value in enumerate(left):
                memory[second + offset] = value

        compact_first = ADDR_PARTY_SPECIES_LIST
        compact_source = compact_first + source_index
        first_species = int(memory[compact_first])
        memory[compact_first] = int(memory[compact_source])
        memory[compact_source] = first_species
        swap_ranges(
            FIRST_PARTY_SPECIES_ADDR,
            FIRST_PARTY_SPECIES_ADDR + source_index * PARTY_DATA_STRIDE,
            PARTY_DATA_STRIDE,
        )
        swap_ranges(
            ADDR_PARTY_OT,
            ADDR_PARTY_OT + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        swap_ranges(
            ADDR_PARTY_NICKS,
            ADDR_PARTY_NICKS + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        # This recorded Route 4 encounter defeats Scratch Charmander one turn
        # before the KO. Ember's STAB wins it and forced-A selects slot zero.
        promote_ember_to_first_move()
        self._lead_moveset_snapshot = None
        return True

    def _maintain_charmander_training_resources(self):
        """Keep the Route 4 level grind viable between honest encounters.

        The level-10 victory ends at 2 HP. Without an intervening guard, the
        forced patrol enters another encounter before the long Cerulean
        return route or swarm sync can run, and fainted Charmander earns no
        experience. Scope recovery to the explicit Charmander grind, only in
        overworld frames, and only below the same 65% retreat threshold (or
        when Ember is nearly exhausted).
        """
        if self.quest_phase not in FULLGAME_CHARMANDER_GRIND_PHASES:
            return False
        memory = self.pyboy.memory
        if (
            self._effective_battle_flag() != 0
            or int(memory[ADDR_PARTY_SIZE]) <= 0
            or int(memory[PARTY_SPECIES_ADDRS[0]])
            not in GEN1_CHARMANDER_SPECIES_IDS
        ):
            return False
        cur_hi, cur_lo = PARTY_CUR_HP_ADDRS[0]
        max_hi, max_lo = PARTY_MAX_HP_ADDRS[0]
        current_hp = (int(memory[cur_hi]) << 8) | int(memory[cur_lo])
        maximum_hp = (int(memory[max_hi]) << 8) | int(memory[max_lo])
        ember_pp = 0
        for move_addr, pp_addr in zip(
            PARTY_MOVE_ID_ADDRS[0], PARTY_MOVE_PP_ADDRS[0]
        ):
            if int(memory[move_addr]) == GEN1_EMBER_MOVE_ID:
                ember_pp = int(memory[pp_addr]) & 0x3F
                break
        low_health = maximum_hp > 0 and current_hp * 100 < maximum_hp * 65
        low_ember_pp = ember_pp <= 3
        if not (low_health or low_ember_pp):
            return False
        _heal_party_memory(memory)
        _restore_party_pp_memory(memory)
        return True

    def _maintain_mansion_training_resources(self):
        """Preserve Mansion XP between level checkpoints.

        The live level-51 frontier entered 13--24 honest wild encounters per
        episode but repeatedly wiped before level 52, discarding every bit of
        uncheckpointed XP.  Recover only between battles, only on Mansion
        maps, and only during the explicit level-51..70 curriculum.
        """
        if self.quest_phase not in FULLGAME_MANSION_GRIND_PHASES:
            return False
        memory = self.pyboy.memory
        if (
            int(memory[ADDR_MAP_ID]) not in {165, 214, 215, 216}
            or self._effective_battle_flag() != 0
            or int(memory[ADDR_PARTY_SIZE]) <= 0
            or int(memory[PARTY_SPECIES_ADDRS[0]]) != GEN1_PIKACHU_SPECIES_ID
        ):
            return False
        cur_hi, cur_lo = PARTY_CUR_HP_ADDRS[0]
        max_hi, max_lo = PARTY_MAX_HP_ADDRS[0]
        current_hp = (int(memory[cur_hi]) << 8) | int(memory[cur_lo])
        maximum_hp = (int(memory[max_hi]) << 8) | int(memory[max_lo])
        attack_pp = [
            int(memory[pp_addr]) & 0x3F
            for move_addr, pp_addr in zip(
                PARTY_MOVE_ID_ADDRS[0], PARTY_MOVE_PP_ADDRS[0]
            )
            if (GEN1_MOVE_TABLE.get(int(memory[move_addr])) or {}).get('power', 0) > 0
        ]
        low_health = maximum_hp > 0 and current_hp * 100 < maximum_hp * 80
        low_attack_pp = bool(attack_pp) and max(attack_pp) <= 5
        if not (low_health or low_attack_pp):
            return False
        _heal_party_memory(memory)
        _restore_party_pp_memory(memory)
        return True

    def _lead_charizard_for_saffron_gym(self):
        """Put Charizard in front for the Marsh Badge.

        Pikachu leads the whole late game, and against Sabrina that is the
        wrong Pokemon by a wide margin: its Thunderbolt is a SPECIAL move
        driven by a Special stat of 71, aimed into Gen 1 Psychics whose
        Special is their best stat (Alakazam's is enormous). Charizard is
        sitting in slot two at L39 with 128 HP, Attack 89 and Slash -- a
        PHYSICAL 70-power move with a high crit ratio -- and Gen 1 Psychics
        have paper Defense. Probe evidence that healing is not the lever: the
        Pikachu lead survived four different bounded heal policies and still
        could not finish her, timing out at 6,000 battle steps every time,
        while the live swarm lost all 38,304 episodes with an identical
        9-faint signature. Reorder all four parallel party records the same
        way _promote_charmander_family_for_training does.
        """
        if not (
            self.quest_phase == FULLGAME_SABRINA_QUEST_PHASE
            and int(self.pyboy.memory[ADDR_MAP_ID]) == 178
            and not self._event_flag_is_set(EVENT_BEAT_SABRINA)
        ):
            return False
        memory = self.pyboy.memory
        if (
            self._effective_battle_flag() != 0
            or int(memory[ADDR_TEXT_BOX]) != 0
        ):
            return False
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        source_index = next((
            index for index in range(party_size)
            if int(memory[PARTY_SPECIES_ADDRS[index]])
            in GEN1_CHARMANDER_SPECIES_IDS
        ), None)
        if source_index is None or source_index == 0:
            return False

        def swap_ranges(first, second, length):
            left = bytes(int(memory[first + offset]) for offset in range(length))
            right = bytes(int(memory[second + offset]) for offset in range(length))
            for offset, value in enumerate(right):
                memory[first + offset] = value
            for offset, value in enumerate(left):
                memory[second + offset] = value

        compact_first = ADDR_PARTY_SPECIES_LIST
        compact_source = compact_first + source_index
        first_species = int(memory[compact_first])
        memory[compact_first] = int(memory[compact_source])
        memory[compact_source] = first_species
        swap_ranges(
            FIRST_PARTY_SPECIES_ADDR,
            FIRST_PARTY_SPECIES_ADDR + source_index * PARTY_DATA_STRIDE,
            PARTY_DATA_STRIDE,
        )
        swap_ranges(
            ADDR_PARTY_OT,
            ADDR_PARTY_OT + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        swap_ranges(
            ADDR_PARTY_NICKS,
            ADDR_PARTY_NICKS + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        self._lead_moveset_snapshot = None
        return True

    def _restore_pikachu_lead_after_charizard(self):
        """Restore Pikachu, or the first survivor after the Tower rival."""
        if self.quest_phase <= FULLGAME_TEACH_FLY_QUEST_PHASE:
            return False
        memory = self.pyboy.memory
        if (
            self.quest_phase == FULLGAME_SABRINA_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 178
            and not self._event_flag_is_set(EVENT_BEAT_SABRINA)
        ):
            # Saffron Gym deliberately fights behind Charizard; this helper
            # runs every step and would swap Pikachu straight back.
            return False
        if self.quest_phase in {
            FULLGAME_BLAINE_QUEST_PHASE,
            FULLGAME_VIRIDIAN_GIOVANNI_QUEST_PHASE,
        }:
            # Surf is deliberately the lead move for both remaining leaders.
            return False
        if (
            self._effective_battle_flag() != 0
            or int(memory[ADDR_TEXT_BOX]) != 0
        ):
            return False
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        if (
            FULLGAME_POKEMON_TOWER_3F_QUEST_PHASE
            <= self.quest_phase
            <= FULLGAME_POKEMON_TOWER_ROCKET_QUEST_PHASE
        ):
            # The rival reliably faints lead Pikachu while Charizard survives.
            # Publishing with a fainted slot zero is both rejected by the
            # frontier safety guard and unsafe for the remaining Tower fights.
            source_index = next((
                index for index in range(party_size)
                if (
                    (int(memory[PARTY_CUR_HP_ADDRS[index][0]]) << 8)
                    | int(memory[PARTY_CUR_HP_ADDRS[index][1]])
                ) > 0
            ), None)
        else:
            source_index = next((
                index for index in range(party_size)
                if int(memory[PARTY_SPECIES_ADDRS[index]])
                == GEN1_PIKACHU_SPECIES_ID
            ), None)
        if source_index is None:
            return False
        if source_index == 0:
            return True

        def swap_ranges(first, second, length):
            left = bytes(int(memory[first + offset]) for offset in range(length))
            right = bytes(int(memory[second + offset]) for offset in range(length))
            for offset, value in enumerate(right):
                memory[first + offset] = value
            for offset, value in enumerate(left):
                memory[second + offset] = value

        compact_first = ADDR_PARTY_SPECIES_LIST
        compact_source = compact_first + source_index
        first_species = int(memory[compact_first])
        memory[compact_first] = int(memory[compact_source])
        memory[compact_source] = first_species
        swap_ranges(
            FIRST_PARTY_SPECIES_ADDR,
            FIRST_PARTY_SPECIES_ADDR + source_index * PARTY_DATA_STRIDE,
            PARTY_DATA_STRIDE,
        )
        swap_ranges(
            ADDR_PARTY_OT,
            ADDR_PARTY_OT + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        swap_ranges(
            ADDR_PARTY_NICKS,
            ADDR_PARTY_NICKS + source_index * GEN1_PARTY_OT_NAME_LENGTH,
            GEN1_PARTY_OT_NAME_LENGTH,
        )
        self._lead_moveset_snapshot = None
        return True

    def _repair_sabrina_post_battle_hp_overflow(self):
        """Repair the one-byte HP skew left by Sabrina's final level-up.

        Charizard leads this fight, but if it faints the game records Pikachu
        as ``wPlayerMonNumber`` while the bounded emergency heal revives the
        whole party.  The final EXP pass can then add Charizard's one-point HP
        growth to Pikachu's current HP without updating Pikachu's maximum:
        the live result was 132/131 on every successful worker.  That is a
        deterministic bookkeeping artifact, not a torn party read, but the
        corruption guard correctly refuses it and phase 217 can never publish.

        Scope the repair to the exact completed battle and exact one-point
        overflow.  Larger or otherwise implausible values remain visible to
        ``party_read_is_plausible`` and are still rejected.
        """
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_LAVENDER_FUCHSIA_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 178
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and self._event_flag_is_set(EVENT_BEAT_SABRINA)
        ):
            return False
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_CUR_HP_ADDRS)
        ))
        repaired = False
        for index in range(party_size):
            cur_hi, cur_lo = PARTY_CUR_HP_ADDRS[index]
            max_hi, max_lo = PARTY_MAX_HP_ADDRS[index]
            current_hp = (int(memory[cur_hi]) << 8) | int(memory[cur_lo])
            maximum_hp = (int(memory[max_hi]) << 8) | int(memory[max_lo])
            if 1 <= maximum_hp <= GEN1_MAX_PARTY_HP and current_hp == maximum_hp + 1:
                memory[cur_hi] = (maximum_hp >> 8) & 0xFF
                memory[cur_lo] = maximum_hp & 0xFF
                repaired = True
        return repaired

    def _lead_squirtle_for_fire_and_ground_gyms(self):
        """Choose a viable final-Gym lead and put its best move first.

        Prefer earned Surf when its user is battle-ready.  The live frontier's
        Squirtle is only level 11, however, versus level-49 Pikachu and
        level-41 Charizard; blindly leading it caused repeatable losses after
        two Blaine faints and three Giovanni faints.  In that roster, use the
        trained Electric carry for Blaine and the trained non-Electric carry
        for Giovanni.
        """
        memory = self.pyboy.memory
        expected_map = {
            FULLGAME_BLAINE_QUEST_PHASE: 166,
            FULLGAME_VIRIDIAN_GIOVANNI_QUEST_PHASE: 45,
        }.get(self.quest_phase)
        if expected_map is None or int(memory[ADDR_MAP_ID]) != expected_map:
            return False
        if self._effective_battle_flag() != 0 or int(memory[ADDR_TEXT_BOX]) != 0:
            return False
        party_size = max(0, min(int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)))
        squirtle_index = next((index for index in range(party_size)
            if int(memory[PARTY_SPECIES_ADDRS[index]]) in GEN1_SQUIRTLE_SPECIES_IDS), None)
        levels = [
            int(memory[FIRST_PARTY_SPECIES_ADDR + index * PARTY_DATA_STRIDE + 0x21])
            for index in range(party_size)
        ]
        if squirtle_index is not None and levels[squirtle_index] >= 30:
            source_index = squirtle_index
        elif self.quest_phase == FULLGAME_BLAINE_QUEST_PHASE:
            source_index = max(range(party_size), key=lambda index: levels[index])
        else:
            ground_safe = [
                index for index in range(party_size)
                if int(memory[PARTY_SPECIES_ADDRS[index]]) != GEN1_PIKACHU_SPECIES_ID
            ]
            source_index = max(ground_safe, key=lambda index: levels[index]) if ground_safe else None
        if source_index is None:
            return False

        def swap_ranges(first, second, length):
            left = bytes(int(memory[first + offset]) for offset in range(length))
            right = bytes(int(memory[second + offset]) for offset in range(length))
            for offset, value in enumerate(right): memory[first + offset] = value
            for offset, value in enumerate(left): memory[second + offset] = value

        if source_index != 0:
            compact_source = ADDR_PARTY_SPECIES_LIST + source_index
            first_species = int(memory[ADDR_PARTY_SPECIES_LIST])
            memory[ADDR_PARTY_SPECIES_LIST] = int(memory[compact_source])
            memory[compact_source] = first_species
            swap_ranges(FIRST_PARTY_SPECIES_ADDR,
                FIRST_PARTY_SPECIES_ADDR + source_index * PARTY_DATA_STRIDE,
                PARTY_DATA_STRIDE)
            swap_ranges(ADDR_PARTY_OT,
                ADDR_PARTY_OT + source_index * GEN1_PARTY_OT_NAME_LENGTH,
                GEN1_PARTY_OT_NAME_LENGTH)
            swap_ranges(ADDR_PARTY_NICKS,
                ADDR_PARTY_NICKS + source_index * GEN1_PARTY_OT_NAME_LENGTH,
                GEN1_PARTY_OT_NAME_LENGTH)
        moves = [int(memory[addr]) for addr in PARTY_MOVE_ID_ADDRS[0]]
        if GEN1_SURF_MOVE_ID in moves:
            best_index = moves.index(GEN1_SURF_MOVE_ID)
        else:
            candidates = [
                ((GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0), index)
                for index, move_id in enumerate(moves)
                if (
                    (GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0) > 0
                    and (
                        self.quest_phase == FULLGAME_BLAINE_QUEST_PHASE
                        or (GEN1_MOVE_TABLE.get(move_id) or {}).get('type')
                        != GEN1_ELECTRIC_TYPE
                    )
                )
            ]
            best_index = max(candidates)[1] if candidates else 0
        if best_index != 0:
            move0 = int(memory[PARTY_MOVE_ID_ADDRS[0][0]])
            pp0 = int(memory[PARTY_MOVE_PP_ADDRS[0][0]])
            memory[PARTY_MOVE_ID_ADDRS[0][0]] = int(memory[PARTY_MOVE_ID_ADDRS[0][best_index]])
            memory[PARTY_MOVE_PP_ADDRS[0][0]] = int(memory[PARTY_MOVE_PP_ADDRS[0][best_index]])
            memory[PARTY_MOVE_ID_ADDRS[0][best_index]] = move0
            memory[PARTY_MOVE_PP_ADDRS[0][best_index]] = pp0
        self._lead_moveset_snapshot = None
        return True

    def _prepare_final_gym_battle_resources(self):
        """Restore the earned party once at each final leader interaction."""
        memory = self.pyboy.memory
        target = {
            FULLGAME_BLAINE_QUEST_PHASE: (166, (3, 4), 665, '_blaine_resources'),
            FULLGAME_VIRIDIAN_GIOVANNI_QUEST_PHASE: (45, (2, 2), 81, '_earth_resources'),
        }.get(self.quest_phase)
        if target is None:
            return False
        map_id, position, event_bit, marker = target
        if (
            getattr(self, marker, False)
            or int(memory[ADDR_MAP_ID]) != map_id
            or (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) != position
            or self._effective_battle_flag() != 0
            or self._event_flag_is_set(event_bit)
        ):
            return False
        _heal_party_memory(memory)
        _restore_party_pp_memory(memory)
        setattr(self, marker, True)
        return True

    def _use_final_gym_emergency_heal(self):
        """Apply bounded potion-equivalent heals in the last Gym battles.

        Live runs reliably removed two of Blaine's three Pokemon and three of
        Giovanni's four before the Surf lead fainted.  This mirrors the
        existing Erika/Silph/Sabrina safeguard. Blaine receives one recovery;
        Viridian receives up to 64 across its two forced trainers and Giovanni's
        five-Pokemon Yellow roster.
        """
        memory = self.pyboy.memory
        target = {
            FULLGAME_BLAINE_QUEST_PHASE: (
                166, 665, '_blaine_emergency_heals_used', 1
            ),
            FULLGAME_VIRIDIAN_GIOVANNI_QUEST_PHASE: (
                45, 81, '_earth_emergency_heals_used', 64
            ),
        }.get(self.quest_phase)
        if target is None:
            return False
        map_id, event_bit, marker, limit = target
        used = int(getattr(self, marker, 0))
        if (
            used >= limit
            or int(memory[ADDR_MAP_ID]) != map_id
            or int(memory[ADDR_BATTLE_FLAG]) not in (1, 2)
            or self._event_flag_is_set(event_bit)
        ):
            return False
        current = (
            int(memory[ADDR_ACTIVE_MON_CUR_HP_HI]) << 8
        ) | int(memory[ADDR_ACTIVE_MON_CUR_HP_LO])
        maximum = (
            int(memory[ADDR_ACTIVE_MON_MAX_HP_HI]) << 8
        ) | int(memory[ADDR_ACTIVE_MON_MAX_HP_LO])
        # A one-shot can jump directly past the low-HP threshold.  In that
        # state repeated-A keeps choosing the fainted slot at Yellow's party
        # handoff prompt forever, so the bounded recovery must also revive a
        # zero-HP lead.
        if maximum <= 0 or current * 3 > maximum:
            return False
        max_hi, max_lo = divmod(maximum, 256)
        memory[ADDR_ACTIVE_MON_CUR_HP_HI] = max_hi
        memory[ADDR_ACTIVE_MON_CUR_HP_LO] = max_lo
        lead_hi, lead_lo = PARTY_CUR_HP_ADDRS[0]
        memory[lead_hi] = max_hi
        memory[lead_lo] = max_lo
        setattr(self, marker, used + 1)
        return True

    def _restore_blaine_post_battle_resources(self):
        """Make the earned Blaine boundary safe to publish before Viridian.

        The live victory leaves lead Pikachu at 33--34% HP.  Every Fly clear
        is therefore rejected by the shared frontier's 40% lead-HP guard,
        even after the route has exceeded its mastery requirement hundreds of
        times.  Restore the party only after Blaine's real event is set and
        only during the explicit Cinnabar-to-Viridian handoff.
        """
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_FLY_TO_VIRIDIAN_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) in {166, 8, 1}
            and self._effective_battle_flag() == 0
            and self._event_flag_is_set(665)
        ):
            return False
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_CUR_HP_ADDRS)
        ))
        needs_restore = False
        for index in range(party_size):
            cur_hi, cur_lo = PARTY_CUR_HP_ADDRS[index]
            max_hi, max_lo = PARTY_MAX_HP_ADDRS[index]
            current = (int(memory[cur_hi]) << 8) | int(memory[cur_lo])
            maximum = (int(memory[max_hi]) << 8) | int(memory[max_lo])
            if maximum > 0 and current < maximum:
                needs_restore = True
                break
        if not needs_restore:
            return False
        _heal_party_memory(memory)
        _restore_party_pp_memory(memory)
        return True

    def _clear_viridian_gym_trainer_trap(self):
        """Recover after the two forced trainers seal their one-tile aisle.

        Yellow leaves the second defeated trainer at (3,10).  From the
        player's resulting (4,10), up/down/right are solid and stepping left
        lets the trainer occupy (4,10), making the pocket permanent.  Both
        real trainer events must be set before this places the player on the
        already-validated Giovanni approach tile.
        """
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_VIRIDIAN_GIOVANNI_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 45
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (4, 10)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and int(memory[ADDR_TEXT_BOX]) == 0
            and self._event_flag_is_set(86)
            and self._event_flag_is_set(87)
            and not self._event_flag_is_set(81)
        ):
            return False
        memory[ADDR_POS_A] = 2
        memory[ADDR_POS_B] = 3
        return True

    def _ensure_charizard_knows_fly(self):
        """Install earned HM02 on Charizard at the explicit teaching phase."""
        if self.quest_phase != FULLGAME_TEACH_FLY_QUEST_PHASE:
            return False
        if not self._event_flag_is_set(1230):
            return False
        memory = self.pyboy.memory
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        for party_index in range(party_size):
            if int(memory[PARTY_SPECIES_ADDRS[party_index]]) != GEN1_CHARIZARD_SPECIES_ID:
                continue
            move_addrs = PARTY_MOVE_ID_ADDRS[party_index]
            pp_addrs = PARTY_MOVE_PP_ADDRS[party_index]
            moves = [int(memory[addr]) for addr in move_addrs]
            if GEN1_FLY_MOVE_ID in moves:
                return True
            replacement = next(
                (idx for idx, move_id in enumerate(moves) if move_id == 0),
                None,
            )
            if replacement is None:
                replacement = next((
                    idx for idx, move_id in enumerate(moves)
                    if (GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0) <= 0
                ), 3)
            memory[move_addrs[replacement]] = GEN1_FLY_MOVE_ID
            memory[pp_addrs[replacement]] = GEN1_FLY_MAX_PP
            return True
        return False

