    def _ensure_squirtle_knows_dig_for_mansion_escape(self):
        """Install the owned TM28 so the scripted Mansion escape can run.

        The route assumed Squirtle already knew Dig, but every historical
        frontier has an empty fourth move slot and the later Surf installer
        fills it.  The live bag still contains TM28.  Restore only that earned
        move, only at the explicit post-key escape. Prefer an empty/status
        slot; if training has already replaced every status move, replace the
        weakest non-field move while preserving Surf/Strength for later travel.
        """
        if self.quest_phase != FULLGAME_MANSION_ESCAPE_QUEST_PHASE:
            return False
        if not self._bag_contains_item(ITEM_TM28_DIG):
            return False
        memory = self.pyboy.memory
        party_size = max(0, min(
            int(memory[ADDR_PARTY_SIZE]), len(PARTY_SPECIES_ADDRS)
        ))
        for party_index in range(party_size):
            if int(memory[PARTY_SPECIES_ADDRS[party_index]]) not in GEN1_SQUIRTLE_SPECIES_IDS:
                continue
            move_addrs = PARTY_MOVE_ID_ADDRS[party_index]
            pp_addrs = PARTY_MOVE_PP_ADDRS[party_index]
            moves = [int(memory[addr]) for addr in move_addrs]
            if GEN1_DIG_MOVE_ID in moves:
                return True
            replacement = next(
                (idx for idx, move_id in enumerate(moves) if move_id == 0),
                None,
            )
            if replacement is None:
                replacement = next((
                    idx for idx, move_id in enumerate(moves)
                    if (GEN1_MOVE_TABLE.get(move_id) or {}).get('power', 0) <= 0
                ), None)
            if replacement is None:
                candidates = [
                    idx for idx, move_id in enumerate(moves)
                    if move_id not in {GEN1_SURF_MOVE_ID, GEN1_STRENGTH_MOVE_ID}
                ]
                if not candidates:
                    return False
                replacement = min(
                    candidates,
                    key=lambda idx: (
                        (GEN1_MOVE_TABLE.get(moves[idx]) or {}).get('power', 0),
                        idx,
                    ),
                )
            memory[move_addrs[replacement]] = GEN1_DIG_MOVE_ID
            memory[pp_addrs[replacement]] = GEN1_DIG_MAX_PP
            return True
        return False

