    def _try_toggle_mansion_statue(self):
        """Use each required statue switch with the ROM's real Yes prompt."""
        memory = self.pyboy.memory
        switch_on = self._event_flag_is_set(632)
        target = None
        desired = None
        if (
            self.quest_phase == FULLGAME_MANSION_B1F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 215
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (6, 10)
        ):
            target, desired = (6, 10), True
        elif (
            self.quest_phase == FULLGAME_SECRET_KEY_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 216
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (26, 18)
        ):
            target, desired = (26, 18), False
        elif (
            self.quest_phase == FULLGAME_SECRET_KEY_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 216
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (4, 20)
        ):
            target, desired = (4, 20), True
        if target is None:
            return False
        if switch_on != desired:
            self._tap_scripted_button('up', 24, 96)
            self._tap_scripted_button('a', 24, 128)
            self._tap_scripted_button('a', 24, 256)  # Yes
            self._tap_scripted_button('a', 24, 256)
            # The event bit is committed as the final prompt closes.
            self._tap_scripted_button('b', 8, 128)
        if self._event_flag_is_set(632) != desired:
            return False
        # Yellow keeps the final statue text/click animation active for
        # several input frames. Close with B only (A would reopen and undo the
        # switch), then take the first verified route step while this helper
        # still owns the action.
        exit_button = {(6, 10): 'down', (26, 18): 'left', (4, 20): 'right'}[target]
        for _ in range(8):
            self._tap_scripted_button('b', 8, 128)
            self._tap_scripted_button(exit_button, 8, 96)
            if (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) != target:
                return True
        return False

