    def _try_answer_cinnabar_quiz(self):
        """Answer the six gate quizzes, checking the real event after each tap."""
        memory = self.pyboy.memory
        quiz_stands = ((8, 15), (2, 10), (8, 9), (14, 9), (14, 1), (8, 1))
        if self.quest_phase not in FULLGAME_CINNABAR_QUIZ_PHASES:
            return False
        index = FULLGAME_CINNABAR_QUIZ_PHASES.index(self.quest_phase)
        event_bit = 681 + index
        if not (
            int(memory[ADDR_MAP_ID]) == 166
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == quiz_stands[index]
            and not self._event_flag_is_set(event_bit)
        ):
            return False
        answer_yes = index in {0, 4}
        self._tap_scripted_button('up', 24, 96)
        self._tap_scripted_button('a', 24, 128)
        for _ in range(14):
            if not answer_yes:
                self._tap_scripted_button('down', 8, 32)
            self._tap_scripted_button('a', 24, 256)
            if self._event_flag_is_set(event_bit):
                break
        if not self._event_flag_is_set(event_bit):
            return False
        # Quiz text can reassert its benign text byte for two movement steps.
        # Close only with B and carry out the first three replayed departure
        # actions so neither A nor a generic recovery pulse can reopen the
        # machine. The ordinary coordinate route resumes from there.
        departures = (
            ('down', 'right', 'up'),
            ('down', 'down', 'down'),
            ('down', 'down', 'down'),
            ('down', 'down', 'left'),
            ('down', 'right', 'up'),
            ('down', 'right', 'up'),
        )[index]
        for departure in departures:
            before = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
            for _ in range(8):
                self._tap_scripted_button('b', 8, 128)
                self._tap_scripted_button(departure, 8, 96)
                if (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) != before:
                    break
        return True

