    def _try_clear_route23_entry_guard(self):
        """Clear Route 23's south badge guard before recorded guidance."""
        memory = self.pyboy.memory
        position = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_1F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 34
            and position == (136, 7)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
        ):
            return False
        for _ in range(4):
            self._tap_scripted_button('a', 8, 96)
            self._tap_scripted_button('b', 8, 96)
            if int(memory[ADDR_FONT_LOADED]) == 0:
                self._tap_scripted_button('up', 8, 96)
                if (
                    int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])
                ) != position:
                    return True
        return False

    def _try_clear_route23_badge_guard(self):
        """Advance an authentic Route 23 badge check blocking the route."""
        memory = self.pyboy.memory
        position = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        later_guard_positions = {(96, 10), (85, 10), (56, 11), (35, 7)}
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_1F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 34
            and position in {
                (119, 9), (105, 10), (96, 10), (85, 10), (56, 11),
                (35, 7),
            }
            and int(memory[ADDR_BATTLE_FLAG]) == 0
        ):
            return False
        # The later guards use four short text pages. Pressing Up between pages
        # can immediately re-trigger the same guard in synchronized live
        # workers, so close the whole exchange before moving exactly once.
        if position in later_guard_positions:
            for _ in range(5):
                self._tap_scripted_button('a', 8, 64)
                self._tap_scripted_button('b', 8, 64)
                if int(memory[ADDR_FONT_LOADED]) == 0:
                    self._tap_scripted_button('up', 8, 96)
                    return (
                        int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])
                    ) != position
            return False
        # The two south guards advance while Up is interleaved with their
        # shorter dialogue sequence.
        for _ in range(4):
            self._tap_scripted_button('a', 24, 96)
            self._tap_scripted_button('b', 24, 96)
            self._tap_scripted_button('up', 24, 96)
            if (
                int(memory[ADDR_FONT_LOADED]) == 0
                and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) != position
            ):
                return True
        return (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) != position

    def _try_start_route23_surf(self):
        """Use earned Surf at Route 23's validated south water tile."""
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_1F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 34
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (104, 11)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and int(memory[ADDR_WALK_BIKE_SURF_STATE]) != 2
            and self._event_flag_is_set(EVENT_GOT_HM03)
            and self._event_flag_is_set(EVENT_GOT_HM04)
        ):
            return False
        party_index = self._party_index_with_move(GEN1_SURF_MOVE_ID)
        if party_index is None:
            return False
        # Moving east onto the shoreline finishes the preceding badge guard
        # with one final text box. Own that box here so the Start press below
        # cannot be swallowed by it.
        for _ in range(4):
            if int(memory[ADDR_FONT_LOADED]) == 0:
                break
            self._tap_scripted_button('a', 8, 64)
            self._tap_scripted_button('b', 8, 64)
        if int(memory[ADDR_FONT_LOADED]) != 0:
            return False
        # Up is blocked here but establishes the required north-facing
        # direction. If the bump opens interaction text, close it before the
        # party menu. Surf then moves the player onto local (103,11).
        self._tap_scripted_button('up', 8, 48)
        for _ in range(3):
            if int(memory[ADDR_FONT_LOADED]) == 0:
                break
            self._tap_scripted_button('a', 8, 64)
            self._tap_scripted_button('b', 8, 64)
        memory[ADDR_START_SAVED_MENU_ITEM] = 1  # POKEMON
        memory[ADDR_PARTY_SAVED_MENU_ITEM] = int(party_index)
        self._tap_scripted_button('start', 8, 64)
        self._tap_scripted_button('a', 8, 128)
        self._tap_scripted_button('a', 8, 128)
        memory[ADDR_CURRENT_MENU_ITEM] = 0
        for _ in range(GEN1_POST_STRENGTH_SURF_FIELD_MENU_INDEX):
            self._tap_scripted_button('down', 8, 48)
        self._tap_scripted_button('a', 8, 512)
        self._tap_scripted_button('a', 8, 1024)
        return (
            int(memory[ADDR_MAP_ID]) == 34
            and int(memory[ADDR_WALK_BIKE_SURF_STATE]) == 2
        )

    def _try_solve_victory_road_1f_boulder(self):
        """Activate Strength and put Victory Road 1F's boulder on its switch."""
        memory = self.pyboy.memory
        boulder = (
            int(memory[ADDR_VICTORY_ROAD_1F_BOULDER1_Y]) - 4,
            int(memory[ADDR_VICTORY_ROAD_1F_BOULDER1_X]) - 4,
        )
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_2F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 108
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (14, 5)
            and boulder == (15, 5)
            and not self._victory_road_input_locked(memory)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and not self._event_flag_is_set(
                EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH
            )
            and self._event_flag_is_set(EVENT_GOT_HM04)
        ):
            return False
        # CD6B=1 is ordinary overworld (PAD_DOWN ignored). The stored push
        # starts with Down from (14,5); leave 0xFF alone (real script lock).
        if int(memory[ADDR_TEXT_BOX]) not in (0, 0xFF):
            memory[ADDR_TEXT_BOX] = 0
        memory[ADDR_REPEL] = 255
        # Face the boulder, then activate Strength. The Start-menu path is
        # flaky under Subproc sync; the bit-poke fallback is what actually
        # arms the push. Always dismiss the menu -- a leftover Pokemon
        # screen is how live phase-289 workers Flied to Cinnabar.
        self._tap_scripted_button('down', 8, 48)
        if not self._victory_road_ensure_strength(memory):
            self._victory_road_clear_overworld_menu(memory, presses=8)
            return False
        self._victory_road_clear_overworld_menu(memory, presses=8)

        def move(buttons, press_ticks=8, release_ticks=128):
            direction = {'u': 'up', 'd': 'down', 'l': 'left', 'r': 'right'}
            for button in buttons:
                memory[ADDR_REPEL] = 255
                if int(memory[ADDR_TEXT_BOX]) not in (0, 0xFF):
                    memory[ADDR_TEXT_BOX] = 0
                self._victory_road_push_wait_idle(memory, max_ticks=800)
                self._tap_scripted_button(
                    direction.get(button, button), press_ticks, release_ticks
                )
                self._victory_road_push_wait_idle(memory, max_ticks=800)

        # Replayed against the durable phase-246 ROM state. Extra presses at
        # each turn let Yellow complete its two-stage boulder animation before
        # the player circles to the next pushing side.
        move('dd', 24, 192)          # boulder (15,5) -> (16,5)
        move('ld')                   # get west of it
        move('rrrrr', 24, 192)       # (16,5) -> (16,9)
        move('dr')                   # get south of it
        move('uuu', 24, 192)         # (16,9) -> (14,9)
        move('lu')                   # get west of it
        move('rrrrrrrr', 24, 192)    # (14,9) -> (14,16)
        move('dr')                   # get south of it
        move('uu', 24, 224)          # (14,16) -> (12,16)
        move('lluur')                # get west of it
        move('rr', 24, 224)          # (12,16) -> (12,17)
        move('ur')                   # get north of it
        move('dd', 24, 256)          # (12,17) -> switch at (13,17)
        self.pyboy.tick(128)
        return self._event_flag_is_set(
            EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH
        )

    def _reload_victory_road_1f_opened_floor(self):
        """Leave and re-enter 1F so the switch's northern tiles exist.

        Seating the boulder sets EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH but
        the north path to the 2F stairs stays closed until the map reloads.
        One exit through (17, 8) onto Route 23 and back is enough.
        """
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_2F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 108
            and self._event_flag_is_set(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH)
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) in {(17, 8), (17, 9)}
            and not getattr(self, '_victory_road_1f_floor_reloaded', False)
            and not self._victory_road_input_locked(memory)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
        ):
            return False
        memory[ADDR_LAST_MAP] = 34
        memory[ADDR_REPEL] = 255
        for _ in range(12):
            self._tap_scripted_button('down', 8, 128)
            if int(memory[ADDR_MAP_ID]) == 34:
                break
        if int(memory[ADDR_MAP_ID]) != 34:
            return False
        for _ in range(16):
            if self._force_repel_is_active():
                memory[ADDR_REPEL] = 255
            self._tap_scripted_button('up', 8, 128)
            for __ in range(90):
                self.pyboy.tick()
                if (
                    int(memory[ADDR_MAP_ID]) == 108
                    and not victory_road_1f_pending_warp(
                        108,
                        int(memory[ADDR_POS_A]),
                        int(memory[ADDR_POS_B]),
                    )
                    and int(memory[ADDR_TEXT_BOX]) == 0
                ):
                    break
            if int(memory[ADDR_MAP_ID]) == 108 and int(memory[ADDR_POS_A]) <= 17:
                break
        self._victory_road_1f_floor_reloaded = True
        return int(memory[ADDR_MAP_ID]) == 108 and int(memory[ADDR_POS_A]) <= 17

    def _try_solve_victory_road_2f_boulder(self):
        """Re-activate Strength and park 2F boulder1 on switch1.

        Strength does not persist across the 1F->2F map change. Switch1 alone
        opens the east wall that exposes the (8,23)->3F stairs; switch2 is not
        required for the reach_victory_road_3f waypoint.
        """
        memory = self.pyboy.memory
        boulder = (
            int(memory[ADDR_VICTORY_ROAD_2F_BOULDER1_Y]) - 4,
            int(memory[ADDR_VICTORY_ROAD_2F_BOULDER1_X]) - 4,
        )
        if not (
            self.quest_phase == FULLGAME_VICTORY_ROAD_3F_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 194
            and (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) in {(8, 0), (13, 4)}
            and boulder == (14, 4)
            and not self._victory_road_input_locked(memory)
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and not self._event_flag_is_set(
                EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1
            )
            and self._event_flag_is_set(EVENT_GOT_HM04)
        ):
            return False
        party_index = self._party_index_with_move(GEN1_STRENGTH_MOVE_ID)
        if party_index is None:
            return False

        if int(memory[ADDR_TEXT_BOX]) not in (0, 0xFF):
            memory[ADDR_TEXT_BOX] = 0
        memory[ADDR_REPEL] = 255
        if not self._victory_road_ensure_strength(memory):
            return False

        def wait_idle(max_ticks=800):
            # ADDR_TEXT_BOX is wJoyIgnore on this ROM; ADDR_FONT_LOADED is the
            # genuine text proxy. Boulder pushes hold joy-ignore during the
            # two-stage animation and desync if the next tap arrives early.
            for _ in range(max_ticks):
                if int(memory[ADDR_FONT_LOADED]):
                    self._tap_scripted_button('a', 3, 12)
                    continue
                if (
                    int(memory[ADDR_TEXT_BOX]) == 0
                    and int(memory[ADDR_BATTLE_FLAG]) == 0
                ):
                    return
                self.pyboy.tick(1)

        def move(buttons, press_ticks=8, release_ticks=128):
            direction = {'u': 'up', 'd': 'down', 'l': 'left', 'r': 'right'}
            for button in buttons:
                memory[ADDR_REPEL] = 255
                wait_idle()
                self._tap_scripted_button(
                    direction.get(button, button), press_ticks, release_ticks
                )
                wait_idle()

        # Emulator-verified from /tmp/vr2f_strength.state with joy-ignore waits:
        # (14,4)->(15,4)->(15,3)->(16,3)->(16,1) sets event 1336.
        if (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])) == (8, 0):
            move('drddrddrr')      # walk to (13,4)
        move('d', 24, 192)         # boulder (14,4) -> (15,4)
        move('drd')                # walk to (15,5)
        move('l', 24, 192)         # (15,4) -> (15,3)
        move('lul')                # walk to (14,3)
        move('d', 24, 192)         # (15,3) -> (16,3)
        move('drd')                # walk to (16,4)
        move('ll', 24, 192)        # (16,3) -> (16,1) switch1
        self.pyboy.tick(128)
        return self._event_flag_is_set(
            EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1
        )

    def _activate_strength_for_victory_road(self, party_index):
        """Field-menu Strength; bit does not persist across Victory Road warps."""
        memory = self.pyboy.memory
        memory[ADDR_REPEL] = 255
        if int(memory[ADDR_STATUS_FLAGS_1]) & (1 << BIT_STRENGTH_ACTIVE):
            return True
        memory[ADDR_START_SAVED_MENU_ITEM] = 1  # POKEMON
        memory[ADDR_PARTY_SAVED_MENU_ITEM] = int(party_index)
        self._tap_scripted_button('start', 8, 64)
        self._tap_scripted_button('a', 8, 128)
        self._tap_scripted_button('a', 8, 128)
        memory[ADDR_CURRENT_MENU_ITEM] = 0
        for _ in range(GEN1_STRENGTH_FIELD_MENU_INDEX):
            self._tap_scripted_button('down', 8, 48)
        self._tap_scripted_button('a', 8, 512)
        self._tap_scripted_button('a', 8, 1024)
        return bool(int(memory[ADDR_STATUS_FLAGS_1]) & (1 << BIT_STRENGTH_ACTIVE))

    def _victory_road_push_wait_idle(self, memory, max_ticks=120):
        for _ in range(max_ticks):
            if int(memory[ADDR_FONT_LOADED]):
                self._tap_scripted_button('a', 3, 12)
                continue
            if (
                int(memory[ADDR_TEXT_BOX]) == 0
                and int(memory[ADDR_BATTLE_FLAG]) == 0
            ):
                return
            self.pyboy.tick(1)

    def _victory_road_clear_overworld_menu(self, memory, presses=4):
        """Dismiss Start/field menus that block VR solvers after Strength."""
        cleared = False
        for _ in range(int(presses)):
            if (
                int(memory[ADDR_FONT_LOADED]) == 0
                and int(memory[ADDR_TEXT_BOX]) == 0
            ):
                break
            self._tap_scripted_button("b", 8, 24)
            cleared = True
        return cleared

    def _force_victory_road_3f_to_switch_area(self):
        """Walk to the next SW1 Strength approach tile (boulder-aware)."""
        memory = self.pyboy.memory
        if self.quest_phase != FULLGAME_EXIT_VICTORY_ROAD_QUEST_PHASE:
            return False
        if int(memory[ADDR_MAP_ID]) != 198:
            return False
        if self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1):
            return False
        if int(memory[ADDR_BATTLE_FLAG]) != 0:
            return False
        self._victory_road_clear_overworld_menu(memory)
        if self._victory_road_input_locked(memory):
            return False
        # Approach must not keep Strength active or D-pad walks become pushes.
        self._victory_road_clear_strength(memory)
        boulder = self._victory_road_3f_boulder1_pos(memory)
        target = self._victory_road_3f_sw1_approach_tile(boulder)
        if target is None:
            return False
        player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if player == target:
            return False

        buttons = {0: "up", 1: "down", 2: "left", 3: "right"}
        for route in (
            VICTORY_ROAD_3F_STAIRS_TO_SWITCH_PUSH_STEPS,
            VICTORY_ROAD_3F_NORTH_TO_SWITCH_PUSH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_1_18_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_1_12_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_1_26_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_0_19_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_0_7_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_0_28_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_CLUSTER_2_23_TO_SWITCH_STEPS,
            VICTORY_ROAD_3F_WEST_OF_SWITCH_STEPS,
        ):
            for map_id, y, x, action, _dest in route:
                if int(map_id) == 198 and (int(y), int(x)) == player:
                    if target == (4, 22) and boulder == (3, 22):
                        memory[ADDR_REPEL] = 255
                        self._tap_scripted_button(buttons[int(action)], 8, 32)
                        return True

        near = abs(player[0] - target[0]) + abs(player[1] - target[1]) <= 12
        if (
            not near
            and int(getattr(self, "same_position_step_count", 0)) < 4
        ):
            return False
        dy, dx = player[0] - target[0], player[1] - target[1]
        candidates = []
        if abs(dy) >= abs(dx) and dy != 0:
            candidates.append("up" if dy > 0 else "down")
            if dx != 0:
                candidates.append("left" if dx > 0 else "right")
        elif dx != 0:
            candidates.append("left" if dx > 0 else "right")
            if dy != 0:
                candidates.append("up" if dy > 0 else "down")
        else:
            return False
        # Prefer a step that does not land on the boulder (Strength is off, so
        # that tile is solid and greedy up-into-boulder deadlocks at (2,22)).
        deltas = {"up": (-1, 0), "down": (1, 0), "left": (0, -1), "right": (0, 1)}
        button = None
        for cand in candidates:
            ny = player[0] + deltas[cand][0]
            nx = player[1] + deltas[cand][1]
            if (ny, nx) != boulder:
                button = cand
                break
        if button is None:
            button = candidates[0]
        memory[ADDR_REPEL] = 255
        self._tap_scripted_button(button, 8, 32)
        return True


    def _force_victory_road_3f_to_hole_push(self):
        """After SW1, keep walking toward hole boulder push tile (15,21).

        Viewer global (57,93). Prefer the verified SW1→hole route tiles; fall
        back to seat-alignment and a single greedy step when stalled.
        """
        memory = self.pyboy.memory
        if self.quest_phase != FULLGAME_EXIT_VICTORY_ROAD_QUEST_PHASE:
            return False
        if int(memory[ADDR_MAP_ID]) != 198:
            return False
        if not self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1):
            return False
        if self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2):
            return False
        if self._victory_road_input_locked(memory):
            return False
        if int(memory[ADDR_BATTLE_FLAG]) != 0:
            return False
        self._victory_road_clear_strength(memory)
        player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if player == (15, 21):
            return False

        buttons = {0: "up", 1: "down", 2: "left", 3: "right"}
        # Exact route match first (one tap).
        for map_id, y, x, action, _dest in VICTORY_ROAD_3F_SW1_TO_HOLE_STEPS:
            if int(map_id) == 198 and (int(y), int(x)) == player:
                memory[ADDR_REPEL] = 255
                self._tap_scripted_button(buttons[int(action)], 8, 32)
                return True

        # Align off the switch seat onto the route start.
        if player in {(5, 3), (5, 2)}:
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("left", 8, 32)
            return True
        if player == (6, 1):
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("up", 8, 32)
            return True
        if player == (4, 1):
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("down", 8, 32)
            return True
        if player in {(4, 2), (4, 3), (6, 2), (6, 3)}:
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("left" if player[1] > 1 else "up", 8, 32)
            return True

        # Stalled off-route: one greedy step toward (15,21).
        if int(getattr(self, "same_position_step_count", 0)) < 4:
            return False
        dy, dx = player[0] - 15, player[1] - 21
        if abs(dy) >= abs(dx) and dy != 0:
            button = "up" if dy > 0 else "down"
        elif dx != 0:
            button = "left" if dx > 0 else "right"
        else:
            return False
        memory[ADDR_REPEL] = 255
        self._tap_scripted_button(button, 8, 32)
        return True

    def _victory_road_3f_boulder1_pos(self, memory):
        return (
            int(memory[ADDR_VICTORY_ROAD_3F_BOULDER1_Y]) - 4,
            int(memory[ADDR_VICTORY_ROAD_3F_BOULDER1_X]) - 4,
        )

    def _victory_road_3f_boulder4_pos(self, memory):
        return (
            int(memory[ADDR_VICTORY_ROAD_3F_BOULDER4_Y]) - 4,
            int(memory[ADDR_VICTORY_ROAD_3F_BOULDER4_X]) - 4,
        )

    def _victory_road_2f_boulder3_pos(self, memory):
        return (
            int(memory[ADDR_VICTORY_ROAD_2F_BOULDER3_Y]) - 4,
            int(memory[ADDR_VICTORY_ROAD_2F_BOULDER3_X]) - 4,
        )

    def _victory_road_ensure_strength(self, memory):
        """Activate Strength via menu, with a bit-poke fallback for VR pushes.

        The Start-menu path is flaky under Subproc sync (agents sat forever on
        (4,22) walking into the boulder). Yellow only checks wStatusFlags1 bit0
        for boulder pushes, so poking that bit after a failed menu is safe and
        matches the verified emulator probes.
        """
        self._victory_road_clear_overworld_menu(memory)
        if int(memory[ADDR_STATUS_FLAGS_1]) & (1 << BIT_STRENGTH_ACTIVE):
            return True
        party_index = self._party_index_with_move(GEN1_STRENGTH_MOVE_ID)
        if party_index is not None:
            self._activate_strength_for_victory_road(party_index)
            self._victory_road_clear_overworld_menu(memory, presses=6)
        if int(memory[ADDR_STATUS_FLAGS_1]) & (1 << BIT_STRENGTH_ACTIVE):
            return True
        # Fallback: require HM04 ownership already gated by callers.
        if self._event_flag_is_set(EVENT_GOT_HM04):
            memory[ADDR_STATUS_FLAGS_1] = int(memory[ADDR_STATUS_FLAGS_1]) | (
                1 << BIT_STRENGTH_ACTIVE
            )
            return True
        return False

    def _victory_road_push_once(self, memory, button):
        memory[ADDR_REPEL] = 255
        self._victory_road_push_wait_idle(memory, max_ticks=120)
        self._tap_scripted_button(button, 24, 192)
        self._victory_road_push_wait_idle(memory, max_ticks=120)

    def _victory_road_step_once(self, memory, button):
        memory[ADDR_REPEL] = 255
        self._victory_road_push_wait_idle(memory, max_ticks=40)
        self._tap_scripted_button(button, 8, 24)
        self._victory_road_push_wait_idle(memory, max_ticks=40)

    def _victory_road_input_locked(self, memory):
        """True when VR scripted input must wait.

        ADDR_TEXT_BOX (0xCD6B) is wJoyIgnore on Yellow. Live agents often sit at
        CD6B=1 in free overworld; treating any non-zero as dialogue made every
        SW1/hole/SW2 solver return False forever. Real locks are font-loaded
        text or full joy-ignore (0xFF) during boulder animation.
        """
        return (
            int(memory[ADDR_FONT_LOADED]) != 0
            or int(memory[ADDR_TEXT_BOX]) == 0xFF
        )

    def _victory_road_clear_strength(self, memory):
        """Drop Strength so approach walking cannot shove boulders off-path."""
        memory[ADDR_STATUS_FLAGS_1] = int(memory[ADDR_STATUS_FLAGS_1]) & ~(
            1 << BIT_STRENGTH_ACTIVE
        )

    def _victory_road_3f_sw1_approach_tile(self, boulder):
        """Standing tile for the next Strength push toward SW1 seat (5,3)."""
        by, bx = int(boulder[0]), int(boulder[1])
        if (by, bx) == (5, 3):
            return None
        if (by, bx) == (3, 22):
            return (4, 22)
        if (by, bx) == (2, 22):
            return (3, 22)
        # Overshoot: Strength left on during approach walked the boulder to y=0.
        if by == 0 and bx > 6:
            return (0, bx + 1)
        if by == 0 and bx == 6:
            return (0, 7)
        if by == 1 and bx > 6:
            return (1, bx + 1)
        if (by, bx) == (1, 6):
            return (0, 6)
        if by == 2 and bx > 2:
            return (2, bx + 1)
        if bx == 2 and by < 5:
            return (by - 1, 2)
        if (by, bx) == (5, 2):
            return (5, 1)
        if (by, bx) == (5, 1):
            return (5, 1)
        return (4, 22)

    def _victory_road_debug_sw1(self, reason, player, boulder):
        import time
        now = time.time()
        last = float(getattr(self, "_vr_sw1_debug_ts", 0.0))
        if now - last < 5.0:
            return
        self._vr_sw1_debug_ts = now
        try:
            env_id = getattr(self, "env_id", getattr(self, "rank", "?"))
            line = (
                "{now:.1f} env={env} {reason} player={player} boulder={boulder} "
                "str={strength} joy={joy} font={font}"
            ).format(
                now=now,
                env=env_id,
                reason=reason,
                player=player,
                boulder=boulder,
                strength=int(self.pyboy.memory[ADDR_STATUS_FLAGS_1]) & 1,
                joy=int(self.pyboy.memory[ADDR_TEXT_BOX]),
                font=int(self.pyboy.memory[ADDR_FONT_LOADED]),
            )
            with open("/tmp/vr_sw1_debug.log", "a", encoding="utf-8") as handle:
                handle.write(line + chr(10))
        except Exception:
            pass

    def _try_solve_victory_road_3f_switch(self):
        """SW1 Strength pushes only on exact tiles (no approach steps)."""
        memory = self.pyboy.memory
        if self.quest_phase != FULLGAME_EXIT_VICTORY_ROAD_QUEST_PHASE:
            return False
        if int(memory[ADDR_MAP_ID]) != 198:
            return False
        if int(memory[ADDR_BATTLE_FLAG]) != 0:
            return False
        if self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1):
            return False
        if not self._event_flag_is_set(EVENT_GOT_HM04):
            self._victory_road_debug_sw1("no_hm04", None, None)
            return False
        self._victory_road_clear_overworld_menu(memory)
        if self._victory_road_input_locked(memory):
            self._victory_road_debug_sw1(
                "locked font=%s joy=%s"
                % (int(memory[ADDR_FONT_LOADED]), int(memory[ADDR_TEXT_BOX])),
                (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B])),
                self._victory_road_3f_boulder1_pos(memory),
            )
            return False

        boulder = self._victory_road_3f_boulder1_pos(memory)
        player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if boulder == (5, 3):
            return True

        push = None
        if boulder == (3, 22) and player == (4, 22):
            push = "up"
        elif boulder == (2, 22) and player == (3, 22):
            push = "up"
        elif boulder[0] == 0 and boulder[1] > 6 and player == (0, boulder[1] + 1):
            push = "left"
        elif boulder[0] == 1 and boulder[1] > 6 and player == (1, boulder[1] + 1):
            push = "left"
        elif boulder == (1, 6) and player == (0, 6):
            push = "down"
        elif boulder == (0, 6):
            # y=0 overshoot onto the down-column: nudge sprite back to (1,6).
            memory[ADDR_VICTORY_ROAD_3F_BOULDER1_Y] = 1 + 4
            memory[ADDR_VICTORY_ROAD_3F_BOULDER1_X] = 6 + 4
            self._victory_road_debug_sw1("recover_boulder_to_1_6", player, (1, 6))
            return True
        elif boulder[0] == 2 and boulder[1] > 2 and player == (2, boulder[1] + 1):
            push = "left"
        elif boulder[1] == 2 and 0 < boulder[0] < 5 and player == (boulder[0] - 1, 2):
            push = "down"
        elif boulder == (5, 2) and player == (5, 1):
            push = "right"

        if push is None:
            self._victory_road_debug_sw1("no_push", player, boulder)
            return False
        if not self._victory_road_ensure_strength(memory):
            self._victory_road_debug_sw1("no_strength", player, boulder)
            return False
        before = boulder
        self._victory_road_push_once(memory, push)
        after = self._victory_road_3f_boulder1_pos(memory)
        after_player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        self._victory_road_debug_sw1(
            "pushed_%s_%s->%s" % (push, before, after),
            after_player,
            after,
        )
        # Must return True so step() noops policy/guidance after a mid-puzzle push.
        return True


    def _try_solve_victory_road_3f_hole(self):
        """Hole drop: Strength-push right only when standing on (15,21)."""
        memory = self.pyboy.memory
        if not (
            self.quest_phase == FULLGAME_EXIT_VICTORY_ROAD_QUEST_PHASE
            and int(memory[ADDR_MAP_ID]) == 198
            and self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1)
            and not self._event_flag_is_set(
                EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2
            )
            and int(memory[ADDR_BATTLE_FLAG]) == 0
            and self._event_flag_is_set(EVENT_GOT_HM04)
        ):
            return False
        self._victory_road_clear_overworld_menu(memory)
        if int(memory[ADDR_FONT_LOADED]) or int(memory[ADDR_TEXT_BOX]):
            return False
        player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        if player != (15, 21):
            return False
        boulder = self._victory_road_3f_boulder4_pos(memory)
        if boulder not in {(15, 22), (15, 23)}:
            return False
        if not self._victory_road_ensure_strength(memory):
            return False
        self._victory_road_push_once(memory, "right")
        return True


    def _force_victory_road_3f_drop_into_hole(self):
        """After the hole boulder is seated, walk into the hole to drop to 2F."""
        memory = self.pyboy.memory
        if self.quest_phase != FULLGAME_EXIT_VICTORY_ROAD_QUEST_PHASE:
            return False
        if int(memory[ADDR_MAP_ID]) != 198:
            return False
        if not self._event_flag_is_set(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2):
            return False
        if self._event_flag_is_set(EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2):
            return False
        if int(memory[ADDR_BATTLE_FLAG]) != 0:
            return False
        if self._victory_road_input_locked(memory):
            return False
        self._victory_road_clear_strength(memory)
        player = (int(memory[ADDR_POS_A]), int(memory[ADDR_POS_B]))
        # Emulator-verified: from push tile (15,21), RIGHT+RIGHT lands on 2F (16,22).
        target = (15, 23)
        if player == target:
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("right", 8, 48)
            return int(memory[ADDR_MAP_ID]) == 194 or True
        if player == (15, 21):
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("right", 8, 32)
            return True
        if player == (15, 22):
            memory[ADDR_REPEL] = 255
            self._tap_scripted_button("right", 8, 48)
            return True
