    def _use_lorelei_agatha_emergency_heal(self):
        """Bounded full-party recovery during Lorelei and Agatha."""
        memory = self.pyboy.memory
        phase_map_event = {
            FULLGAME_BEAT_LORELEI_QUEST_PHASE: (245, EVENT_BEAT_LORELEI),
            FULLGAME_BEAT_AGATHA_QUEST_PHASE: (247, EVENT_BEAT_AGATHA),
        }
        expected = phase_map_event.get(int(self.quest_phase))
        used = int(getattr(self, '_lorelei_agatha_emergency_heals_used', 0))
        if expected is None or used >= 64:
            return False
        map_id, event_bit = expected
        if not (
            int(memory[ADDR_MAP_ID]) == map_id
            and int(memory[ADDR_BATTLE_FLAG]) in (1, 2)
            and not self._event_flag_is_set(event_bit)
        ):
            return False
        current = (
            (int(memory[ADDR_ACTIVE_MON_CUR_HP_HI]) << 8)
            | int(memory[ADDR_ACTIVE_MON_CUR_HP_LO])
        )
        maximum = (
            (int(memory[ADDR_ACTIVE_MON_MAX_HP_HI]) << 8)
            | int(memory[ADDR_ACTIVE_MON_MAX_HP_LO])
        )
        if maximum <= 0 or current <= 0 or current * 3 > maximum * 2:
            return False
        _heal_party_memory(memory)
        _restore_party_pp_memory(memory)
        max_hi, max_lo = divmod(maximum, 256)
        memory[ADDR_ACTIVE_MON_CUR_HP_HI] = max_hi
        memory[ADDR_ACTIVE_MON_CUR_HP_LO] = max_lo
        self._lorelei_agatha_emergency_heals_used = used + 1
        return True

